QT_ISI(7,{"751":["(Sesungguhnya kamu dapati) wahai Muhammad (orang-orang yang paling keras permusuhannya terhadap orang-orang yang beriman ialah orang-orang Yahudi dan orang-orang musyrik) dari kalangan penduduk Mekah oleh sebab menebalnya kekafiran mereka, kebodohan mereka dan tenggelamnya mereka dalam hawa nafsu (dan sesungguhnya kamu dapati yang paling dekat persahabatannya dengan orang-orang yang beriman ialah orang-orang yang berkata, \"Sesungguhnya kami ini orang Nasrani.\" Yang demikian itu) maksudnya kecintaan mereka begitu dekat terhadap orang-orang mukmin (disebabkan karena) oleh karena (di antara mereka/orang-orang Nasrani terdapat pendeta-pendeta) ulama-ulama agama Nasrani (dan rahib-rahib) orang-orang ahli ibadah Nasrani (juga karena sesungguhnya mereka tidak menyombongkan diri) untuk mengikuti barang yang hak tidak sebagaimana orang-orang Yahudi dan kaum musyrikin penduduk Mekah yang menyombongkan diri. Ayat ini diturunkan berkenaan dengan utusan raja Najasyi yang datang dari negeri Habasyah untuk menemui kaum Muslimin. Kemudian Nabi saw. membacakan surah Yasin kepada mereka setelah itu mereka menangis dan masuk Islam semuanya seraya mengatakan, \"Alangkah miripnya bacaan ini dengan apa yang telah diturunkan kepada Nabi Isa.\" Allah swt. berfirman:",[["۞ لَتَجِدَنَّ","Pasti kamu akan dapati"],["أَشَدَّ","terkuat"],["ٱلنَّاسِ","(daripada) rakyat"],["عَدَٰوَةًۭ","(dalam) permusuhan"],["لِّلَّذِينَ","kepada mereka yang"],["ءَامَنُوا۟","beriman"],["ٱلْيَهُودَ","orang Yahudi"],["وَٱلَّذِينَ","dan orang yang"],["أَشْرَكُوا۟ ۖ","(adalah) orang musyrik"],["وَلَتَجِدَنَّ","dan pasti kamu akan dapati"],["أَقْرَبَهُم","terdekat daripada mereka"],["مَّوَدَّةًۭ","(dalam) kasih sayang"],["لِّلَّذِينَ","kepada mereka yang"],["ءَامَنُوا۟","beriman"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّا","Kami"],["نَصَـٰرَىٰ ۚ","(adalah) orang Kristian"],["ذَٰلِكَ","Itu (ialah)"],["بِأَنَّ","kerana"],["مِنْهُمْ","antara mereka"],["قِسِّيسِينَ","(adalah) imam"],["وَرُهْبَانًۭا","dan sami"],["وَأَنَّهُمْ","dan bahawa mereka"],["لَا","(adalah) tidak"],["يَسْتَكْبِرُونَ","sombong"]]],"752":["(Dan apabila mereka mendengarkan apa yang diturunkan kepada Rasul) yaitu sebagian dari Alquran (kamu lihat mata mereka mencucurkan air mata disebabkan kebenaran Alquran yang telah mereka ketahui dari kitab-kitab mereka sendiri, seraya berkata, \"Ya Tuhan kami! Kami telah beriman) kami telah percaya kepada Nabi-Mu dan Kitab-Mu (maka catatlah kami bersama orang-orang yang menjadi saksi -atas kebenaran Alquran dan kenabian Nabi Muhammad-.\") orang-orang yang mengakui dirinya beriman kepada keduanya.",[["وَإِذَا","Dan apabila"],["سَمِعُوا۟","mereka mendengar"],["مَآ","(kepada) apa"],["أُنزِلَ","telah didedahkan"],["إِلَى","kepada"],["ٱلرَّسُولِ","Rasul"],["تَرَىٰٓ","kamu lihat"],["أَعْيُنَهُمْ","mata mereka"],["تَفِيضُ","melimpah"],["مِنَ","dengan"],["ٱلدَّمْعِ","air mata"],["مِمَّا","bagi apa"],["عَرَفُوا۟","mereka mengenali"],["مِنَ","daripada"],["ٱلْحَقِّ ۖ","kebenaran"],["يَقُولُونَ","Mereka berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["ءَامَنَّا","kami telah beriman"],["فَٱكْتُبْنَا","jadi tulislah kami"],["مَعَ","dengan"],["ٱلشَّـٰهِدِينَ","para saksi"]]],"753":["(Dan) mereka mengatakan sehubungan dengan bantahan mereka terhadap orang-orang Yahudi yang mencap mereka masuk Islam (mengapa kami tidak beriman kepada Allah dan kepada kebenaran yang datang kepada kami) yaitu berupa Alquran; artinya tidak ada halangan bagi diri kami untuk beriman selagi memang ada bukti-bukti yang mengharuskan iman (padahal kami sangat ingin) diathafkan/dikaitkan dengan lafal nu'minu (agar Tuhan kami memasukkan kami ke dalam golongan orang-orang yang saleh?) orang-orang yang beriman ke dalam surga. Allah melanjutkan firman-Nya:",[["وَمَا","Dan apa"],["لَنَا","untuk kita (itu)"],["لَا","tidak"],["نُؤْمِنُ","kami beriman"],["بِٱللَّهِ","kepada Allah"],["وَمَا","dan apa"],["جَآءَنَا","datang (kepada) kami"],["مِنَ","daripada"],["ٱلْحَقِّ","kebenaran"],["وَنَطْمَعُ","Dan kami berharap"],["أَن","bahawa"],["يُدْخِلَنَا","akan mengakui kita"],["رَبُّنَا","Tuhan kami"],["مَعَ","dengan"],["ٱلْقَوْمِ","manusia"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"754":["(Maka Allah memberi mereka pahala terhadap perkataan yang mereka ucapkan, yaitu surga yang mengalir sungai-sungai di bawahnya sedang mereka kekal di dalamnya. Dan itulah balasan bagi orang-orang yang berbuat kebaikan) yang ikhlas keimanannya.",[["فَأَثَـٰبَهُمُ","Maka memberi ganjaran kepada mereka"],["ٱللَّهُ","Allah"],["بِمَا","bagi apa"],["قَالُوا۟","mereka berkata"],["جَنَّـٰتٍۢ","(dengan) Taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","akan kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["وَذَٰلِكَ","Dan bahawa"],["جَزَآءُ","(ialah) pahala"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"755":["(Dan orang-orang kafir serta mendustakan ayat-ayat Kami mereka itulah penghuni neraka.)",[["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan dinafikan"],["بِـَٔايَـٰتِنَآ","Tanda-Tanda Kami"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"756":["Ayat ini diturunkan tatkala ada suatu kaum dari kalangan para sahabat yang bertekad menetapi puasa dan melakukan salat di malam harinya; mereka tidak mau mendekati wanita-wanita, memakai wewangian, memakan daging dan tidur di ranjang/kasur. (Hai orang-orang yang beriman janganlah kamu haramkan apa-apa yang baik yang telah Allah halalkan bagi kamu dan janganlah kamu melampaui batas.) janganlah kamu melanggar perintah Allah. (Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.)",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تُحَرِّمُوا۟","jadikan haram"],["طَيِّبَـٰتِ","(yang) perkara yang baik"],["مَآ","apa"],["أَحَلَّ","telah (dihalalkan)."],["ٱللَّهُ","(oleh) Allah"],["لَكُمْ","bagi kamu"],["وَلَا","dan jangan"],["تَعْتَدُوٓا۟ ۚ","langgar"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُعْتَدِينَ","orang yang melampaui batas"]]],"757":["(Dan makanlah makanan yang halal lagi baik dari apa yang Allah rezekikan kepadamu) sebagai maf`ul/obyek jar dan majrur yang sebelumnya menjadi hal yang berkaitan dengan maf`ul itu (dan bertakwalah kepada Allah yang kamu beriman kepada-Nya.)",[["وَكُلُوا۟","Dan makan"],["مِمَّا","tentang apa"],["رَزَقَكُمُ","telah menyediakan kamu"],["ٱللَّهُ","Allah"],["حَلَـٰلًۭا","halal"],["طَيِّبًۭا ۚ","kebaikan"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["ٱلَّذِىٓ","yang Satu"],["أَنتُم","kamu (adalah)"],["بِهِۦ","dalam Dia"],["مُؤْمِنُونَ","orang yang beriman"]]],"758":["(Allah tidak menghukum kamu disebabkan senda-gurau) yang terjadi (di dalam sumpah-sumpahmu) yaitu sumpah yang dilakukan secara tidak sengaja hanya karena lisan terlanjur mengatakan, seperti ucapan seseorang, \"Tidak demi Allah,\" dan, \"Ya demi Allah.\" (tetapi Dia menghukum kamu disebabkan apa yang kamu sengaja) dengan dibaca ringan `aqadtum dan dibaca tasydid `aqqadtum, menurut suatu riwayat dibaca `aaqadtum (dalam sumpah-sumpahmu) mengenai hal itu, yaitu seumpamanya kamu bersumpah dengan sengaja (maka kafaratnya) artinya kafarat sumpah tersebut apabila kamu melanggarnya (memberi makan sepuluh orang miskin) yang untuk setiap orang sebanyak satu mud (yaitu dari makanan yang biasa kamu berikan) dari makanan tersebut (kepada keluargamu) artinya kualitas makanan yang paling pertengahan dan yang paling biasa dipakai bukannya kualitas makanan yang paling tinggi dan juga bukan yang paling rendah (atau memberi kepada mereka pakaian) yaitu sesuatu yang biasa dijadikan sebagai pakaian seperti baju gamis, serban dan kain. Imam Syafii berpendapat jika memberikannya secara sekaligus kepada seorang miskin saja dianggap kurang sempurna atau tidak memenuhi persyaratan (atau membebaskan) memerdekakan (seorang budak) yang beriman seperti dalam masalah kafarat membunuh dan kafarat zihar atas dasar memberlakukan yang mutlak dengan hukum yang muqayyad (dan siapa yang tidak menemukan) salah satu di antara yang telah disebutkan (maka berpuasa selama tiga hari) sebagai ganti kafaratnya; menurut pendapat yang terkuat dalam masalah ini tidak disyaratkan puasa secara berturut-turut, pendapat ini dikatakan oleh Imam Syafii. (Yang demikian itu) yang telah disebutkan (adalah kafarat sumpah-sumpahmu bila kamu bersumpah) kemudian kamu langgar. (Dan jagalah sumpahmu) jangan sampai kamu melanggarnya selagi sumpah itu bukanlah perbuatan kebaikan atau mendamaikan orang-orang sebagaimana yang telah disebutkan dalam surah Al-Baqarah. (Demikianlah) artinya seperti apa yang telah Allah jelaskan tentang beberapa hal yang telah lalu penuturannya (Allah menjelaskan kepada kamu tentang ayat-ayat-Nya agar kamu bersyukur) kepada-Nya atas hal itu.",[["لَا","Tidak"],["يُؤَاخِذُكُمُ","akan menghubungi kamu ke akaun"],["ٱللَّهُ","Allah"],["بِٱللَّغْوِ","untuk ucapan yang tidak difikirkan"],["فِىٓ","dalam"],["أَيْمَـٰنِكُمْ","sumpah kamu"],["وَلَـٰكِن","tetapi"],["يُؤَاخِذُكُم","Dia akan memanggil kamu ke akaun"],["بِمَا","bagi apa"],["عَقَّدتُّمُ","kamu kontrak"],["ٱلْأَيْمَـٰنَ ۖ","(dari) sumpah itu"],["فَكَفَّـٰرَتُهُۥٓ","Jadi kafaratnya"],["إِطْعَامُ","(adalah) memberi makan"],["عَشَرَةِ","(dari) sepuluh"],["مَسَـٰكِينَ","orang yang memerlukan"],["مِنْ","daripada"],["أَوْسَطِ","purata"],["مَا","apa"],["تُطْعِمُونَ","kamu memberi makan"],["أَهْلِيكُمْ","keluarga kamu"],["أَوْ","atau"],["كِسْوَتُهُمْ","pakaian mereka"],["أَوْ","atau"],["تَحْرِيرُ","membebaskan"],["رَقَبَةٍۢ ۖ","seorang hamba"],["فَمَن","Tetapi siapa pun"],["لَّمْ","tidak"],["يَجِدْ","cari"],["فَصِيَامُ","(itu), kemudian berpuasa"],["ثَلَـٰثَةِ","(untuk) tiga"],["أَيَّامٍۢ ۚ","hari"],["ذَٰلِكَ","Itu"],["كَفَّـٰرَةُ","(ialah) kafarat"],["أَيْمَـٰنِكُمْ","(dari) sumpah kamu"],["إِذَا","apabila"],["حَلَفْتُمْ ۚ","kamu telah bersumpah"],["وَٱحْفَظُوٓا۟","Dan jaga"],["أَيْمَـٰنَكُمْ ۚ","sumpah kamu"],["كَذَٰلِكَ","Demikianlah"],["يُبَيِّنُ","membuat jelas"],["ٱللَّهُ","Allah"],["لَكُمْ","kepada kamu"],["ءَايَـٰتِهِۦ","Ayat-ayatNya"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)."]]],"759":["(Hai orang-orang yang beriman, sesungguhnya meminum khamar) minuman yang memabukkan yang dapat menutupi akal sehat (berjudi) taruhan (berkorban untuk berhala) patung-patung sesembahan (mengundi nasib dengan anak panah) permainan undian dengan anak panah (adalah perbuatan keji) menjijikkan lagi kotor (termasuk perbuatan setan) yang dihiasi oleh setan. (Maka jauhilah perbuatan-perbuatan itu) yakni kekejian yang terkandung di dalam perbuatan-perbuatan itu jangan sampai kamu melakukannya (agar kamu mendapat keberuntungan).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِنَّمَا","Sesungguhnya"],["ٱلْخَمْرُ","yang memabukkan"],["وَٱلْمَيْسِرُ","dan [permainan] peluang"],["وَٱلْأَنصَابُ","dan (berkurban di) mezbah"],["وَٱلْأَزْلَـٰمُ","dan anak panah meramal"],["رِجْسٌۭ","(adalah) kekejian"],["مِّنْ","daripada"],["عَمَلِ","(yang) kerja"],["ٱلشَّيْطَـٰنِ","(dari) syaitan"],["فَٱجْتَنِبُوهُ","jadi elakkan"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","(berjaya)."]]],"760":["(Sesungguhnya setan itu bermaksud hendak menimbulkan permusuhan dan kebencian di antara kamu lantaran meminum khamar dan berjudi itu) bila kamu melakukan keduanya mengingat dalam keduanya itu terkandung kejelekan dan fitnah (dan menghalangi kamu) karena sibuk melakukannya itu (dari mengingat Allah dan salat) Allah menyebutkan salat secara khusus sebagai pengagungan terhadap-Nya (maka berhentilah kamu) dari melakukan kedua pekerjaan ini.",[["إِنَّمَا","Hanya"],["يُرِيدُ","berniat"],["ٱلشَّيْطَـٰنُ","syaitan"],["أَن","kepada"],["يُوقِعَ","sebab"],["بَيْنَكُمُ","antara kamu"],["ٱلْعَدَٰوَةَ","[the] permusuhan"],["وَٱلْبَغْضَآءَ","dan kebencian"],["فِى","melalui"],["ٱلْخَمْرِ","minuman yang memabukkan"],["وَٱلْمَيْسِرِ","dan perjudian"],["وَيَصُدَّكُمْ","dan menghalang kamu"],["عَن","daripada"],["ذِكْرِ","(the) zikir"],["ٱللَّهِ","(milik) Allah"],["وَعَنِ","dan daripada"],["ٱلصَّلَوٰةِ ۖ","solat"],["فَهَلْ","Jadi akan"],["أَنتُم","kamu"],["مُّنتَهُونَ","(jadilah) orang-orang yang berpantang"]]],"761":["(Dan taatlah kamu kepada Allah dan taatlah kamu kepada Rasul-Nya dan berhati-hatilah) terhadap perbuatan-perbuatan maksiat. (Jika kamu berpaling) dari ketaatan (maka ketahuilah bahwa sesungguhnya kewajiban Rasul Kami hanyalah menyampaikan amanat Allah dengan terang) dengan gamblang, kemudian pembalasan kamu oleh Kami.",[["وَأَطِيعُوا۟","Dan taat"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","dan taat"],["ٱلرَّسُولَ","Rasul"],["وَٱحْذَرُوا۟ ۚ","dan berhati-hati"],["فَإِن","Dan jika"],["تَوَلَّيْتُمْ","kamu berpaling"],["فَٱعْلَمُوٓا۟","maka ketahuilah"],["أَنَّمَا","sahaja"],["عَلَىٰ","ke atas"],["رَسُولِنَا","Rasul kami"],["ٱلْبَلَـٰغُ","(iaitu) menyampaikan (Mesej)"],["ٱلْمُبِينُ","dengan jelas"]]],"762":["(Tidak ada dosa bagi orang-orang yang beriman dan mengerjakan amalan yang saleh karena memakan makanan yang telah mereka makan dahulu) meminum dan melakukan perjudian sebelum adanya pengharaman (apabila mereka bertakwa) terhadap perbuatan-perbuatan yang haram (serta beriman dan mengerjakan amal-amalan yang saleh kemudian mereka tetap bertakwa dan beriman) mereka terus menetapi pada ketakwaan dan keimanannya (kemudian mereka tetap juga bertakwa dan berbuat kebaikan) dalam beramal. (Dan Allah menyukai orang-orang yang berbuat kebaikan) dengan pengertian bahwa Allah akan memberi pahala mereka.",[["لَيْسَ","Tidak"],["عَلَى","pada"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik itu"],["جُنَاحٌۭ","sebarang dosa"],["فِيمَا","bagi apa"],["طَعِمُوٓا۟","mereka makan"],["إِذَا","apabila"],["مَا","bahawa"],["ٱتَّقَوا۟","mereka takut (Allah)"],["وَّءَامَنُوا۟","dan mereka beriman"],["وَعَمِلُوا۟","dan mereka lakukan"],["ٱلصَّـٰلِحَـٰتِ","[yang] perbuatan baik"],["ثُمَّ","kemudian"],["ٱتَّقَوا۟","mereka takut (Allah)"],["وَّءَامَنُوا۟","dan beriman"],["ثُمَّ","kemudian"],["ٱتَّقَوا۟","mereka takut (Allah)"],["وَّأَحْسَنُوا۟ ۗ","dan berbuat baik"],["وَٱللَّهُ","dan Allah"],["يُحِبُّ","suka"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"763":["(Hai orang-orang yang beriman, sesungguhnya kamu akan menerima ujian) percobaan dari (Allah dengan sesuatu) yang Ia kirimkan kepadamu (berupa binatang buruan yang mudah didapat) maksudnya binatang buruan yang kecil-kecil (oleh tangan-tanganmu dan tombak-tombakmu) berupa binatang buruan yang besar-besar. Peristiwa ini terjadi sewaktu di Hudaibiah sedangkan mereka dalam keadaan berihram; tersebutlah bahwa hewan-hewan liar berada di mana-mana sewaktu mereka dalam perjalanan (supaya Allah mengetahui) dengan pengetahuan yang jelas (orang yang takut kepada-Nya, biar pun ia tidak dapat melihat-Nya) menjadi hal yang artinya secara gaib tidak bisa melihat-Nya kemudian ia menghindari binatang buruan itu. (Siapa yang melanggar batas sesudah itu) sesudah dilarang menangkap binatang buruan itu kemudian ia bertekad menangkapnya (maka baginya siksaan yang pedih).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَيَبْلُوَنَّكُمُ","Pasti akan menguji kamu"],["ٱللَّهُ","Allah"],["بِشَىْءٍۢ","melalui sesuatu"],["مِّنَ","daripada"],["ٱلصَّيْدِ","permainan itu"],["تَنَالُهُۥٓ","boleh mencapainya"],["أَيْدِيكُمْ","tangan kamu"],["وَرِمَاحُكُمْ","dan lembing kamu"],["لِيَعْلَمَ","yang mungkin jelas"],["ٱللَّهُ","Allah"],["مَن","yang"],["يَخَافُهُۥ","takut kepada-Nya"],["بِٱلْغَيْبِ ۚ","dalam ghaib"],["فَمَنِ","Dan sesiapa"],["ٱعْتَدَىٰ","dilanggar"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["فَلَهُۥ","kemudian untuk dia"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"764":["(Hai orang-orang yang beriman! Janganlah kamu membunuh binatang buruan ketika kamu sedang berihram) melakukan ihram haji dan ihram umrah. (Siapa di antara kamu membunuhnya dengan sengaja, maka dendanya) lafal yang sesudahnya dibaca secara tanwin dan rafa`; artinya ia harus membayar denda yang (sama dengan hewan yang telah dibunuhnya) artinya hewan yang sama bentuknya; dan di dalam suatu qiraat lafal jazaaun diidhafatkan kepada lafal yang sesudahnya sehingga dibaca wa jazaau mitsli (menurut keputusan) artinya mengenai perimbangan dua orang lelaki (dua orang yang adil di antara kamu) yang keduanya mempunyai kecerdasan dalam membedakan dan menyesuaikan hal-hal yang serupa. Ibnu Abbas, Umar dan Ali telah memutuskan denda seekor unta sebagai imbangan buruan seekor burung unta. Kemudian Ibnu Abbas dan Abu Ubaidah telah memutuskan mengganti sapi liar dan keledai liar dengan seekor sapi. Ibnu Umar dan Ibnu Auf mengganti seekor kijang dengan seekor kambing sebagai kafaratnya, kemudian Ibnu Abbas dan Umar serta selain keduanya telah memutuskan hal yang sama dalam kasus perburuan rusa sebab ia mirip dengan kambing dalam masalah besarnya (sebagai hadya) sebagai hal dari lafal jazaa (yang dibawa sampai ke Kakbah) artinya kurban itu dibawa sampai ke tanah suci lalu disembelih sesampainya di sana, lalu dagingnya disedekahkan kepada para penduduknya yang miskin; dan hewan hadya itu tidak boleh disembelih di tempat perburuan terjadi. Lafal balighal ka`bati dibaca nashab karena menjadi sifat dari lafal yang sebelumnya yaitu hadya, sekalipun ia diidhafatkan karena idhafatnya itu hanya bersifat lafzi. Jadi tidak memberikan pengertian makrifat. Apabila binatang buruan itu sangat sulit untuk ditemukan yang sepadan dengannya, seperti burung cicit dan belalang, maka pelakunya wajib membayar harganya saja (atau) ia harus membayar (kafarat) yang tidak sepadan sekalipun hewan yang sepadan memang ada, yaitu (memberi makan orang-orang miskin) berupa makanan pokok yang biasa dimakan oleh penduduk setempat dalam jumlah yang sesuai dengan harga denda untuk dibagikan kepada setiap orang miskin satu mud. Menurut suatu qiraat dengan mengidhafatkan lafal kaffarah kepada lafal yang sesudahnya dengan pengertian memperjelas (atau) ia harus membayarnya (dengan yang seimbang) seperti (jumlah itu) dalam bentuk makanan (berupa puasa) yang ia lakukan untuk setiap harinya sebagai ganti dari satu mud makanan, dan jika ia menemukan makanan, maka yang wajib baginya ialah membayarnya dengan makanan (supaya ia merasakan akibat) yang berat bagi pembalasan (perbuatannya) yang telah ia lakukan. (Allah telah memaafkan apa yang telah lalu) yaitu dari perbuatan membunuh binatang buruan sewaktu ihram sebelum diharamkan. (Dan siapa yang kembali mengerjakan)nya (niscaya Allah akan membalasnya. Allah Maha Perkasa) Maha Menang dalam segala perkara-Nya (lagi Yang Mempunyai pembalasan) terhadap orang yang berbuat durhaka kepada-Nya dan kemudian disamakan dengan membunuh secara sengaja, yaitu membunuh secara kesalahan.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَقْتُلُوا۟","membunuh"],["ٱلصَّيْدَ","permainan itu"],["وَأَنتُمْ","sedangkan kamu"],["حُرُمٌۭ ۚ","(berada dalam) Ihram"],["وَمَن","Dan sesiapa"],["قَتَلَهُۥ","membunuhnya"],["مِنكُم","antara kamu"],["مُّتَعَمِّدًۭا","dengan sengaja"],["فَجَزَآءٌۭ","kemudian penalti"],["مِّثْلُ","(adalah) serupa"],["مَا","(kepada) apa"],["قَتَلَ","dia membunuh"],["مِنَ","daripada"],["ٱلنَّعَمِ","lembu itu"],["يَحْكُمُ","menghakimi"],["بِهِۦ","ia"],["ذَوَا","dua orang lelaki"],["عَدْلٍۢ","cuma"],["مِّنكُمْ","antara kamu"],["هَدْيًۢا","(sebagai) suatu persembahan"],["بَـٰلِغَ","mencapai"],["ٱلْكَعْبَةِ","Kabah"],["أَوْ","atau"],["كَفَّـٰرَةٌۭ","kafarat"],["طَعَامُ","memberi makan"],["مَسَـٰكِينَ","orang yang memerlukan"],["أَوْ","atau"],["عَدْلُ","setara"],["ذَٰلِكَ","(daripada) itu"],["صِيَامًۭا","(dalam) berpuasa"],["لِّيَذُوقَ","supaya dia dapat rasa"],["وَبَالَ","(akibatnya)."],["أَمْرِهِۦ ۗ","(dari) perbuatannya"],["عَفَا","Diampunkan"],["ٱللَّهُ","(oleh) Allah"],["عَمَّا","apa"],["سَلَفَ ۚ","(telah) berlalu"],["وَمَنْ","tetapi sesiapa sahaja"],["عَادَ","dikembalikan"],["فَيَنتَقِمُ","maka akan menerima pembalasan"],["ٱللَّهُ","Allah"],["مِنْهُ ۗ","daripada dia"],["وَٱللَّهُ","Dan Allah"],["عَزِيزٌۭ","(adalah) Maha Perkasa"],["ذُو","Pemilik"],["ٱنتِقَامٍ","(dari) Pembalasan"]]],"765":["(Dihalalkan bagimu) hai umat manusia sewaktu kamu berada dalam keadaan halal/tidak ihram atau sedang ihram (binatang buruan laut) kamu boleh memakannya. Binatang buruan laut ialah binatang yang hidupnya hanya di laut/di air, seperti ikan. Berbeda dengan binatang yang terkadang hidup di laut dan terkadang hidup di darat seperti kepiting (dan makanan yang berasal dari laut) binatang laut yang terdampar dalam keadaan mati (sebagai makanan yang lezat) untuk dinikmati (bagimu) kamu boleh memakannya (dan bagi orang-orang yang bepergian) orang-orang yang musafir dari kalangan kamu dengan menjadikannya sebagai bekal mereka. (Dan diharamkan atasmu binatang buruan darat) yaitu binatang yang hidup di darat dari jenis binatang yang boleh dimakan, kamu dilarang memburunya (selagi kamu dalam keadaan ihram) dan jika yang memburunya itu adalah orang yang tidak sedang ihram, maka orang yang sedang ihram diperbolehkan memakannya sebagaimana yang telah dijelaskan oleh sunah. (Dan bertakwalah kepada Allah yang hanya kepada-Nya kamu kembali.)",[["أُحِلَّ","Dihalalkan"],["لَكُمْ","bagi kamu"],["صَيْدُ","permainan"],["ٱلْبَحْرِ","(dari) laut"],["وَطَعَامُهُۥ","dan makanannya"],["مَتَـٰعًۭا","(sebagai) peruntukan"],["لَّكُمْ","bagi kamu"],["وَلِلسَّيَّارَةِ ۖ","dan untuk pengembara"],["وَحُرِّمَ","dan dijadikan haram"],["عَلَيْكُمْ","pada kamu"],["صَيْدُ","permainan"],["ٱلْبَرِّ","(dari) tanah itu"],["مَا","seperti"],["دُمْتُمْ","sepanjang kamu"],["حُرُمًۭا ۗ","(berada dalam) Ihram"],["وَٱتَّقُوا۟","Dan sedarlah"],["ٱللَّهَ","(milik) Allah"],["ٱلَّذِىٓ","yang Satu"],["إِلَيْهِ","kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"766":["(Allah telah menjadikan Kakbah rumah suci itu) rumah yang disucikan (sebagai pusat kegiatan umat manusia) yang mereka melaksanakan urusan agamanya dengan berhaji kepadanya, dan mengatur urusan keduniaan mereka dengan mengamankan orang-orang yang masuk ke dalamnya dan menjamin keselamatan mereka, kemudian mendatangkan semua jenis buah-buahan ke dalamnya. Menurut suatu qiraat dibaca qiyaman tanpa alif panjang yang berakar dari kata qaama tanpa dii'lalkan (dan bulan haram) yang dimaksud adalah bulan-bulan haram seperti Zulkaidah, Zulhijah, Muharam dan Rajab sebagai pusat kegiatan mereka dalam mengamankan lingkungan dan tidak boleh melakukan peperangan dalam bulan-bulan tersebut (dan hadya serta qalaid) sebagai pertanda bagi semua orang bahwa kedua jenis hewan kurban itu tidak boleh diganggu dan harus diamankan. (Demikian itu) peraturan yang telah disebutkan itu (agar kamu tahu, bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan bahwa sesungguhnya Allah Maha Mengetahui segala sesuatu) karena sesungguhnya Ia telah menjadikan peraturan tersebut demi kemaslahatan kamu dan demi untuk menolak mara bahaya dari dirimu sebelum segala sesuatunya terjadi; hal ini jelas menunjukkan pengetahuan Allah yang mencakup semua yang ada dalam alam wujud ini dan semua yang sedang berlangsung.",[["۞ جَعَلَ","Telah (telah) dibuat"],["ٱللَّهُ","(oleh) Allah"],["ٱلْكَعْبَةَ","Kabah"],["ٱلْبَيْتَ","Dewan"],["ٱلْحَرَامَ","yang Suci"],["قِيَـٰمًۭا","sebuah pertubuhan"],["لِّلنَّاسِ","untuk manusia"],["وَٱلشَّهْرَ","dan bulan"],["ٱلْحَرَامَ","[yang] suci"],["وَٱلْهَدْىَ","dan (binatang) untuk dipersembahkan"],["وَٱلْقَلَـٰٓئِدَ ۚ","dan kalungan"],["ذَٰلِكَ","Itu (ialah)"],["لِتَعْلَمُوٓا۟","supaya kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌ","(adalah) Maha Mengetahui"]]],"767":["(Ketahuilah bahwa sesungguhnya Allah amat berat siksaan-Nya) terhadap musuh-musuh-Nya (dan bahwa sesungguhnya Allah Maha Pengampun) terhadap kekasih-kekasih-Nya (lagi Maha Penyayang) terhadap mereka.",[["ٱعْلَمُوٓا۟","Tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) hukuman"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"768":["(Kewajiban rasul tidak lain hanyalah menyampaikan) kepadamu (dan Allah mengetahui apa yang kamu tampakkan) amal perbuatan yang kamu lahirkan (dan apa yang kamu sembunyikan) amal perbuatan yang kamu sembunyikan karena itu Allah membalas kamu.",[["مَّا","Tidak"],["عَلَى","pada"],["ٱلرَّسُولِ","Rasul"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ ۗ","pengangkutan itu"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تُبْدُونَ","kamu dedahkan"],["وَمَا","dan apa"],["تَكْتُمُونَ","kamu sembunyikan"]]],"769":["(Katakanlah, \"Tidak sama yang buruk) barang yang haram (dengan yang baik) barang yang halal (meskipun membuatmu kagum) membuatmu suka (banyaknya hal yang buruk itu, maka bertakwalah kepada Allah) tinggalkanlah hal yang buruk itu (hai orang-orang berakal agar kamu mendapat keberuntungan.\") agar kamu mendapat kebahagiaan. Kemudian turunlah ayat berikut ini tatkala para sahabat banyak bertanya kepada Rasulullah saw.",[["قُل","Katakanlah"],["لَّا","Tidak"],["يَسْتَوِى","(adalah) sama"],["ٱلْخَبِيثُ","yang jahat"],["وَٱلطَّيِّبُ","dan yang baik"],["وَلَوْ","walaupun"],["أَعْجَبَكَ","mengagumkan kamu"],["كَثْرَةُ","kelimpahan"],["ٱلْخَبِيثِ ۚ","(dari) kejahatan"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["يَـٰٓأُو۟لِى","Wahai lelaki"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","(berjaya)."]]],"770":["(Hai orang-orang yang beriman! Janganlah kamu menanyakan kepada Nabimu hal-hal yang jika diterangkan) dijelaskan (kepadamu, niscaya menyusahkan kamu) karena di dalamnya mengandung kemudaratan (dan jika kamu menanyakannya di waktu Alquran itu sedang diturunkan) artinya di masa Nabi saw. masih hidup (niscaya akan diterangkan kepadamu) makna ayat: apabila kamu bertanya tentang macam-macam masalah sewaktu Nabi saw. masih ada niscaya akan turun ayat-ayat Alquran yang menjelaskannya dan jika ayat-ayat Alquran telah turun niscaya isinya akan menjelek-jelekkan kamu sendiri oleh karena janganlah kamu banyak bertanya tentang hal-hal itu; sesungguhnya (Allah telah memaafkan kamu tentang hal-hal itu) sebelum kamu meminta maaf kepada-Nya, maka dari itu janganlah kamu mengulanginya. (Allah Maha Pengampun lagi Maha Penyantun.)",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَسْـَٔلُوا۟","bertanya"],["عَنْ","tentang"],["أَشْيَآءَ","benda"],["إِن","jika"],["تُبْدَ","dibuat dengan jelas"],["لَكُمْ","kepada kamu"],["تَسُؤْكُمْ","ia mungkin menyusahkan kamu"],["وَإِن","dan jika"],["تَسْـَٔلُوا۟","kamu tanya"],["عَنْهَا","mengenainya"],["حِينَ","apabila"],["يُنَزَّلُ","sedang didedahkan"],["ٱلْقُرْءَانُ","al-Quran"],["تُبْدَ","ia akan dibuat dengan jelas"],["لَكُمْ","kepada kamu"],["عَفَا","telah (diampunkan)."],["ٱللَّهُ","(oleh) Allah"],["عَنْهَا ۗ","[tentang]nya"],["وَٱللَّهُ","dan Allah"],["غَفُورٌ","Maha Pengampun"],["حَلِيمٌۭ","Maha Penyabar"]]],"771":["(Sesungguhnya telah menanyakan hal itu) artinya hal-hal serupa itu (suatu kaum sebelum kamu) kepada nabi-nabi mereka, maka mereka diberi penjelasan tentang hukum-hukumnya (kemudian jadilah mereka) mereka menjadi (tidak percaya kepadanya) karena mereka tidak mengamalkannya.",[["قَدْ","Sesungguhnya"],["سَأَلَهَا","tanya mereka"],["قَوْمٌۭ","suatu kaum"],["مِّن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["ثُمَّ","kemudian"],["أَصْبَحُوا۟","mereka menjadi"],["بِهَا","dengan itu"],["كَـٰفِرِينَ","orang kafir"]]],"772":["(Tidak sekali-kali menjadikan) mensyariatkan (Allah akan adanya bahirah, saibah, wasilah dan ham) sebagaimana yang telah dilakukan oleh orang-orang jahiliah. Telah diriwayatkan oleh Imam Bukhari dari Said bin Musayyab yang telah mengatakan bahwa bahirah ialah unta betina yang air susunya dihadiahkan untuk berhala-berhala, maka tidak ada seorang pun yang berani memerah air susunya. Saibah ialah unta betina yang mereka lepaskan begitu saja dibiarkan demi untuk berhala-berhala mereka, maka unta tersebut tidak boleh dibebani sesuatu pun. Wasilah ialah unta betina yang sewaktu melahirkan anak unta pertama kalinya betina setelah ia beranak lagi secara kembar yang kedua-duanya betina; induk unta itu dibiarkan terlepas bebas jika anak-anaknya itu tidak ada yang jantan yang memisahkan antara kedua anaknya itu. Hal ini mereka lakukan demi berhala-berhala mereka. Dan ham ialah unta pejantan yang dipekerjakan dalam masa yang telah ditentukan dan jika masanya telah habis lalu mereka membiarkannya bebas demi untuk mendekatkan diri kepada berhala-berhala sesembahan mereka. Selain dari itu mereka membebaskannya dari segala muatan dan beban hingga ia tidak lagi disuruh membawa apa pun dan nama lain dari jenis unta itu ialah hami. (Akan tetapi orang-orang kafir selalu membuat kedustaan terhadap Allah) dalam hal tersebut kemudian mereka mengaitkannya kepada Allah (dan kebanyakan mereka tidak mengerti) bahwa perkara tersebut merupakan kedustaan karena mereka dalam hal ini hanyalah mengikuti apa yang biasa dilakukan oleh nenek moyang mereka.",[["مَا","Tidak"],["جَعَلَ","telah (telah) dibuat"],["ٱللَّهُ","(oleh) Allah"],["مِنۢ","daripada"],["بَحِيرَةٍۢ","a Bahirah"],["وَلَا","dan bukan"],["سَآئِبَةٍۢ","seorang Saibah"],["وَلَا","dan bukan"],["وَصِيلَةٍۢ","a Wasilah"],["وَلَا","dan bukan"],["حَامٍۢ ۙ","seorang Hami"],["وَلَـٰكِنَّ","[Dan] tetapi"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["يَفْتَرُونَ","mereka cipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ ۖ","pembohongan itu"],["وَأَكْثَرُهُمْ","dan kebanyakannya"],["لَا","jangan"],["يَعْقِلُونَ","guna akal"]]],"773":["(Apabila dikatakan kepada mereka, \"Marilah mengikuti apa yang telah diturunkan Allah dan mengikuti rasul!\") artinya kepada hikmah yang menjelaskan tentang penghalalan apa yang kamu haramkan (Mereka menjawab, \"Cukuplah untuk kami) kami cukup puas dengan (apa yang kami dapati bapak-bapak kami mengerjakannya.\") yaitu berupa agama dan syariat. Allah selanjutnya berfirman: (Apakah) mereka cukup puas dengan hal itu (sekalipun nenek moyang mereka itu tidak mengetahui apa-apa dan tidak pula mendapat petunjuk) ke jalan yang benar? Kata tanya/istifham di sini menunjukkan makna ingkar.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["تَعَالَوْا۟","Datang"],["إِلَىٰ","kepada"],["مَآ","apa"],["أَنزَلَ","telah (telah) didedahkan"],["ٱللَّهُ","(oleh) Allah"],["وَإِلَى","dan kepada"],["ٱلرَّسُولِ","Rasul"],["قَالُوا۟","mereka berkata"],["حَسْبُنَا","Cukup untuk kita"],["مَا","(ialah) apa"],["وَجَدْنَا","kami jumpa"],["عَلَيْهِ","atasnya"],["ءَابَآءَنَآ ۚ","nenek moyang kita"],["أَوَلَوْ","walaupun"],["كَانَ","(itu)"],["ءَابَآؤُهُمْ","nenek moyang mereka"],["لَا","(adalah) tidak"],["يَعْلَمُونَ","mengetahui"],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["يَهْتَدُونَ","mereka telah mendapat petunjuk"]]],"774":["(Hai orang-orang yang beriman! Jagalah dirimu) peliharalah dirimu dan berbuatlah kamu untuk memperbaikinya (tiadalah orang yang sesat itu akan memberi mudarat kepadamu apabila kamu telah mendapat petunjuk.) Dikatakan bahwa yang dimaksud dengan makna tidak akan membahayakan kamu orang-orang yang sesat ialah golongan Ahlul Kitab. Menurut pendapat lainnya, yang dimaksud dengan mereka adalah orang-orang selain Ahlul Kitab, pendapat ini berlandaskan pada hadisnya Abu Tsa'labah Al-Khusyani. Dalam hadisnya Al-Khusyani mengatakan, \"Aku bertanya kepada Rasulullah saw. tentang makna ayat ini; kemudian beliau menjawab, 'Saling perintah-memerintahkanlah kamu sekalian kepada kebaikan, dan saling cegah-mencegahlah kamu sekalian tentang kemungkaran, hingga jika kamu melihat orang yang bakhil (pelit) ditaati; hawa nafsu mulai diikuti; keduniawian paling dipentingkan; dan orang-orang yang berakal mulai merasa kagum dengan akalnya sendiri, maka peliharalah dirimu.'\" Hadis ini diriwayatkan oleh Imam Hakim dan lain-lainnya (hanya kepada Allahlah kamu semuanya kembali, kemudian Dia akan menerangkan kepadamu apa yang telah kamu kerjakan) kemudian Dia akan membalas kamu.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["عَلَيْكُمْ","atas kamu"],["أَنفُسَكُمْ ۖ","(adalah untuk menjaga) diri kamu"],["لَا","Tidak"],["يَضُرُّكُم","akan membahayakan kamu"],["مَّن","(mereka) yang"],["ضَلَّ","(telah pergi) sesat"],["إِذَا","apabila"],["ٱهْتَدَيْتُمْ ۚ","kamu telah diberi petunjuk"],["إِلَى","Kepada"],["ٱللَّهِ","Allah"],["مَرْجِعُكُمْ","(adalah) kamu kembali"],["جَمِيعًۭا","semua"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"775":["(Hai orang-orang yang beriman! Diperlukan kesaksian di antara kamu apabila salah seorang di antara kamu menghadapi kematian) menghadapi hal-hal yang menyebabkan kepada kematian (tatkala ia hendak berwasiat; yaitu oleh dua orang lelaki yang adil di antara kamu) Kalimat syahaadatu bainikum adalah kalimat berita yang bermakna perintah; yang artinya hendaklah disaksikan/liyasyhad. Mengidhafatkan Lafal syahaadah kepada Lafal baina menunjukkan makna keluasan memilih; kata hiina merupakan badal (kata ganti) dari kata idzaa atau menjadi zharaf bagi kalimat hadhara (atau oleh dua orang yang berbeda dengan kamu) artinya yang bukan seagama denganmu (jika kamu dalam perjalanan) sedang bepergian (di muka bumi lalu kamu tertimpa bahaya kematian. Kamu tahan kedua saksi itu) kamu pegang kedua orang itu; kalimat ini menjadi kata sifat dari lafal aakharaani (sesudah kamu salat) yaitu salat asar (lalu mereka keduanya bersumpah) mengikrarkan perjanjian (dengan atas nama Allah jika kamu ragu-ragu) kamu merasa syakwasangka mengenainya, kemudian keduanya mengatakan: (\"Kami tidak akan membeli dengan sumpah itu) atas nama Allah (harga yang sedikit) sebagai imbalan berupa materi/duniawi yang kami ambil sebagai penggantinya dengan cara bersumpah atau mengadakan kesaksian dusta demi untuk meraih imbalan itu (walaupun dia) orang yang disumpahi atau orang yang disaksikan itu adalah (kerabat karib) familinya sendiri (dan tidak pula kami menyembunyikan persaksian Allah) yang kami diperintahkan-Nya untuk melaksanakannya (sesungguhnya kami kalau demikian) kalau kami menyembunyikannya (termasuk orang-orang yang berdosa.\")",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["شَهَـٰدَةُ","(Ambil) kesaksian"],["بَيْنِكُمْ","antara kamu"],["إِذَا","apabila"],["حَضَرَ","pendekatan"],["أَحَدَكُمُ","salah seorang daripada kamu"],["ٱلْمَوْتُ","[the] kematian"],["حِينَ","(pada) masa (membuat)"],["ٱلْوَصِيَّةِ","[the] wasiat"],["ٱثْنَانِ","dua"],["ذَوَا","lelaki"],["عَدْلٍۢ","cuma"],["مِّنكُمْ","antara kamu"],["أَوْ","atau"],["ءَاخَرَانِ","dua lagi"],["مِنْ","daripada"],["غَيْرِكُمْ","selain kamu"],["إِنْ","jika"],["أَنتُمْ","kamu"],["ضَرَبْتُمْ","(adalah) perjalanan (ing)"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَأَصَـٰبَتْكُم","kemudian menimpa kamu"],["مُّصِيبَةُ","musibah"],["ٱلْمَوْتِ ۚ","(dari) kematian"],["تَحْبِسُونَهُمَا","Tahan kedua-duanya"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["ٱلصَّلَوٰةِ","solat"],["فَيُقْسِمَانِ","dan hendaklah mereka berdua bersumpah"],["بِٱللَّهِ","oleh Allah"],["إِنِ","jika"],["ٱرْتَبْتُمْ","kamu ragu-ragu"],["لَا","Tidak"],["نَشْتَرِى","kami akan tukar"],["بِهِۦ","ia untuk"],["ثَمَنًۭا","satu harga"],["وَلَوْ","walaupun"],["كَانَ","dia adalah"],["ذَا","(daripada)"],["قُرْبَىٰ ۙ","saudara terdekat"],["وَلَا","dan bukan"],["نَكْتُمُ","kami akan sembunyikan"],["شَهَـٰدَةَ","kesaksian"],["ٱللَّهِ","(milik) Allah"],["إِنَّآ","Sesungguhnya kami"],["إِذًۭا","kemudian"],["لَّمِنَ","(akan) pasti (ada) daripada"],["ٱلْـَٔاثِمِينَ","orang berdosa"]]],"776":["(Jika diketahui) terbukti sesudah keduanya bersumpah (bahwa kedua saksi itu melakukan dosa) artinya melakukan perbuatan yang mengakibatkan dosa, seperti berkhianat atau berdusta dalam kesaksiannya; hal ini diperkuat dengan adanya bukti bahwa keduanya hanya mengaku telah membeli barang yang diwasiatkan itu dari si mayat atau mereka mengaku bahwa si mayat telah mewasiatkan untuk mereka (maka dua orang yang lain mengganti kedudukan mereka berdua) untuk mengajukan tuntutan kepada mereka berdua (dari orang-orang yang berhak) menerima wasiat; mereka ialah para ahli waris dari si mayat kemudian keduanya diganti (yang keduanya lebih dekat) kepada orang yang mati; artinya dua orang yang kekerabatannya dekat dengan si mayat. Di dalam suatu qiraat dibaca al-awwaliin, jamak dari kata awwal sebagai sifat atau badal dari kata alladziina (kemudian keduanya melakukan sumpah dengan nama Allah) mengenai khianat yang dilakukan oleh kedua saksi pertama, lalu mengucapkan: (\"Sesungguhnya persaksian kami) sumpah kami ini (lebih berhak) lebih diakui (daripada persaksian kedua saksi itu) sumpah keduanya (dan kami tidak melanggar batas) melewati garis-garis kebenaran dalam sumpah (sesungguhnya kami kalau demikian tentulah termasuk orang-orang yang berdosa.\") Makna ayat secara ringkasnya ialah: Hendaklah orang yang sedang menghadapi kematian mempersaksikan wasiatnya itu di hadapan dua orang saksi. Atau ia berwasiat kepada dua orang yang seagama atau berlainan agama jika kamu jauh dari ahli warismu oleh karena kamu sedang mengadakan perjalanan atau karena ada keperluan lainnya. Apabila para ahli waris merasa ragu terhadap kejujuran kedua saksi itu, maka mereka diperbolehkan mengajukan tuntutan terhadap kedua saksi itu, bahwa mereka berdua telah berkhianat dengan mengambil sesuatu dari wasiat itu. Atau kedua saksi itu memberikan wasiat si mayat kepada orang lain yang mereka duga bahwa si mayat berwasiat kepada mereka untuk orang itu, kemudian hendaknya kedua saksi itu bersumpah untuk membela dirinya. Jika sang hakim melihat tanda-tanda kedustaan kedua orang saksi itu, maka hendaknya kesaksian mereka berdua ditolak dengan sumpah para ahli waris si mayat yang terdekat yang membuktikan kedustaan mereka dan membenarkan apa yang didakwakan oleh para ahli waris itu. Hukum yang menetapkan hak orang-orang yang diberi wasiat telah dinasakh oleh kesaksian para saksi dari ahli waris demikian pula kesaksian orang-orang yang bukan seagama dinasakh olehnya. Penuturan salat asar di sini hanyalah untuk memperberat sanksi; dan pengkhususan penyebutan dua orang saksi dari kalangan ahli waris terdekat si mayat adalah karena melihat kekhususan peristiwa yang menyangkut turunnya ayat ini. Mengenai peristiwa yang menyebabkan turunnya ayat ini ialah sebuah hadis yang diriwayatkan oleh Imam Bukhari, bahwa seorang lelaki dari kalangan Bani Sahm keluar bersama Tamim Ad-Dariy dan Addiy bin Badda yang keduanya adalah pemeluk agama Nasrani. Kemudian dalam perjalanan Sahmiy -lelaki dari Bani Sahm itu- meninggal di tanah suatu kaum yang penduduknya tidak ada seorang muslim pun. Tatkala keduanya tiba di Madinah seraya membawa harta harta peninggalan Sahmiy, para ahli warisnya merasa kehilangan sebuah piala yang terbuat dari perak dilapisi dengan emas milik pribadi Sahmiy. Maka permasalahan kedua saksi itu dilaporkan kepada Nabi saw., kemudian turunlah ayat pertama. Nabi saw. menyumpah kedua saksi itu, kemudian ternyata piala itu ditemukan, lalu mereka berkata, \"Kami telah membelinya dari Tamim dan Addiy.\" Setelah itu turun pula ayat yang kedua lalu dua orang lelaki dari kalangan keluarga Sahmiy berdiri mengucapkan sumpahnya. Di dalam riwayat Tirmizi disebutkan, bahwa Amr bin Ash dan seorang lelaki dari kalangan mereka bangkit kemudian mengucapkan sumpah mengingat Amr bin Ash lebih dekat kepadanya. Di dalam riwayat lain disebutkan, bahwa Sahmiy dalam perjalanannya itu mengalami sakit keras, lalu ia berwasiat kepada kedua temannya itu agar keduanya menyampaikan harta peninggalannya kepada keluarga yang akan mewarisinya. Tatkala Sahmiy meninggal dunia kedua orang temannya itu mengambil piala tersebut kemudian mereka menyerahkan sisanya kepada ahli warisnya.",[["فَإِنْ","Kemudian jika"],["عُثِرَ","ia ditemui"],["عَلَىٰٓ","(hidup)"],["أَنَّهُمَا","bahawa kedua-duanya"],["ٱسْتَحَقَّآ","(adalah) bersalah"],["إِثْمًۭا","(dari) dosa"],["فَـَٔاخَرَانِ","maka (biarkan) dua orang yang lain"],["يَقُومَانِ","berdiri"],["مَقَامَهُمَا","(di) tempat mereka"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["ٱسْتَحَقَّ","mempunyai hak yang sah"],["عَلَيْهِمُ","atas mereka"],["ٱلْأَوْلَيَـٰنِ","dua yang dahulu"],["فَيُقْسِمَانِ","dan hendaklah mereka berdua bersumpah"],["بِٱللَّهِ","oleh Allah"],["لَشَهَـٰدَتُنَآ","Pasti testimoni kami"],["أَحَقُّ","(adalah) lebih benar"],["مِن","daripada"],["شَهَـٰدَتِهِمَا","keterangan dua orang lagi"],["وَمَا","dan bukan"],["ٱعْتَدَيْنَآ","kami telah melampaui batas"],["إِنَّآ","Sesungguhnya kami"],["إِذًۭا","kemudian"],["لَّمِنَ","(akan) daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"777":["(Hal itu) hukum yang telah disebutkan itu, yaitu yang menyangkut perpindahan sumpah kepada para ahli waris (lebih dekat) lebih mendekati untuk (menjadikan mereka mau mengemukakan) artinya para saksi itu atau orang-orang yang diwasiatkan (persaksiannya menurut apa yang sebenarnya) yang mendorong mereka untuk mengemukakan persaksian tanpa diubah-ubah dan juga tanpa khianat (atau) lebih dekat untuk menjadikan mereka (merasa takut akan dikembalikan sumpahnya sesudah mereka bersumpah) kepada para ahli waris yang mengajukan tuntutan, maka ahli waris si mayat melakukan sumpah yang menyatakan khianat mereka dan kedustaan yang mereka lakukan yang akibatnya mereka akan ditelanjangi kejelekannya hingga mereka harus mengganti kerugian kepada ahli waris mayat, oleh karena itu janganlah kamu berdusta. (Dan bertakwalah kamu kepada Allah) dengan cara meninggalkan perbuatan khianat dan dusta (dan dengarkanlah olehmu) dengan pendengaran yang insaf akan hal-hal yang kamu diperintahkan melakukannya (dan Allah tidak memberi petunjuk kepada orang-orang yang fasik) orang-orang yang keluar dari garis ketaatan terhadap-Nya atau orang-orang yang menyimpang dari jalan yang baik.",[["ذَٰلِكَ","Itu"],["أَدْنَىٰٓ","(adalah) lebih dekat"],["أَن","bahawa"],["يَأْتُوا۟","mereka akan memberi"],["بِٱلشَّهَـٰدَةِ","kesaksian"],["عَلَىٰ","dalam"],["وَجْهِهَآ","bentuknya (sebenar)."],["أَوْ","atau"],["يَخَافُوٓا۟","mereka akan takut"],["أَن","bahawa"],["تُرَدَّ","akan disangkal"],["أَيْمَـٰنٌۢ","sumpah mereka"],["بَعْدَ","selepas"],["أَيْمَـٰنِهِمْ ۗ","sumpah mereka (orang lain)."],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["وَٱسْمَعُوا۟ ۗ","dan dengar"],["وَٱللَّهُ","dan Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"778":["Ingatlah! (hari di waktu Allah mengumpulkan para rasul) yaitu pada hari kiamat (lalu Allah bertanya) kepada mereka dengan nada mencela yang ditujukan kepada kaum mereka (Apa) yang (jawaban kaummu terhadap seruanmu?) tatkala kamu mengajak mereka kepada ketauhidan (Para rasul menjawab, \"Tidak ada pengetahuan kami) tentang hal itu (sesungguhnya Engkaulah yang mengetahui perkara yang gaib.\") apa-apa yang tidak bisa dijangkau oleh pengetahuan hamba-hamba-Nya dan gaib di mata mereka oleh sebab kengerian yang mereka hadapi pada saat hari kiamat yang membuat mereka kaget. Kemudian para rasul itu menjadi saksi terhadap umat mereka masing-masing tatkala umat mereka diam seribu bahasa.",[["۞ يَوْمَ","(The) hari"],["يَجْمَعُ","akan (akan) dikumpulkan"],["ٱللَّهُ","(oleh) Allah"],["ٱلرُّسُلَ","para Rasul"],["فَيَقُولُ","dan Dia akan berkata"],["مَاذَآ","Apa"],["أُجِبْتُمْ ۖ","adalah (respon) yang kamu terima"],["قَالُوا۟","Mereka berkata"],["لَا","(Ada) tidak"],["عِلْمَ","pengetahuan"],["لَنَآ ۖ","bagi kami"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","kamu"],["عَلَّـٰمُ","(adalah) Yang Maha Mengetahui"],["ٱلْغُيُوبِ","(dari) yang ghaib"]]],"779":["Ingatlah! (ketika Allah mengatakan, \"Hai Isa putra Maryam! Ingatlah nikmat-Ku kepadamu dan kepada ibumu) syukurilah nikmat-Ku itu (di waktu Aku mendukung kamu) menguatkan kamu (dengan ruhul kudus) malaikat Jibril (kamu dapat berbicara dengan manusia) menjadi hal bagi kaaf atau dhamir mukhathab yang terdapat dalam kalimat ayyadtuka (sewaktu dalam buaian) masih dalam keadaan bayi (dan sesudah dewasa) kalimat ini memberikan pengertian bahwa ia (Nabi Isa) akan turun ke bumi sebelum hari kiamat sebab sebelum ia mencapai usia tua telah diangkat terlebih dahulu ke langit sebagaimana penjelasan yang telah dikemukakan dalam surah Ali Imran. (Dan ingatlah di waktu Aku mengajar kamu menulis, hikmah, Taurat dan Injil dan ingat pula di waktu kamu membuat suatu bentuk dari tanah yang berupa) seperti gambaran (burung) huruf kaaf dalam kalimat kahaiah adalah bermakna isim yang artinya seperti dan kedudukan i`rabnya menjadi maf`ul atau objek (dengan seizin-Ku kemudian kamu meniup padanya lalu bentuk itu menjadi burung yang sebenarnya seizin-Ku) dengan kehendak-Ku. (Dan ingatlah waktu kamu menyembuhkan orang yang buta dan orang yang berpenyakit sopak dengan seizin-Ku, dan ingatlah di waktu kamu mengeluarkan orang-orang mati) dari kuburan-kuburan mereka dalam keadaan hidup (dengan seizin-Ku, dan ingatlah di waktu Aku menghalangi Bani Israel dari kamu) sewaktu mereka bersengaja hendak membunuhmu (di kala kamu mengemukakan kepada mereka keterangan-keterangan yang nyata) yakni mukjizat-mukjizat (lalu orang-orang kafir di antara mereka berkata, 'Tidak) tidak lain (hal ini) yang engkau datangkan melainkan sihir yang nyata') dan menurut qiraat dibaca saahirun/tukang sihir, yang dimaksud ialah Nabi Isa.",[["إِذْ","Apabila"],["قَالَ","berkata"],["ٱللَّهُ","Allah"],["يَـٰعِيسَى","Wahai Isa"],["ٱبْنَ","nak"],["مَرْيَمَ","(dari) Maryam"],["ٱذْكُرْ","Ingat"],["نِعْمَتِى","Nikmat Aku"],["عَلَيْكَ","ke atas kamu"],["وَعَلَىٰ","dan seterusnya"],["وَٰلِدَتِكَ","ibu kamu"],["إِذْ","apabila"],["أَيَّدتُّكَ","Aku kuatkan kamu"],["بِرُوحِ","dengan (Roh)."],["ٱلْقُدُسِ","yang Suci"],["تُكَلِّمُ","kamu cakap"],["ٱلنَّاسَ","(kepada) rakyat"],["فِى","dalam"],["ٱلْمَهْدِ","buaian"],["وَكَهْلًۭا ۖ","dan (dalam) matang"],["وَإِذْ","Dan apabila"],["عَلَّمْتُكَ","aku ajar kamu"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحِكْمَةَ","dan hikmahnya"],["وَٱلتَّوْرَىٰةَ","dan Taurat"],["وَٱلْإِنجِيلَ ۖ","dan Injeel"],["وَإِذْ","dan apabila"],["تَخْلُقُ","kamu buat"],["مِنَ","daripada"],["ٱلطِّينِ","tanah liat"],["كَهَيْـَٔةِ","seperti bentuk"],["ٱلطَّيْرِ","(dari) burung itu"],["بِإِذْنِى","dengan izin-Ku"],["فَتَنفُخُ","kemudian kamu bernafas"],["فِيهَا","ke dalamnya"],["فَتَكُونُ","dan ia menjadi"],["طَيْرًۢا","seekor burung"],["بِإِذْنِى ۖ","dengan izin-Ku"],["وَتُبْرِئُ","dan kamu sembuh"],["ٱلْأَكْمَهَ","yang dilahirkan buta"],["وَٱلْأَبْرَصَ","dan kusta"],["بِإِذْنِى ۖ","dengan izin-Ku"],["وَإِذْ","dan apabila"],["تُخْرِجُ","kamu melahirkan"],["ٱلْمَوْتَىٰ","yang mati"],["بِإِذْنِى ۖ","dengan izin-Ku"],["وَإِذْ","Dan apabila"],["كَفَفْتُ","Aku menahan"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["عَنكَ","daripada kamu"],["إِذْ","apabila"],["جِئْتَهُم","kamu datang kepada mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَقَالَ","lalu berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْهُمْ","antara mereka"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["سِحْرٌۭ","sihir"],["مُّبِينٌۭ","yang nyata"]]],"780":["(Dan ingatlah ketika Aku ilhamkan kepada para pengikut Nabi Isa yang setia) Aku perintahkan mereka melalui lisannya (hendaknya) (kamu beriman kepada-Ku dan kepada rasul-Ku.\") yaitu Nabi Isa (Mereka menjawab, \"Kami telah beriman) kepada Allah dan rasul-Nya (dan saksikanlah, wahai rasul, bahwa sesungguhnya kami adalah orang-orang yang berserah diri kepada seruanmu.\")",[["وَإِذْ","Dan apabila"],["أَوْحَيْتُ","Aku memberi inspirasi"],["إِلَى","kepada"],["ٱلْحَوَارِيِّـۧنَ","para murid"],["أَنْ","kepada"],["ءَامِنُوا۟","beriman"],["بِى","dalam Aku"],["وَبِرَسُولِى","dan dalam Rasul-Ku"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["وَٱشْهَدْ","dan menjadi saksi"],["بِأَنَّنَا","bahawa sesungguhnya kita"],["مُسْلِمُونَ","(adalah) orang Islam"]]],"781":["Ingatlah (Ketika pengikut-pengikut Isa berkata, \"Hai Isa putra Maryam! Sanggupkah) artinya bisakah (Tuhanmu) menurut satu qiraat dibaca tastathii'u kemudian lafal yang sesudahnya dibaca nashab/rabbaka, yang artinya apakah engkau bisa meminta kepada-Nya (menurunkan hidangan dari langit kepada kami?\" Menjawab) kepada mereka Isa (\"Bertakwalah kepada Allah) di dalam meminta bukti-bukti itu/mukjizat-mukjizat (jika betul-betul kamu orang yang beriman.\")",[["إِذْ","Apabila"],["قَالَ","berkata"],["ٱلْحَوَارِيُّونَ","para murid"],["يَـٰعِيسَى","Wahai Isa"],["ٱبْنَ","nak"],["مَرْيَمَ","(dari) Maryam"],["هَلْ","Adakah"],["يَسْتَطِيعُ","mampu"],["رَبُّكَ","Tuhanmu"],["أَن","kepada"],["يُنَزِّلَ","hantar ke bawah"],["عَلَيْنَا","kepada kami"],["مَآئِدَةًۭ","terbentang meja"],["مِّنَ","daripada"],["ٱلسَّمَآءِ ۖ","syurga itu"],["قَالَ","Dia berkata"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"782":["(Mereka berkata, \"Kami menginginkan) dengan permintaan ini agar (agar bisa memakan hidangan itu dan supaya menjadi tenteram) menjadi tenang/mantap (hati kami) semakin bertambah yakin (dan supaya kami mengetahui) kami makin bertambah pengetahuan (bahwa) an mukhaffafah; artinya bahwa sesungguhnya (kamu telah berkata benar kepada kami) dalam pengakuanmu menjadi nabi (dan kami menjadi orang-orang yang menyaksikan hidangan itu.\")",[["قَالُوا۟","Mereka berkata"],["نُرِيدُ","Kami berharap"],["أَن","bahawa"],["نَّأْكُلَ","kita makan"],["مِنْهَا","daripadanya"],["وَتَطْمَئِنَّ","dan memuaskan"],["قُلُوبُنَا","hati kita"],["وَنَعْلَمَ","dan kita tahu"],["أَن","bahawa"],["قَدْ","sudah tentu"],["صَدَقْتَنَا","kamu telah bercakap benar kepada kami"],["وَنَكُونَ","dan kita jadi"],["عَلَيْهَا","atasnya"],["مِنَ","antara"],["ٱلشَّـٰهِدِينَ","para saksi"]]],"783":["(Isa Putra Maryam berdoa, \"Ya Tuhan kami! Turunkanlah kiranya kepada kami suatu hidangan dari langit yang hal itu bagi kami) artinya pada hari turunnya hidangan itu (menjadi hari raya) yang kami hormati dan kami muliakan (bagi orang-orang sezaman dengan kami) kalimat ini menjadi badal/kalimat pengganti bagi lafal lanaa, yang juga disertai pula dengan huruf jarnya (dan bagi orang-orang yang datang sesudah kami) orang-orang yang akan datang sesudah kami (dan menjadi tanda kekuasaan Engkau) yang menunjukkan akan kekuasaan-Mu dan kenabianku (berilah kami rezeki) dengan hidangan tersebut (dan Engkaulah Pemberi rezeki Yang Paling Utama.\")",[["قَالَ","Berkata"],["عِيسَى","Isa"],["ٱبْنُ","nak"],["مَرْيَمَ","(dari) Maryam"],["ٱللَّهُمَّ","Ya Allah"],["رَبَّنَآ","Tuhan kami"],["أَنزِلْ","hantar ke bawah"],["عَلَيْنَا","kepada kami"],["مَآئِدَةًۭ","terbentang meja"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["تَكُونُ","menjadi"],["لَنَا","bagi kami"],["عِيدًۭا","satu perayaan"],["لِّأَوَّلِنَا","untuk kita yang pertama"],["وَءَاخِرِنَا","dan terakhir kita"],["وَءَايَةًۭ","dan tanda"],["مِّنكَ ۖ","daripada Engkau"],["وَٱرْزُقْنَا","Dan sediakan kami"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) terbaik"],["ٱلرَّٰزِقِينَ","(daripada) penyedia"]]],"784":["(Allah berfirman) mengabulkan doanya (\"Sesungguhnya Aku akan menurunkan hidangan itu) boleh dibaca takhfif/munziluhaa dan boleh pula dibaca tasydid/munazziluhaa (kepadamu; siapa yang kafir sesudah) artinya sesudah diturunkannya hidangan itu (di antara kamu, maka sesungguhnya Aku akan menyiksanya dengan siksaan yang tidak pernah Aku timpakan kepada seseorang pun di antara umat manusia.\") kemudian turunlah malaikat-malaikat seraya membawa hidangan dari langit berupa tujuh buah roti dan tujuh macam lauk-pauk. Kemudian mereka memakan sebagian darinya hingga semuanya merasa kenyang. Demikianlah menurut riwayat Ibnu Abbas dalam hadisnya sehubungan dengan kisah mengenai turunnya hidangan dari langit ini. Hadisnya itu mengatakan, bahwa hidangan itu berupa roti dan daging, kemudian mereka diperintahkan agar jangan berkhianat dan juga jangan menyimpannya hingga keesokan harinya. Akan tetapi mereka berkhianat dan menyimpan sebagian hidangan itu, akhirnya mereka dikutuk menjadi kera-kera dan babi-babi.",[["قَالَ","Berkata"],["ٱللَّهُ","Allah"],["إِنِّى","Sesungguhnya aku"],["مُنَزِّلُهَا","(akan) menurunkannya"],["عَلَيْكُمْ ۖ","kepada kamu"],["فَمَن","maka sesiapa"],["يَكْفُرْ","tidak beriman"],["بَعْدُ","selepas (itu)"],["مِنكُمْ","antara kamu"],["فَإِنِّىٓ","maka sesungguhnya aku"],["أُعَذِّبُهُۥ","[Aku] akan menghukum dia"],["عَذَابًۭا","(dengan) hukuman"],["لَّآ","tidak"],["أُعَذِّبُهُۥٓ","Aku telah menghukum"],["أَحَدًۭا","sesiapa sahaja"],["مِّنَ","antara"],["ٱلْعَـٰلَمِينَ","dunia"]]],"785":["(Dan) ingatlah (ketika berfirman) artinya akan berfirman (Allah) kepada Isa di hari kiamat sebagai penghinaan terhadap kaumnya (\"Hai Isa putra Maryam! Adakah kamu mengatakan kepada manusia, 'Jadikanlah aku dan ibuku dua orang tuhan selain Allah?' Ia menjawab) Isa menjawab seraya gemetar ('Maha Suci Engkau) aku menyucikan-Mu dari apa-apa yang tidak layak bagi-Mu seperti sekutu dan lain-lainnya (tidaklah patut) tidak pantas (bagiku mengatakan apa yang bukan hakku mengatakannya) bihaqqin menjadi khabar dari laisa sedangkan kata lii adalah untuk penjelas/tabyin (jika aku pernah mengatakannya maka tentulah Engkau mengetahuinya. Engkau mengetahui apa) yang aku sembunyikan (pada diriku dan aku tidak mengetahui apa yang ada pada diri Engkau) artinya apa-apa yang Engkau sembunyikan di antara pengetahuan-pengetahuan Engkau (Sesungguhnya Engkau Maha Mengetahui perkara yang gaib-gaib.)",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["ٱللَّهُ","Allah"],["يَـٰعِيسَى","Wahai Isa"],["ٱبْنَ","nak"],["مَرْيَمَ","(dari) Maryam"],["ءَأَنتَ","Adakah kamu"],["قُلْتَ","berkata"],["لِلنَّاسِ","kepada rakyat"],["ٱتَّخِذُونِى","Bawa aku"],["وَأُمِّىَ","dan ibu aku"],["إِلَـٰهَيْنِ","(sebagai) dua tuhan"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ ۖ","Allah"],["قَالَ","Dia berkata"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["مَا","Tidak"],["يَكُونُ","adalah"],["لِىٓ","untuk aku"],["أَنْ","bahawa"],["أَقُولَ","aku cakap"],["مَا","apa"],["لَيْسَ","tidak"],["لِى","aku"],["بِحَقٍّ ۚ","(ada) betul"],["إِن","Jika"],["كُنتُ","aku ada"],["قُلْتُهُۥ","berkata ia"],["فَقَدْ","maka pasti"],["عَلِمْتَهُۥ ۚ","Kamu pasti mengetahuinya"],["تَعْلَمُ","kamu tahu"],["مَا","apa"],["فِى","(berada) dalam"],["نَفْسِى","diri sendiri"],["وَلَآ","dan bukan"],["أَعْلَمُ","aku tahu"],["مَا","apa"],["فِى","(berada) dalam"],["نَفْسِكَ ۚ","diri sendiri"],["إِنَّكَ","Sesungguhnya, Engkau"],["أَنتَ","kamu"],["عَلَّـٰمُ","(adalah) Maha Mengetahui"],["ٱلْغُيُوبِ","(dari) yang ghaib"]]],"786":["(Aku tidak pernah mengatakan kepada mereka kecuali apa yang telah Engkau perintahkan kepadaku untuk mengatakannya) yaitu: ('Sembahlah Allah Tuhanku dan Tuhanmu dan adalah aku menjadi saksi terhadap mereka) sebagai pengawas yang mencegah mereka dari apa yang mereka katakan itu (selama aku berada di antara mereka. Maka setelah Engkau wafatkan aku) Engkau telah mengambilku dengan cara mengangkatku ke langit (Engkaulah yang menguasai mereka) yang memelihara amal perbuatan mereka. (Sesungguhnya Engkau atas segala sesuatu) termasuk perkataanku kepada mereka dan perkataan mereka sesudahku dan lain-lainnya (Maha Menyaksikan) Maha Waspada dan Maha Mengetahui tentang hal itu.",[["مَا","Tidak"],["قُلْتُ","kata aku"],["لَهُمْ","kepada mereka"],["إِلَّا","kecuali"],["مَآ","apa"],["أَمَرْتَنِى","Kamu perintahkan aku"],["بِهِۦٓ","[dengannya]"],["أَنِ","bahawa"],["ٱعْبُدُوا۟","kamu sembah"],["ٱللَّهَ","Allah"],["رَبِّى","Tuhanku"],["وَرَبَّكُمْ ۚ","dan Tuhanmu"],["وَكُنتُ","Dan aku"],["عَلَيْهِمْ","atas mereka"],["شَهِيدًۭا","seorang saksi"],["مَّا","bahawa"],["دُمْتُ","asalkan aku"],["فِيهِمْ ۖ","(ada) di antara mereka"],["فَلَمَّا","kemudian apabila"],["تَوَفَّيْتَنِى","Kamu membesarkan aku"],["كُنتَ","kamu tadi"],["أَنتَ","[Kamu]"],["ٱلرَّقِيبَ","Pemerhati"],["عَلَيْهِمْ ۚ","atas mereka"],["وَأَنتَ","dan kamu"],["عَلَىٰ","(ada) pada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["شَهِيدٌ","seorang Saksi"]]],"787":["(Jika Engkau menyiksa mereka) artinya orang-orang yang melakukan kekafiran di antara mereka (maka sesungguhnya mereka adalah hamba-hamba Engkau) Engkau adalah Yang Menguasai mereka; Engkaulah yang berhak memperlakukan mereka menurut apa yang Engkau kehendaki, tak ada yang bisa menghalang-halangi Engkau (dan jika Engkau mengampuni mereka) artinya mengampuni orang-orang yang beriman di antara mereka (maka sesungguhnya Engkaulah Yang Maha Perkasa) Yang Maha Menang perkara-Nya (lagi Maha Bijaksana'\") dalam perbuatan-Nya.",[["إِن","Jika"],["تُعَذِّبْهُمْ","Kamu menghukum mereka"],["فَإِنَّهُمْ","maka sesungguhnya mereka"],["عِبَادُكَ ۖ","(adalah) hamba-hamba kamu"],["وَإِن","dan jika"],["تَغْفِرْ","kamu maafkan"],["لَهُمْ","[untuk] mereka"],["فَإِنَّكَ","maka sesungguhnya Engkau"],["أَنتَ","kamu"],["ٱلْعَزِيزُ","(adalah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"788":["(Allah berfirman, \"Ini adalah) artinya hari kiamat (suatu hari yang bermanfaat orang-orang yang benar) sewaktu di dunia seperti Nabi Isa (kebenaran mereka) sebab hari itu adalah hari pembalasan (bagi mereka surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya untuk selama-lamanya; Allah rida terhadap mereka) oleh sebab ketaatan terhadap-Nya (dan mereka pun rida terhadap-Nya) dengan pahala-Nya (Itulah keberuntungan yang besar.\") dan orang-orang pendusta sewaktu hidup di dunia, tidak akan bisa bermanfaat kejujuran mereka pada hari itu seperti orang-orang kafir, yaitu tatkala mereka mulai percaya dan iman sewaktu mereka melihat azab Allah.",[["قَالَ","Akan berkata"],["ٱللَّهُ","Allah"],["هَـٰذَا","Ini"],["يَوْمُ","Hari"],["يَنفَعُ","akan untung"],["ٱلصَّـٰدِقِينَ","yang benar"],["صِدْقُهُمْ ۚ","kebenaran mereka"],["لَهُمْ","Untuk mereka"],["جَنَّـٰتٌۭ","(adalah) Taman-taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","akan kekal"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۚ","selama-lamanya"],["رَّضِىَ","berpuas hati"],["ٱللَّهُ","Allah"],["عَنْهُمْ","bersama mereka"],["وَرَضُوا۟","dan mereka redha"],["عَنْهُ ۚ","dengan Dia"],["ذَٰلِكَ","Itu"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","(yang) hebat"]]],"789":["(Kepunyaan Allahlah kerajaan langit dan bumi) tempat-tempat penyimpanan hujan, semua tumbuhan, semua rezeki dan lain-lainnya (dan apa yang ada di dalamnya) dipergunakan kata maa, karena kebanyakan makhluk Allah itu terdiri dari yang tidak berakal (dan Dia Maha Kuasa atas segala sesuatu) di antara kekuasaan-Nya itu ialah memberi pahala kepada orang yang berbuat benar, dan menyiksa orang yang berbuat dusta.",[["لِلَّهِ","Kepunyaan Allah (kepunyaan)"],["مُلْكُ","kekuasaan itu"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa"],["فِيهِنَّ ۚ","(ada) pada mereka"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۢ","Maha Berkuasa"]]],"790":["(Segala puji) yaitu ungkapan tentang sifat yang baik lagi tetap (bagi Allah) apakah yang dimaksud dengan pemberitaan dalam bentuk ini sebagai ungkapan rasa iman terhadap-Nya ataukah hanya sebagai panjatan puji kepada-Nya atau memang untuk maksud keduanya? Memang mengandung beberapa hipotesis akan tetapi hipotesis yang paling banyak faedahnya ialah yang ketiga, demikianlah menurut pendapat Syekh di dalam surah Al-Kahfi (Yang telah menciptakan langit dan bumi) Allah menyebutkan keduanya secara khusus mengingat keduanya adalah makhluk ciptaan Allah yang paling besar di mata orang-orang yang menyaksikannya (dan mengadakan) menjadikan (gelap dan terang) artinya setiap yang gelap dan terang; pengungkapan kata gelap dengan bentuk jamak sedangkan untuk terang tidak karena gelap itu mempunyai banyak penyebabnya. Hal ini merupakan sebagian dari bukti-bukti keesaan-Nya (namun orang-orang yang kafir) sekalipun dengan adanya bukti ini (terhadap Tuhan mereka adalah orang-orang yang mempersekutukan-Nya) mereka menyamakan selain Allah dalam hal ibadah.",[["ٱلْحَمْدُ","(Segala) pujian dan terima kasih"],["لِلَّهِ","bagi Allah"],["ٱلَّذِى","yang Esa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَجَعَلَ","dan dibuat"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["وَٱلنُّورَ ۖ","dan cahaya"],["ثُمَّ","Kemudian"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["بِرَبِّهِمْ","pada Tuhan mereka"],["يَعْدِلُونَ","samakan orang lain dengan Dia"]]],"791":["(Dialah Yang menciptakanmu dari tanah) dengan diciptakan-Nya ayah kamu Adam dari tanah (sesudah itu ditentukan-Nya ajal) bagi kamu, setelah sampai pada ajal itu kamu akan mati (dan ajal lain yang ditentukan) ditetapkan (di sisi-Nya) untuk membangkitkan kamu dari kematian (kemudian kamu) hai orang-orang kafir (masih tidak percaya tentang berbangkit itu) kamu masih meragukan tentang adanya hari berbangkit padahal sebelumnya kamu telah mengetahui, bahwa Dialah yang mulai menciptakanmu. Dan siapa yang mampu menciptakan berarti Dia lebih mampu untuk mengembalikan ke asalnya.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَكُم","mencipta kamu"],["مِّن","daripada"],["طِينٍۢ","tanah liat"],["ثُمَّ","kemudian"],["قَضَىٰٓ","Dia memutuskan"],["أَجَلًۭا ۖ","satu istilah"],["وَأَجَلٌۭ","dan istilah"],["مُّسَمًّى","ditentukan"],["عِندَهُۥ ۖ","dengan Dia"],["ثُمَّ","belum lagi"],["أَنتُمْ","kamu"],["تَمْتَرُونَ","keraguan"]]],"792":["(Dan Dialah Allah) yang berhak untuk disembah dan dipuja (baik di langit maupun di bumi, Dia mengetahui apa yang kamu rahasiakan dan apa yang kamu lahirkan) hal-hal yang kamu sembunyikan dan hal-hal yang kamu tampakkan di antara kamu sekalian (dan mengetahui pula apa yang kamu usahakan) perkara baik dan perkara buruk yang kamu ketahui.",[["وَهُوَ","Dan Dia"],["ٱللَّهُ","(ialah) Allah"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَفِى","dan dalam"],["ٱلْأَرْضِ ۖ","bumi"],["يَعْلَمُ","Dia tahu"],["سِرَّكُمْ","rahsia kamu"],["وَجَهْرَكُمْ","dan apa yang kamu umumkan"],["وَيَعْلَمُ","dan Dia mengetahui"],["مَا","apa"],["تَكْسِبُونَ","kamu mendapat"]]],"793":["(Dan tidak ada yang sampai kepada mereka) artinya penduduk Mekah (berupa) huruf min adalah tambahan/zaidah (suatu ayat dari ayat-ayat Tuhan mereka) dari Alquran (melainkan mereka selalu berpaling daripadanya.)",[["وَمَا","Dan tidak"],["تَأْتِيهِم","datang kepada mereka"],["مِّنْ","[daripada]"],["ءَايَةٍۢ","sebarang tanda"],["مِّنْ","daripada"],["ءَايَـٰتِ","(the) Tanda-tanda"],["رَبِّهِمْ","(dari) Tuhan mereka"],["إِلَّا","tetapi"],["كَانُوا۟","mereka adalah"],["عَنْهَا","daripadanya"],["مُعْرِضِينَ","berpaling"]]],"794":["(Sesungguhnya mereka telah mendustakan yang hak) yakni Alquran (tatkala sampai kepada mereka maka akan sampai kepada mereka berita-berita) akibat-akibat (yang selalu mereka perolok-olokkan.)",[["فَقَدْ","Maka sesungguhnya"],["كَذَّبُوا۟","mereka menafikan"],["بِٱلْحَقِّ","kebenaran"],["لَمَّا","apabila"],["جَآءَهُمْ ۖ","ia datang kepada mereka"],["فَسَوْفَ","tetapi tidak lama lagi"],["يَأْتِيهِمْ","akan datang kepada mereka"],["أَنۢبَـٰٓؤُا۟","berita"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","[padanya]"],["يَسْتَهْزِءُونَ","mengejek"]]],"795":["(Apakah mereka tidak memperhatikan) dalam perjalanan-perjalanan mereka menuju ke negeri Syam dan negeri-negeri lainnya (berapa banyak) kalimat khabariah atau bukan kata tanya yang artinya betapa banyaknya (generasi-generasi yang telah Kami binasakan sebelum mereka) umat-umat yang terdahulu (padahal mereka telah Kami teguhkan) Kami berikan kedudukan (di muka bumi) melalui kekuatan dan kekuasaannya (yaitu keteguhan yang belum pernah Kami menganugerahkan) Kami berikan (kepadamu) dalam Lafal ini terkandung pengertian iltifat/peralihan dari orang ketiga ke orang kedua yang maksudnya ditujukan kepada orang ketiga (dan Kami curahkan) hujan (atas mereka dengan derasnya) tahap demi tahap (dan Kami jadikan sungai-sungai mengalir di bawah mereka) di bawah rumah-rumah tempat tinggal mereka (kemudian Kami binasakan mereka karena dosa-dosa mereka sendiri) oleh sebab kedustaan mereka terhadap para nabi (dan Kami ciptakan sesudah mereka generasi yang lain.)",[["أَلَمْ","tidak"],["يَرَوْا۟","mereka lihat"],["كَمْ","berapa ramai"],["أَهْلَكْنَا","Kami musnahkan"],["مِن","daripada"],["قَبْلِهِم","sebelum mereka"],["مِّن","daripada"],["قَرْنٍۢ","generasi"],["مَّكَّنَّـٰهُمْ","Kami telah menubuhkan mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مَا","apa"],["لَمْ","tidak"],["نُمَكِّن","Kami (telah) menubuhkan"],["لَّكُمْ","bagi kamu"],["وَأَرْسَلْنَا","Dan Kami telah mengutus"],["ٱلسَّمَآءَ","(hujan dari) langit"],["عَلَيْهِم","ke atas mereka"],["مِّدْرَارًۭا","mandi dengan banyaknya"],["وَجَعَلْنَا","dan Kami jadikan"],["ٱلْأَنْهَـٰرَ","sungai-sungai"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهِمْ","di bawah mereka"],["فَأَهْلَكْنَـٰهُم","Kemudian Kami binasakan mereka"],["بِذُنُوبِهِمْ","kerana dosa mereka"],["وَأَنشَأْنَا","dan Kami bangkitkan"],["مِنۢ","daripada"],["بَعْدِهِمْ","selepas mereka"],["قَرْنًا","generasi"],["ءَاخَرِينَ","lain"]]],"796":["(Dan kalau Kami turunkan kepadamu sebuah kitab) yang tertulis (di atas kertas) yang tipis seperti apa yang mereka minta (lalu mereka dapat memegangnya dengan tangan mereka) lebih akurat daripada seandainya mereka hanya menyaksikan saja sebab cara ini jelas lebih menghapuskan rasa ragu (tentulah orang-orang kafir itu mengatakan, \"Tiada) tidak lain (hal ini adalah sihir yang nyata.\") sebagai ungkapan rasa ketidakpercayaan dan keingkaran mereka.",[["وَلَوْ","Dan (walaupun) jika"],["نَزَّلْنَا","Kami (telah) menurunkan"],["عَلَيْكَ","kepada kamu"],["كِتَـٰبًۭا","sebuah Kitab Suci yang tertulis"],["فِى","dalam"],["قِرْطَاسٍۢ","kertas kulit"],["فَلَمَسُوهُ","dan mereka menyentuhnya"],["بِأَيْدِيهِمْ","dengan tangan mereka"],["لَقَالَ","nescaya (akan) berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["سِحْرٌۭ","sihir"],["مُّبِينٌۭ","yang nyata"]]],"797":["(Dan mereka berkata, \"Mengapa tidak) kenapa tidak (diturunkan kepadanya) kepada Nabi Muhammad saw. (seorang malaikat?\") yang membenarkannya (dan kalau Kami turunkan kepadanya seorang malaikat) sebagaimana yang telah mereka minta, niscaya mereka tidak akan beriman (tentu selesailah urusan itu) dengan binasanya mereka (kemudian mereka tidak ditangguhkan) tidak diberi kesempatan untuk bertobat atau minta ampunan, seperti yang telah dilakukan oleh Allah terhadap orang-orang sebelum mereka, yaitu di kala permintaan mereka dikabulkan, kemudian mereka tidak juga mau beriman.",[["وَقَالُوا۟","Dan mereka berkata"],["لَوْلَآ","Kenapa belum"],["أُنزِلَ","diturunkan"],["عَلَيْهِ","kepadanya"],["مَلَكٌۭ ۖ","seorang Malaikat"],["وَلَوْ","Dan jika"],["أَنزَلْنَا","Kami (telah) menurunkan"],["مَلَكًۭا","seorang Malaikat"],["لَّقُضِىَ","nescaya (akan) telah diputuskan"],["ٱلْأَمْرُ","perkara itu"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُنظَرُونَ","tangguh akan diberikan kepada mereka"]]],"798":["(Dan kalau Kami jadikan rasul itu) yang diutus untuk mereka (seorang malaikat, tentulah Kami jadikan dia) artinya malaikat itu berupa (seorang laki-laki) artinya berbentuk seorang laki-laki supaya mereka bisa melihatnya, sebab manusia itu tidak akan kuat untuk melihat malaikat (dan) seandainya Kami menurunkannya lalu menjadikannya sebagai seorang laki-laki (niscaya akan Kami serupakan) Kami miripkan (atas mereka apa yang membuat mereka ragu) terhadap diri mereka, sebab mereka pasti mengatakan bahwa malaikat ini tidak lain kecuali seorang manusia seperti kamu.",[["وَلَوْ","Dan jika"],["جَعَلْنَـٰهُ","Kami telah membuatnya"],["مَلَكًۭا","seorang Malaikat"],["لَّجَعَلْنَـٰهُ","sesungguhnya Kami (akan) jadikan dia"],["رَجُلًۭا","seorang lelaki"],["وَلَلَبَسْنَا","dan sesungguhnya Kami (akan) mengaburkan"],["عَلَيْهِم","kepada mereka"],["مَّا","apa"],["يَلْبِسُونَ","mereka mengaburkan"]]],"799":["(Dan sungguh telah diperolok-olokkan beberapa rasul sebelum kamu) ungkapan ini mengandung makna yang menghibur hati Nabi saw. (maka datanglah) turunlah (kepada orang-orang yang mencemoohkan di antara mereka sebagai akibat dari apa yang mereka perolok-olokkan) yang berupa azab; demikian pula siksaan itu akan menimpa orang-orang yang memperolok-olokkan kamu.",[["وَلَقَدِ","Dan sesungguhnya"],["ٱسْتُهْزِئَ","diejek"],["بِرُسُلٍۢ","Utusan"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["فَحَاقَ","tetapi dikelilingi"],["بِٱلَّذِينَ","orang yang"],["سَخِرُوا۟","mengejek"],["مِنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","[padanya]"],["يَسْتَهْزِءُونَ","mengejek"]]],"800":["(Katakanlah) kepada mereka (\"Berjalanlah di muka bumi kemudian perhatikanlah bagaimana kesudahan orang-orang yang mendustakan.\") rasul-rasul itu; yaitu kebinasaan mereka karena tertimpa azab supaya orang-orang yang memperolok-olokkanmu itu mengambil pelajaran darinya.",[["قُلْ","Katakanlah"],["سِيرُوا۟","Perjalanan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["ثُمَّ","dan"],["ٱنظُرُوا۟","lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُكَذِّبِينَ","(dari) orang-orang yang mendustakan"]]],"801":["(Katakanlah, \"Kepunyaan siapakah apa yang ada di langit dan di bumi?\" Katakanlah, \"Kepunyaan Allah.\") jika mereka tidak mengatakannya dan tidak ada jawaban lain kecuali itu. (Dia telah memastikan) telah menetapkan (atas diri-Nya kasih sayang) sebagai kemurahan dari-Nya. Ungkapan ini mengandung seruan yang lembut untuk mengajak mereka agar beriman (Dia sungguh-sungguh akan menghimpun kamu pada hari kiamat) untuk membalas kamu atas perbuatan-perbuatan kamu (tidak ada keraguan) kebimbangan (terhadapnya. Orang-orang yang merugikan dirinya) karena mereka menjerumuskan dirinya ke dalam siksaan. Alladziina adalah mubtada sedangkan khabarnya ialah (mereka itu tidak beriman).",[["قُل","Katakanlah"],["لِّمَن","milik siapa (kepunyaan)"],["مَّا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["قُل","Katakanlah"],["لِّلَّهِ ۚ","Kepada Allah"],["كَتَبَ","Dia telah menetapkan"],["عَلَىٰ","ke atas"],["نَفْسِهِ","dirinya sendiri"],["ٱلرَّحْمَةَ ۚ","kerahiman"],["لَيَجْمَعَنَّكُمْ","Sesungguhnya Dia akan mengumpulkan kamu"],["إِلَىٰ","pada"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["لَا","(ada) tidak"],["رَيْبَ","keraguan"],["فِيهِ ۚ","mengenainya"],["ٱلَّذِينَ","Orang yang"],["خَسِرُوٓا۟","dah kalah"],["أَنفُسَهُمْ","diri mereka"],["فَهُمْ","kemudian mereka"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"802":["(Dan kepunyaan Allahlah) Maha Luhur Allah (segala yang ada) yang berada (di malam hari dan di siang hari) artinya Dialah Tuhan segala sesuatu, Penciptanya dan Pemiliknya (Dan Dia Maha Mendengar) terhadap apa yang dikatakan (lagi Maha Mengetahui) atas apa yang diperbuat.",[["۞ وَلَهُۥ","Dan untuk Dia"],["مَا","(adalah) apa sahaja"],["سَكَنَ","berdiam"],["فِى","dalam"],["ٱلَّيْلِ","malam"],["وَٱلنَّهَارِ ۚ","dan hari"],["وَهُوَ","dan Dia"],["ٱلسَّمِيعُ","(ialah) Maha Mendengar"],["ٱلْعَلِيمُ","Maha Mengetahui"]]],"803":["(Katakanlah) kepada mereka (\"Apakah akan aku jadikan pelindung selain dari Allah) yang aku sembah (yang menjadikan langit dan bumi) Allah yang menciptakan keduanya (padahal Dia memberi makan) memberi rezeki (dan tidak diberi makan?\") tidak memerlukan rezeki (Katakanlah, \"Sesungguhnya aku diperintah supaya aku menjadi orang yang pertama sekali menyerahkan diri) kepada Allah dari kalangan umat ini (dan) dikatakan kepadaku (jangan sekali-kali kamu termasuk golongan orang-orang yang musyrik\") kepada-Nya.",[["قُلْ","Katakanlah"],["أَغَيْرَ","Adakah selain daripada"],["ٱللَّهِ","Allah"],["أَتَّخِذُ","Aku (harus) ambil"],["وَلِيًّۭا","(sebagai) pelindung"],["فَاطِرِ","Pencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَهُوَ","sedang (ialah) Dia"],["يُطْعِمُ","Siapa yang memberi makan"],["وَلَا","dan bukan"],["يُطْعَمُ ۗ","Dia diberi makan"],["قُلْ","Katakanlah"],["إِنِّىٓ","Sesungguhnya aku"],["أُمِرْتُ","[Aku] diperintahkan"],["أَنْ","bahawa"],["أَكُونَ","aku jadi"],["أَوَّلَ","(yang) pertama"],["مَنْ","yang"],["أَسْلَمَ ۖ","berserah diri (kepada Allah)"],["وَلَا","dan bukan"],["تَكُونَنَّ","jadilah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"804":["(Katakanlah, \"Sesungguhnya aku takut jika aku mendurhakai Tuhanku) dengan menyembah selain-Nya (azab hari yang besar.\") yaitu hari kiamat.",[["قُلْ","Katakanlah"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["إِنْ","jika"],["عَصَيْتُ","aku ingkar"],["رَبِّى","Tuhanku"],["عَذَابَ","hukuman"],["يَوْمٍ","(dari) sehari"],["عَظِيمٍۢ","perkasa"]]],"805":["(Siapa yang dijauhkan siksaan) dalam bentuk pasif, maf'ulnya azab/siksaan; dan dalam bentuk aktif, fa'ilnya Allah, sedangkan dhamirnya dibuang (daripadanya pada hari itu, maka sungguh Allah telah memberikan rahmat kepadanya) Maha Tinggi Allah, artinya Ia menghendaki kebaikan untuknya. (Dan itu keberuntungan yang nyata) keselamatan yang nyata.",[["مَّن","Siapa pun"],["يُصْرَفْ","dielakkan"],["عَنْهُ","daripadanya"],["يَوْمَئِذٍۢ","hari itu"],["فَقَدْ","maka pasti"],["رَحِمَهُۥ ۚ","Dia telah mengasihani dia"],["وَذَٰلِكَ","Dan bahawa"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْمُبِينُ","(yang) jelas"]]],"806":["(Jika Allah menimpakan suatu kemudaratan kepadamu) musibah, seperti sakit dan kemiskinan (maka tidak ada yang menghilangkannya) tidak ada yang bisa mengangkatnya (daripadanya selain Dia sendiri. Dan jika Dia mendatangkan kebaikan kepadamu) seperti kesehatan dan kecukupan (maka Dia Maha Kuasa atas tiap-tiap segala sesuatu) berada pada kekuasaan-Nyalah segala sesuatu itu; tidak ada seorang pun yang dapat menolaknya dari dirimu selain daripada-Nya sendiri.",[["وَإِن","Dan jika"],["يَمْسَسْكَ","menyentuh kamu"],["ٱللَّهُ","Allah"],["بِضُرٍّۢ","dengan penderitaan"],["فَلَا","maka tidak"],["كَاشِفَ","penghilang"],["لَهُۥٓ","daripadanya"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["وَإِن","Dan jika"],["يَمْسَسْكَ","Dia sentuh kamu"],["بِخَيْرٍۢ","dengan kebaikan"],["فَهُوَ","kemudian Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"807":["(Dan Dialah yang berkuasa) Maha Kuasa tidak ada sesuatu pun yang dapat melemahkan-Nya, Dia Maha Tinggi (atas sekalian hamba-hamba-Nya. Dan Dialah Yang Maha Bijaksana) atas makhluk-Nya (lagi Maha Mengetahui) Semua yang tersimpan dalam batin mereka sebagaimana halnya yang tampak pada mereka. Ayat berikut diturunkan berkenaan dengan pertanyaan yang mereka ajukan kepada Nabi saw., \"Datangkanlah kepada kami orang yang menyaksikan dirimu sebagai Nabi karena sesungguhnya orang-orang Ahli Kitab pun ingkar terhadap dirimu.\"",[["وَهُوَ","Dan Dia"],["ٱلْقَاهِرُ","(ialah) Penunduk"],["فَوْقَ","atas"],["عِبَادِهِۦ ۚ","hambanya"],["وَهُوَ","Dan Dia"],["ٱلْحَكِيمُ","(ialah) Yang Maha Bijaksana"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"808":["(Katakanlah) kepada mereka (\"Siapakah yang lebih kuat persaksiannya?\") menjadi tamyiz yang dialihkan dari mubtada (Katakanlah, \"Allah.\") jika kamu tidak mengatakannya, maka tidak ada jawaban lain bagimu selain itu. (Dia menjadi saksi antara aku dan kamu) yang menyaksikan kebenaranku. (Dan Alquran ini diwahyukan kepadaku supaya aku memberi peringatan kepadamu) aku membuat kamu takut hai penduduk Mekah (dengannya dan kepada orang-orang yang sampai kepadanya Alquran) diathafkan kepada dhamir yang terdapat dalam Lafal undzirakum; artinya manusia dan jin yang sampai kepadanya Alquran. (\"Apakah sesungguhnya kamu mengakui bahwa ada tuhan-tuhan yang lain di samping Allah?\") kata tanya mengandung arti ingkar. (Katakanlah) kepada mereka (\"Aku tidak mengakui\") hal tersebut. (Katakanlah, \"Sesungguhnya Dia adalah Tuhan Maha Esa dan sesungguhnya aku berlepas diri dari apa yang kamu persekutukan.\") terhadap Allah.",[["قُلْ","Katakanlah"],["أَىُّ","Apa"],["شَىْءٍ","perkara"],["أَكْبَرُ","(adalah) terbesar"],["شَهَـٰدَةًۭ ۖ","(sebagai) kesaksian"],["قُلِ","Katakanlah"],["ٱللَّهُ ۖ","Allah"],["شَهِيدٌۢ","(adalah) Saksi"],["بَيْنِى","antara aku"],["وَبَيْنَكُمْ ۚ","dan antara kamu"],["وَأُوحِىَ","dan telah didedahkan"],["إِلَىَّ","kepada aku"],["هَـٰذَا","ini"],["ٱلْقُرْءَانُ","[al-Quran]."],["لِأُنذِرَكُم","supaya aku boleh memberi amaran kepada kamu"],["بِهِۦ","dengannya"],["وَمَنۢ","dan sesiapa"],["بَلَغَ ۚ","ia sampai"],["أَئِنَّكُمْ","Adakah kamu benar-benar"],["لَتَشْهَدُونَ","memberi keterangan"],["أَنَّ","bahawa"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["ءَالِهَةً","(ada) tuhan"],["أُخْرَىٰ ۚ","lain"],["قُل","Katakanlah"],["لَّآ","Tidak"],["أَشْهَدُ ۚ","(lakukan) Aku bersaksi"],["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["هُوَ","Dia"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ","satu"],["وَإِنَّنِى","dan sesungguhnya, aku"],["بَرِىٓءٌۭ","percuma"],["مِّمَّا","tentang apa"],["تُشْرِكُونَ","kamu mempersekutukan (denganNya)"]]],"809":["(Orang-orang yang telah Kami berikan kitab kepadanya mereka mengenalnya) artinya mengenal Muhammad dengan sifat-sifat atau ciri-cirinya yang terdapat di dalam Kitab mereka (seperti mereka mengenal anak-anak sendiri. Orang-orang yang merugikan dirinya) di antara mereka (mereka itu tidak beriman) kepada Muhammad.",[["ٱلَّذِينَ","Mereka (kepada) siapa"],["ءَاتَيْنَـٰهُمُ","Kami telah memberi mereka"],["ٱلْكِتَـٰبَ","Kitab"],["يَعْرِفُونَهُۥ","mereka mengenalinya"],["كَمَا","seperti"],["يَعْرِفُونَ","mereka mengenali"],["أَبْنَآءَهُمُ ۘ","anak lelaki mereka"],["ٱلَّذِينَ","Orang yang"],["خَسِرُوٓا۟","hilang"],["أَنفُسَهُمْ","diri mereka"],["فَهُمْ","kemudian mereka"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"810":["(Dan siapakah) artinya tidak ada seorang pun (yang lebih aniaya daripada orang yang membuat-buat suatu kedustaan kepada Allah) yaitu menyekutukan-Nya dengan selain-Nya (atau mendustakan ayat-ayat-Nya?) Alquran. (Sesungguhnya) artinya keadaan yang sebenarnya (orang-orang yang aniaya itu tidak mendapat keberuntungan) oleh sebab kedustaannya itu.",[["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّنِ","daripada (dia) yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["أَوْ","atau"],["كَذَّبَ","menolak"],["بِـَٔايَـٰتِهِۦٓ ۗ","Tanda-tandaNya"],["إِنَّهُۥ","Sesungguhnya"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلظَّـٰلِمُونَ","orang yang zalim"]]],"811":["(Dan) ingatlah (hari yang di waktu itu Kami menghimpun mereka semuanya, kemudian Kami berkata kepada orang-orang musyrik) sebagai celaan (\"Di manakah sesembahan-sesembahan yang kamu katakan dahulu?\") yang kalian jadikan sebagai sekutu-sekutu Allah.",[["وَيَوْمَ","Dan (hari) itu"],["نَحْشُرُهُمْ","Kami akan mengumpulkan mereka"],["جَمِيعًۭا","semua"],["ثُمَّ","kemudian"],["نَقُولُ","Kami akan berkata"],["لِلَّذِينَ","kepada mereka yang"],["أَشْرَكُوٓا۟","mempersekutukan orang lain dengan Allah"],["أَيْنَ","Di mana (ada)"],["شُرَكَآؤُكُمُ","rakan kongsi kamu"],["ٱلَّذِينَ","mereka yang"],["كُنتُمْ","kamu pernah"],["تَزْعُمُونَ","tuntutan"]]],"812":["(Kemudian tiadalah) Takun dapat dibaca yakun (fitnah mereka) dapat dibaca fitnatuhum dan fitnatahum; artinya alasan mereka (kecuali mengatakan) selain ucapan mereka (\"Demi Allah, Tuhan kami) dibaca dengan jar sebagai sifat, dan dibaca nashab sebagai seruan (kami bukanlah orang-orang yang musyrik terhadap Allah\").",[["ثُمَّ","Kemudian"],["لَمْ","tidak"],["تَكُن","akan menjadi"],["فِتْنَتُهُمْ","(untuk) mereka rayuan"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوا۟","mereka berkata"],["وَٱللَّهِ","Demi Allah"],["رَبِّنَا","Tuhan kami"],["مَا","tidak"],["كُنَّا","kami"],["مُشْرِكِينَ","orang yang mempersekutukan (dengan Allah)"]]],"813":["Allah berfirman (Lihatlah) olehmu Muhammad (bagaimana mereka telah berdusta terhadap diri mereka sendiri) mereka menganggap bukan sebagai orang-orang musyrik (dan hilanglah) lenyaplah (dari mereka apa-apa yang selama ini mereka buat-buat) sebagai sesembahan mereka selain Allah.",[["ٱنظُرْ","Tengok"],["كَيْفَ","bagaimana"],["كَذَبُوا۟","mereka berbohong"],["عَلَىٰٓ","terhadap"],["أَنفُسِهِمْ ۚ","diri mereka"],["وَضَلَّ","Dan hilang"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يَفْتَرُونَ","mencipta"]]],"814":["(Dan di antara mereka ada orang-orang yang mau mendengarkanmu) apabila kamu membaca Alquran (padahal Kami telah menjadikan tutupan di atas hati mereka) penutup-penutup (agar mereka tidak memahaminya) supaya mereka tidak dapat memahami Alquran (dan di telinga mereka Kami letakkan sumbatan) sehingga mereka tuli tidak dapat mendengarnya, dengan pengertian pendengaran yang masuk di hati (Dan sekali pun mereka melihat segala tanda kebenaran, mereka tetap tidak mau beriman kepadanya. Sehingga apabila mereka datang kepadamu untuk membantahmu, orang-orang kafir itu berkata, \"Tiadalah) tidak lain (ini) Alquran ini (kecuali dongengan) cerita-cerita bohong (orang orang dahulu.\") sama seperti lelucon-lelucon dan legenda-legenda; asaathiir adalah bentuk jamak dari usthuurah.",[["وَمِنْهُم","Dan di antara mereka"],["مَّن","(adalah) siapa"],["يَسْتَمِعُ","dengar"],["إِلَيْكَ ۖ","kepada kamu"],["وَجَعَلْنَا","tetapi Kami telah meletakkan"],["عَلَىٰ","atas"],["قُلُوبِهِمْ","hati mereka"],["أَكِنَّةً","penutup"],["أَن","jangan-jangan"],["يَفْقَهُوهُ","mereka memahaminya"],["وَفِىٓ","dan dalam"],["ءَاذَانِهِمْ","telinga mereka"],["وَقْرًۭا ۚ","pekak"],["وَإِن","Dan jika"],["يَرَوْا۟","mereka lihat"],["كُلَّ","setiap"],["ءَايَةٍۢ","tanda"],["لَّا","tidak"],["يُؤْمِنُوا۟","adakah mereka akan beriman"],["بِهَا ۚ","di dalamnya"],["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["جَآءُوكَ","mereka datang kepada kamu"],["يُجَـٰدِلُونَكَ","dan berdebat dengan kamu"],["يَقُولُ","berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّآ","tetapi"],["أَسَـٰطِيرُ","(the) cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"815":["(Mereka melarang) orang-orang lain (darinya) dari mengikut kepada Nabi Muhammad saw. (dan mereka sendiri menjauh) makin menjauh (darinya) mereka semakin tidak beriman kepadanya. Menurut suatu riwayat ayat ini diturunkan berkenaan dengan Abu Thalib; ia melarang orang-orang mengganggu Nabi saw. akan tetapi ia sendiri tidak mau beriman kepadanya (dan tidaklah) tiada lain (mereka itu membinasakan) oleh sebab menjauh dari Nabi saw. (kecuali diri mereka sendiri) karena bahaya mereka sendirilah yang menanggungnya (sedangkan mereka tidak menyadari) akibat perbuatannya itu.",[["وَهُمْ","Dan mereka"],["يَنْهَوْنَ","melarang (orang lain)"],["عَنْهُ","daripadanya"],["وَيَنْـَٔوْنَ","dan mereka menjauhkan diri"],["عَنْهُ ۖ","daripadanya"],["وَإِن","Dan tidak"],["يُهْلِكُونَ","mereka memusnahkan"],["إِلَّآ","kecuali"],["أَنفُسَهُمْ","diri mereka"],["وَمَا","dan bukan"],["يَشْعُرُونَ","mereka rasa"]]],"816":["(Dan jika kamu melihat) hai Muhammad (ketika mereka dihadapkan) dikemukakan (ke neraka lalu mereka berkata, \"Hai kiranya) ungkapan penyesalan (kami dikembalikan) ke dunia (dan tidak mendustakan ayat-ayat Tuhan kami serta menjadi orang-orang yang beriman.\") kalau dibaca rafa' kedua fi'ilnya menjadi jumlah istinaf atau kalimat permulaan, jika dibaca nashab keduanya menjadi jawab dari tamanniy, demikian pula bila dibaca rafa' fi'ilnya yang pertama serta dibaca nashab fi'ilnya yang kedua. Sedang jawab dari lau/seandainya ialah: tentu kamu melihat suatu peristiwa yang besar.",[["وَلَوْ","Dan jika"],["تَرَىٰٓ","kamu (boleh) lihat"],["إِذْ","apabila"],["وُقِفُوا۟","mereka dibuat untuk berdiri"],["عَلَى","oleh"],["ٱلنَّارِ","neraka"],["فَقَالُوا۟","maka mereka (akan) berkata"],["يَـٰلَيْتَنَا","Oh! Adakah kita"],["نُرَدُّ","telah dihantar balik"],["وَلَا","dan bukan"],["نُكَذِّبَ","kami akan menafikan"],["بِـَٔايَـٰتِ","(the) Tanda-tanda"],["رَبِّنَا","(dari) Tuhan kami"],["وَنَكُونَ","dan kita akan menjadi"],["مِنَ","antara"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"817":["Allah berfirman (Tetapi) sebagai sanggahan terhadap kemauan mereka untuk beriman; pengertian ini dipahami dari makna tamanniy tadi (telah nyata) telah jelas (bagi mereka apa yang dahulu mereka menyembunyikannya) apa yang tersimpan dalam hati mereka yang dahulu mereka mengatakan, bahwa demi Allah, Tuhan kami, kami bukanlah orang-orang musyrik terhadap Allah. Hal itu terungkapkan berkat kesaksian anggota-anggota tubuh mereka, sehingga mereka mengharapkan (Sekiranya mereka dikembalikan) ke dunia secara perkiraan (tentulah mereka kembali kepada apa yang mereka telah dilarang mengerjakannya) yaitu perbuatan syirik (dan sesungguhnya mereka itu adalah pendusta-pendusta belaka) dalam janji mereka yang menyatakan sedia untuk beriman.",[["بَلْ","Bahkan"],["بَدَا","menjadi nyata"],["لَهُم","bagi mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يُخْفُونَ","menyembunyikan"],["مِن","daripada"],["قَبْلُ ۖ","sebelum"],["وَلَوْ","Dan jika"],["رُدُّوا۟","mereka dihantar balik"],["لَعَادُوا۟","nescaya mereka (akan) kembali"],["لِمَا","ke apa"],["نُهُوا۟","mereka dilarang"],["عَنْهُ","daripadanya"],["وَإِنَّهُمْ","dan sesungguhnya mereka"],["لَكَـٰذِبُونَ","sudah tentulah pembohong"]]],"818":["(Dan tentu mereka akan mengatakan) orang-orang yang ingkar terhadap hari berbangkit (\"Tiada lain) tidak lain (ia) dimaksud kehidupan (kecuali hanya kehidupan dunia saja, dan kita sekali-kali tidak akan dibangkitkan.\")",[["وَقَالُوٓا۟","Dan mereka berkata"],["إِنْ","Tidak"],["هِىَ","ia (adalah)"],["إِلَّا","kecuali"],["حَيَاتُنَا","hidup kita"],["ٱلدُّنْيَا","dunia"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمَبْعُوثِينَ","(akan) dibangkitkan"]]],"819":["(Dan seandainya kamu melihat ketika mereka dihadapkan) mereka diajukan (kepada Tuhan mereka) tentulah kamu akan melihat peristiwa yang besar. (Allah berfirman) kepada mereka melalui lisan malaikat-malaikat-Nya sebagai cemoohan. (\"Bukankah hal ini) yakni kebangkitan dan hari pembalasan ini (benar?\" Mereka menjawab, \"Sungguh benar, demi Tuhan kami\") sungguh hal itu adalah benar belaka (Berfirman Allah, \"Karena itu rasakanlah azab ini, disebabkan kamu mengingkari\")nya sewaktu hidup di dunia.",[["وَلَوْ","Dan jika"],["تَرَىٰٓ","kamu (boleh) lihat"],["إِذْ","apabila"],["وُقِفُوا۟","mereka akan dibuat berdiri"],["عَلَىٰ","sebelum"],["رَبِّهِمْ ۚ","Tuhan mereka"],["قَالَ","Dia (akan) berkata"],["أَلَيْسَ","bukan"],["هَـٰذَا","ini"],["بِٱلْحَقِّ ۚ","kebenaran"],["قَالُوا۟","Mereka akan berkata"],["بَلَىٰ","ya"],["وَرَبِّنَا ۚ","oleh Tuhan kita"],["قَالَ","Dia (akan) berkata"],["فَذُوقُوا۟","Jadi rasa"],["ٱلْعَذَابَ","azab"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَكْفُرُونَ","kufur"]]],"820":["(Sungguh telah rugilah orang-orang yang mendustakan pertemuan mereka dengan Allah) mendustakan adanya hari kebangkitan (sehingga) sebagai tanda keterlaluan mereka dalam mendustakan (apabila kiamat datang kepada mereka) yaitu hari kiamat (dengan tiba-tiba) secara mendadak (mereka berkata, \"Alangkah besarnya penyesalan kami) sebagai ungkapan rasa derita yang sangat keras; dan pemakaian huruf nida atau panggilan di sini hanyalah majaz atau kiasan yang artinya sekarang saatnya telah tiba maka datanglah (terhadap kelalaian kami) kealpaan kami (tentang kiamat itu.\") sewaktu di dunia (sambil mereka memikul dosa-dosa di atas punggungnya) dosa-dosa itu mendatangi mereka dalam bentuk yang paling buruk dan paling berbau kemudian dosa-dosa itu menaiki mereka. (Ingatlah, amatlah buruk) sangat jeleklah (apa yang mereka pikul itu) beban yang mereka pikul itu.",[["قَدْ","Sesungguhnya"],["خَسِرَ","mengalami kerugian"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِلِقَآءِ","dalam mesyuarat itu"],["ٱللَّهِ ۖ","(dengan) Allah"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءَتْهُمُ","datang kepada mereka"],["ٱلسَّاعَةُ","Jam itu"],["بَغْتَةًۭ","tiba-tiba"],["قَالُوا۟","mereka berkata"],["يَـٰحَسْرَتَنَا","Oh! penyesalan kami"],["عَلَىٰ","atas"],["مَا","apa"],["فَرَّطْنَا","kita lalai"],["فِيهَا","berkenaan dengannya"],["وَهُمْ","sedangkan mereka"],["يَحْمِلُونَ","akan menanggung"],["أَوْزَارَهُمْ","bebanan mereka"],["عَلَىٰ","pada"],["ظُهُورِهِمْ ۚ","belakang mereka"],["أَلَا","Tidak dinafikan"],["سَآءَ","jahat"],["مَا","(ialah) apa"],["يَزِرُونَ","mereka menanggung"]]],"821":["(Dan tiadalah kehidupan dunia ini) artinya kesibukannya (selain dari main-main dan senda-gurau) adapun mengenai amal taat dan hal-hal yang menjadi sarananya maka hal itu termasuk perkara-perkara akhirat. (Dan sungguh kampung akhirat itu) di dalam suatu qiraat yang dimaksud dengan kampung akhirat itu ialah surga (lebih baik bagi orang-orang yang takwa) yang takut berbuat kemusyrikan. (Maka tidakkah kamu memahaminya?) dengan memakai ya dan ta; hal itu kemudian mendorong kamu untuk beriman.",[["وَمَا","Dan tidak"],["ٱلْحَيَوٰةُ","(ialah) kehidupan"],["ٱلدُّنْيَآ","dunia"],["إِلَّا","kecuali"],["لَعِبٌۭ","sebuah sandiwara"],["وَلَهْوٌۭ ۖ","dan keseronokan"],["وَلَلدَّارُ","tetapi rumah"],["ٱلْـَٔاخِرَةُ","(dari) Akhirat"],["خَيْرٌۭ","(adalah) terbaik"],["لِّلَّذِينَ","bagi mereka yang"],["يَتَّقُونَ ۗ","(adalah) sedar Tuhan"],["أَفَلَا","Kemudian tidak"],["تَعْقِلُونَ","(akan) kamu beralasan"]]],"822":["(Sesungguhnya) untuk penegasan (Kami mengetahui bahwasanya) perihal itu (apa yang mereka katakan itu membuat kamu bersedih hati) berupa kedustaan yang ditujukan kepadamu (karena mereka sebenarnya tidak mendustakan kamu) secara sembunyi-sembunyi oleh sebab pengetahuan mereka tentang dirimu yang dapat dipercaya itu. Dan di dalam suatu qiraat dibaca dengan takhfif atau ringan; artinya mereka tidak menuduhmu berbuat dusta (akan tetapi orang-orang yang zalim itu) azh-zhaalimiina diletakkan pada tempatnya dhamir (terhadap ayat-ayat Allah) Alquran (mereka ingkar) mereka mendustakannya.",[["قَدْ","Sesungguhnya"],["نَعْلَمُ","Kami tahu"],["إِنَّهُۥ","bahawa ia"],["لَيَحْزُنُكَ","menyedihkan kamu"],["ٱلَّذِى","apa"],["يَقُولُونَ ۖ","mereka berkata"],["فَإِنَّهُمْ","Dan sesungguhnya, mereka"],["لَا","jangan"],["يُكَذِّبُونَكَ","menafikan kamu"],["وَلَـٰكِنَّ","tetapi"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["بِـَٔايَـٰتِ","ayat-ayat"],["ٱللَّهِ","(milik) Allah"],["يَجْحَدُونَ","mereka menolak"]]],"823":["(Dan sungguh telah didustakan pula rasul-rasul sebelumnya) dalam ayat ini terkandung makna yang menghibur diri Nabi saw. (akan tetapi mereka sabar dalam menghadapi pendustaan dan penganiayaan yang dilakukan terhadap mereka sampai datang pertolongan Kami kepada mereka) untuk membinasakan kaumnya; maka bersabarlah kamu sehingga datang pertolongan-Ku yang akan membinasakan kaummu. (Tak ada seorang pun yang dapat merubah kalimat-kalimat Allah) janji-janji-Nya (Dan sesungguhnya telah datang kepadamu sebagian dari berita rasul-rasul itu) yang dapat menenangkan hatimu.",[["وَلَقَدْ","Dan pastinya"],["كُذِّبَتْ","telah ditolak"],["رُسُلٌۭ","Utusan"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["فَصَبَرُوا۟","tetapi mereka bersabar"],["عَلَىٰ","atas"],["مَا","apa"],["كُذِّبُوا۟","mereka ditolak"],["وَأُوذُوا۟","dan mereka dicederakan"],["حَتَّىٰٓ","sehingga"],["أَتَىٰهُمْ","datang kepada mereka"],["نَصْرُنَا ۚ","Bantuan kami"],["وَلَا","Dan tidak"],["مُبَدِّلَ","satu (boleh) mengubah"],["لِكَلِمَـٰتِ","(the) perkataan"],["ٱللَّهِ ۚ","(milik) Allah"],["وَلَقَدْ","dan pastinya"],["جَآءَكَ","telah datang kepada kamu"],["مِن","daripada"],["نَّبَإِى۟","(the) berita"],["ٱلْمُرْسَلِينَ","(dari) para Rasul"]]],"824":["(Dan jika makin bertambah besar) makin menjadi (berpalingnya mereka darimu) dari agama Islam padahal kamu masih berharap agar mereka beriman (maka jika kamu dapat membuat lubang) membuat terowongan (di bumi atau tangga) alat untuk naik (ke langit lalu kamu dapat mendatangkan mukjizat kepada mereka) sesuai dengan apa yang mereka minta, maka lakukanlah. Artinya sesungguhnya kamu tidak akan kuat untuk melakukan hal itu oleh karena itu bersabarlah hingga datang kepada mereka keputusan Allah. (Dan kalau Allah menghendaki) memberikan hidayah kepada mereka (tentu saja Allah menjadikan mereka semua dalam petunjuk) akan tetapi Ia tidak menghendaki demikian oleh karenanya mereka tidak mau beriman (janganlah kamu sekali-kali termasuk orang-orang jahil) mengenai hal itu.",[["وَإِن","Dan jika"],["كَانَ","ialah"],["كَبُرَ","susah"],["عَلَيْكَ","bagi kamu"],["إِعْرَاضُهُمْ","keengganan mereka"],["فَإِنِ","maka jika"],["ٱسْتَطَعْتَ","kamu mampu"],["أَن","kepada"],["تَبْتَغِىَ","mencari"],["نَفَقًۭا","sebuah terowong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أَوْ","atau"],["سُلَّمًۭا","sebuah tangga"],["فِى","ke dalam"],["ٱلسَّمَآءِ","langit"],["فَتَأْتِيَهُم","supaya kamu bawa kepada mereka"],["بِـَٔايَةٍۢ ۚ","sebuah Tanda"],["وَلَوْ","Tetapi jika"],["شَآءَ","(telah) berkehendak"],["ٱللَّهُ","Allah"],["لَجَمَعَهُمْ","nescaya Dia (akan) mengumpulkan mereka"],["عَلَى","pada"],["ٱلْهُدَىٰ ۚ","bimbingan"],["فَلَا","Jadi (jangan)"],["تَكُونَنَّ","jadilah"],["مِنَ","daripada"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"825":["(Sesungguhnya yang mendengar) ajakanmu kepada keimanan (hanyalah orang-orang yang mematuhi ajakanmu) dengan pendengaran yang penuh pengertian dan penuh pertimbangan (dan orang-orang yang mati hatinya) yakni orang-orang kafir; Allah menyerupakan mereka dengan orang-orang yang mati oleh karena mereka semua sama-sama tidak bisa mendengar (akan dibangkitkan oleh Allah) di akhirat (kemudian kepada-Nyalah mereka dikembalikan) mereka akan dikembalikan kepada-Nya kemudian Allah membalas amal perbuatan mereka.",[["۞ إِنَّمَا","Hanya"],["يَسْتَجِيبُ","bertindak balas"],["ٱلَّذِينَ","orang yang"],["يَسْمَعُونَ ۘ","dengar"],["وَٱلْمَوْتَىٰ","Tetapi yang mati"],["يَبْعَثُهُمُ","akan membangkitkan mereka"],["ٱللَّهُ","Allah"],["ثُمَّ","kemudian"],["إِلَيْهِ","kepada-Nya"],["يُرْجَعُونَ","mereka akan dikembalikan"]]],"826":["(Dan mereka berkata) yaitu orang-orang musyrik Mekah (\"Mengapa tidak) kenapa tidak (diturunkan kepadanya, Muhammad, suatu mukjizat dari Tuhannya?\") seperti mukjizat onta, tongkat dan hidangan. (Katakanlah) kepada mereka (\"Sesungguhnya Allah kuasa menurunkan) dengan dibaca tasydid dan takhfif (suatu mukjizat) seperti apa yang mereka minta (tetapi kebanyakan mereka tidak mengetahui\") karena sesungguhnya dengan turunnya mukjizat itu berarti suatu musibah besar yang pasti menimpa mereka jika mereka masih tetap mengingkarinya.",[["وَقَالُوا۟","Dan mereka berkata"],["لَوْلَا","Mengapa (ada) tidak"],["نُزِّلَ","diturunkan"],["عَلَيْهِ","kepadanya"],["ءَايَةٌۭ","sebuah Tanda"],["مِّن","daripada"],["رَّبِّهِۦ ۚ","Tuhannya"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["قَادِرٌ","(adalah) Mampu"],["عَلَىٰٓ","[pada]"],["أَن","kepada"],["يُنَزِّلَ","hantar ke bawah"],["ءَايَةًۭ","sebuah Tanda"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"827":["(Dan tiadalah) min sebagai tambahan (binatang-binatang) yang berjalan (di muka bumi dan burung-burung yang terbang) di udara (dengan kedua sayapnya melainkan umat-umat juga seperti kamu) dalam pengaturan penciptaannya, rezeki dan sepak terjangnya. (Tiadalah Kami alpakan) Kami tinggalkan (di dalam Alkitab) yakni Lohmahfuz (tentang) sebagai tambahan (sesuatu pun) artinya Kami tidak menulisnya (kemudian kepada Tuhanlah mereka dihimpunkan) kemudian Tuhan memutuskan hukum-Nya di antara mereka. Ia mengkisas si kuat yang menganiaya di lemah setelah Ia berfirman kepada mereka semua, \"Jadilah kamu semua sebagai tanah!\"",[["وَمَا","Dan tidak"],["مِن","[daripada]"],["دَآبَّةٍۢ","mana-mana haiwan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["طَـٰٓئِرٍۢ","seekor burung"],["يَطِيرُ","(yang) terbang"],["بِجَنَاحَيْهِ","dengan sayapnya"],["إِلَّآ","tetapi"],["أُمَمٌ","(adalah) masyarakat"],["أَمْثَالُكُم ۚ","macam kamu"],["مَّا","Tidak"],["فَرَّطْنَا","Kita telah lalai"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["مِن","[daripada]"],["شَىْءٍۢ ۚ","sesuatu"],["ثُمَّ","kemudian"],["إِلَىٰ","kepada"],["رَبِّهِمْ","Tuhan mereka"],["يُحْشَرُونَ","mereka akan dikumpulkan"]]],"828":["(Dan orang-orang yang mendustakan ayat-ayat Kami) Alquran (adalah pekak) tidak dapat mendengarkannya dengan pendengaran yang meresap ke dalam hati lalu menerimanya (bisu) tidak dapat mengucapkan perkara yang hak (lagi berada dalam gelap-gulita) yakni kekafiran. (Siapa yang dikehendaki Allah) ia tersesat (niscaya disesatkan-Nya. Dan siapa yang dikehendaki-Nya) mendapat petunjuk (niscaya Dia menjadikannya berada di atas jalan) titian (yang lurus) yakni agama Islam.",[["وَٱلَّذِينَ","Dan orang yang"],["كَذَّبُوا۟","ditolak"],["بِـَٔايَـٰتِنَا","Ayat Kami"],["صُمٌّۭ","(adalah) pekak"],["وَبُكْمٌۭ","dan bodoh"],["فِى","dalam"],["ٱلظُّلُمَـٰتِ ۗ","kegelapan[es]"],["مَن","Siapa pun"],["يَشَإِ","wasiat"],["ٱللَّهُ","Allah"],["يُضْلِلْهُ","Dia biarkan dia sesat"],["وَمَن","dan sesiapa"],["يَشَأْ","Dia berkehendak"],["يَجْعَلْهُ","Dia meletakkan dia"],["عَلَىٰ","pada"],["صِرَٰطٍۢ","jalan"],["مُّسْتَقِيمٍۢ","(yang) lurus"]]],"829":["(Katakanlah) hai Muhammad kepada penduduk Mekah (\"Terangkanlah kepadaku) beritakanlah kepadaku (jika datang siksaan Allah kepadamu) di dunia ini (atau datang kepadamu hari kiamat) yaitu kiamat yang mencakup semuanya secara tiba-tiba (apakah kamu menyeru tuhan selain Allah) tidak (jika kamu orang-orang yang benar.\") bahwa berhala-berhala itu dapat memberi manfaat kepadamu, maka serulah mereka.",[["قُلْ","Katakanlah"],["أَرَءَيْتَكُمْ","Pernahkah kamu melihat"],["إِنْ","jika"],["أَتَىٰكُمْ","(di sana) datang kepada kamu"],["عَذَابُ","hukuman"],["ٱللَّهِ","(milik) Allah"],["أَوْ","atau"],["أَتَتْكُمُ","(di sana) datang kepada kamu"],["ٱلسَّاعَةُ","Jam itu"],["أَغَيْرَ","adakah ia lain"],["ٱللَّهِ","(daripada) Allah"],["تَدْعُونَ","kamu panggil"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"830":["(Bahkan hanya kepada-Nyalah) tidak ada lain (kamu berseru) memohon pertolongan-Nya di masa kalian tertimpa kesulitan (maka Dia menghilangkan bahaya yang karenanya kamu berdoa kepada-Nya) Ia akan menyingkirkan mara bahaya dari dirimu dan juga lain-lainnya (jika Dia menghendaki) niscaya Ia melenyapkannya (dan kamu melupakan) kamu meninggalkan (apa-apa yang kamu sekutukan) dengan Allah yaitu berupa sesembahan-sesembahan lain-Nya, maka dari itu janganlah kamu berseru kepadanya.",[["بَلْ","Bahkan"],["إِيَّاهُ","Dia sahaja"],["تَدْعُونَ","kamu panggil"],["فَيَكْشِفُ","dan Dia akan menghapuskan"],["مَا","apa"],["تَدْعُونَ","kamu panggil"],["إِلَيْهِ","atas Dia"],["إِن","jika"],["شَآءَ","Dia kehendaki"],["وَتَنسَوْنَ","dan kamu akan lupa"],["مَا","apa"],["تُشْرِكُونَ","kamu mempersekutukan (denganNya)"]]],"831":["(Dan sesungguhnya Kami telah mengutus kepada umat-umat) min sebagai tambahan yang tidak mempunyai arti (sebelum kamu) rasul-rasul, akan tetapi mereka mendustakannya (kemudian Kami siksa mereka dengan kesengsaraan) kemelaratan yang sangat (dan penderitaan) penyakit (supaya mereka tunduk merendahkan diri) merasa rendah diri lalu mereka mau beriman.",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَآ","Kami mengutus (Rasul-rasul)"],["إِلَىٰٓ","kepada"],["أُمَمٍۢ","bangsa-bangsa"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["فَأَخَذْنَـٰهُم","kemudian Kami siksa mereka"],["بِٱلْبَأْسَآءِ","dengan kesusahan"],["وَٱلضَّرَّآءِ","dan kesusahan"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَضَرَّعُونَ","merendahkan diri"]]],"832":["(Maka mengapa tidak) kenapa tidak (tatkala datang siksaan Kami kepada mereka) azab Kami (memohon kepada Allah dengan menundukkan diri) artinya mereka tidak mau melakukan hal itu, padahal yang mengharuskan mereka berbuat demikian sudah ada (bahkan hati mereka telah menjadi keras) oleh karenanya tidak mau tunduk kepada keimanan (dan setan pun menampakkan kepada mereka kebagusan apa yang selalu mereka kerjakan) yaitu perbuatan-perbuatan maksiat sehingga mereka terus menetapinya.",[["فَلَوْلَآ","Lalu kenapa tidak"],["إِذْ","apabila"],["جَآءَهُم","datang kepada mereka"],["بَأْسُنَا","hukuman kita"],["تَضَرَّعُوا۟","mereka merendahkan diri"],["وَلَـٰكِن","Tetapi"],["قَسَتْ","menjadi keras"],["قُلُوبُهُمْ","hati mereka"],["وَزَيَّنَ","dan dibuat kelihatan adil"],["لَهُمُ","kepada mereka"],["ٱلشَّيْطَـٰنُ","syaitan"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"833":["(Maka tatkala mereka melupakan) mereka mengabaikan (peringatan yang telah diberikan kepada mereka) nasihat dan ancaman yang telah diberikan kepada mereka (melaluinya) yaitu dalam bentuk kesengsaraan dan penderitaan, mereka tetap tidak mau mengambil pelajaran dan nasihat darinya (Kami bukakan) dengan dibaca takhfif dan tasydid (kepada mereka semua pintu-pintu) yakni kesenangan-kesenangan sebagai istidraj untuk mereka (sehingga apabila mereka bergembira dengan apa yang telah diberikan kepada mereka) gembira yang diwarnai rasa sombong (Kami siksa mereka) dengan azab (dengan tiba-tiba) secara sekonyong-konyong (maka ketika itu mereka terdiam berputus-asa) mereka merasa berputus asa dari segala kebaikan.",[["فَلَمَّا","Maka apabila"],["نَسُوا۟","mereka lupa"],["مَا","apa"],["ذُكِّرُوا۟","mereka diingatkan"],["بِهِۦ","daripada [itu]"],["فَتَحْنَا","Kami buka"],["عَلَيْهِمْ","ke atas mereka"],["أَبْوَٰبَ","pintu pagar"],["كُلِّ","(daripada) setiap"],["شَىْءٍ","perkara"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["فَرِحُوا۟","mereka bergembira"],["بِمَآ","pada apa"],["أُوتُوٓا۟","mereka diberi"],["أَخَذْنَـٰهُم","Kami menangkap mereka"],["بَغْتَةًۭ","tiba-tiba"],["فَإِذَا","dan kemudian"],["هُم","mereka"],["مُّبْلِسُونَ","(telah) tercengang"]]],"834":["(Maka orang-orang yang lalim itu dimusnahkan) sampai ke akar-akarnya sehingga habis tanpa bekas (Segala puji bagi Allah Tuhan semesta alam) yang menolong rasul-rasul dan membinasakan orang-orang kafir.",[["فَقُطِعَ","Jadi telah dipotong"],["دَابِرُ","(yang) tinggalan"],["ٱلْقَوْمِ","(daripada) rakyat"],["ٱلَّذِينَ","[mereka] yang"],["ظَلَمُوا۟ ۚ","buat salah"],["وَٱلْحَمْدُ","Dan segala pujian dan terima kasih"],["لِلَّهِ","bagi Allah"],["رَبِّ","Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"835":["(Katakanlah) kepada penduduk Mekah (\"Terangkanlah kepadaku) beritakanlah kepadaku (jika Allah mencabut pendengaranmu) membuatmu menjadi tuli (dan penglihatanmu) membutakanmu (serta mengunci) menutup (hatimu) sehingga kamu tidak dapat mengenal sesuatu (Siapakah tuhan selain Allah yang kuasa mengembalikannya kepadamu?\") apa-apa yang telah Dia cabut darimu sesuai dengan dugaanmu (Perhatikanlah bagaimana Kami memperlihatkan) menjelaskan (tanda-tanda kebesaran Kami) bukti-bukti yang menunjukkan kepada keesaan Kami (kemudian mereka masih tetap berpaling) tetap berpaling dari-Nya dan tidak mau beriman.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["إِنْ","jika"],["أَخَذَ","dibawa pergi"],["ٱللَّهُ","Allah"],["سَمْعَكُمْ","pendengaran kamu"],["وَأَبْصَـٰرَكُمْ","dan penglihatan kamu"],["وَخَتَمَ","dan dimeteraikan"],["عَلَىٰ","[pada]"],["قُلُوبِكُم","hati kamu"],["مَّنْ","yang"],["إِلَـٰهٌ","(ialah) tuhan"],["غَيْرُ","selain daripada"],["ٱللَّهِ","Allah"],["يَأْتِيكُم","untuk membawa [kembali] kepada kamu"],["بِهِ ۗ","dengannya"],["ٱنظُرْ","Lihat"],["كَيْفَ","bagaimana"],["نُصَرِّفُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["ثُمَّ","belum lagi"],["هُمْ","mereka"],["يَصْدِفُونَ","berpaling"]]],"836":["(Katakanlah,) kepada mereka (\"Terangkanlah kepadaku, jika datang siksaan Allah kepadamu dengan sekonyong-konyong atau terang-terangan) siang hari maupun malam hari (maka adakah yang dibinasakan Allah selain dari orang-orang yang lalim?\") yakni orang-orang kafir. Atau dengan kata lain: tidak ada yang dibinasakan-Nya kecuali hanya mereka.",[["قُلْ","Katakanlah"],["أَرَءَيْتَكُمْ","Pernahkah kamu melihat"],["إِنْ","jika"],["أَتَىٰكُمْ","datang kepada kamu"],["عَذَابُ","hukuman"],["ٱللَّهِ","(milik) Allah"],["بَغْتَةً","tiba-tiba"],["أَوْ","atau"],["جَهْرَةً","secara terbuka"],["هَلْ","kehendak"],["يُهْلَكُ","(mana-mana) dimusnahkan"],["إِلَّا","kecuali"],["ٱلْقَوْمُ","rakyat"],["ٱلظَّـٰلِمُونَ","orang yang zalim"]]],"837":["(Dan tidaklah Kami mengutus para rasul itu melainkan untuk memberi kabar gembira) tentang surga terhadap orang yang beriman (dan memberi peringatan) kepada orang yang kafir dengan adanya siksaan neraka. (Siapa yang beriman) kepada rasul-rasul itu (dan mengadakan perbaikan) terhadap amal perbuatannya (maka tak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) di akhirat kelak.",[["وَمَا","Dan tidak"],["نُرْسِلُ","Kami hantar"],["ٱلْمُرْسَلِينَ","para Rasul"],["إِلَّا","kecuali"],["مُبَشِّرِينَ","(sebagai) pembawa berita gembira"],["وَمُنذِرِينَ ۖ","dan (sebagai) pemberi amaran"],["فَمَنْ","Jadi sesiapa"],["ءَامَنَ","beriman"],["وَأَصْلَحَ","dan diperbaharui"],["فَلَا","maka tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"838":["(Dan orang-orang yang mendustakan ayat-ayat Kami mereka ditimpa siksaan disebabkan mereka selalu berbuat fasik) yaitu keluar dari garis-garis ketaatan.",[["وَٱلَّذِينَ","Dan orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","[dalam] Ayat Kami"],["يَمَسُّهُمُ","akan menyentuh mereka"],["ٱلْعَذَابُ","azab"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَفْسُقُونَ","membangkang menderhaka"]]],"839":["(Katakanlah) kepada mereka (\"Aku tidak mengatakan kepadamu, bahwa perbendaharaan Allah ada padaku) yang di antaranya ialah rezeki yang diberikan kepadanya (dan tidak) pula bahwa aku (mengetahui yang gaib) hal-hal yang gaib dariku dan tidak diwahyukan kepadaku (dan tidak pula aku mengatakan kepadamu bahwa aku seorang malaikat) di antara malaikat-malaikat lainnya. (Tidaklah) tiada lain (aku hanya mengikut apa yang diwahyukan kepadaku.\" Katakanlah, \"Apakah sama orang yang buta) orang kafir (dengan orang yang melihat?\") orang yang beriman; tentu saja tidak. (Maka apakah kamu tidak memikirkan) tentang hal itu, kemudian kamu beriman.",[["قُل","Katakanlah"],["لَّآ","Tidak"],["أَقُولُ","(buat) aku katakan"],["لَكُمْ","kepada kamu"],["عِندِى","(itu) dengan aku"],["خَزَآئِنُ","(adalah) khazanah"],["ٱللَّهِ","(milik) Allah"],["وَلَآ","dan bukan"],["أَعْلَمُ","(itu) aku tahu"],["ٱلْغَيْبَ","yang ghaib"],["وَلَآ","dan bukan"],["أَقُولُ","aku cakap"],["لَكُمْ","kepada kamu"],["إِنِّى","bahawa aku (adalah)"],["مَلَكٌ ۖ","seorang Malaikat"],["إِنْ","Tidak"],["أَتَّبِعُ","(ada) aku ikut"],["إِلَّا","kecuali"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَىَّ ۚ","kepada aku"],["قُلْ","Katakanlah"],["هَلْ","boleh"],["يَسْتَوِى","sama rata"],["ٱلْأَعْمَىٰ","yang buta"],["وَٱلْبَصِيرُ ۚ","dan yang melihat"],["أَفَلَا","Kemudian tidak akan"],["تَتَفَكَّرُونَ","kamu fikirkan"]]],"840":["(Dan berilah peringatan) takut-takutilah (dengannya) dengan Alquran (orang-orang yang takut akan dihimpunkan kepada Tuhannya pada hari kiamat sedang tidak ada bagi mereka selain-Nya) yakni selain Allah (seorang pelindung) yang dapat menolong mereka (dan pemberi syafaat pun) yang dapat memberikan syafaat kepada mereka. Jumlah kalimat yang diawali dengan huruf nafi menjadi hal dari dhamir yang terdapat di dalam lafal yuhsyaruu; maksudnya tempat yang ditakuti. Dan yang dimaksud dengan mereka adalah orang-orang yang maksiat (agar mereka bertakwa) kepada Allah dengan memberhentikan diri mereka dari kebiasaan yang biasa mereka lakukan kemudian mau berbuat ketaatan.",[["وَأَنذِرْ","Dan beri amaran"],["بِهِ","dengannya"],["ٱلَّذِينَ","orang yang"],["يَخَافُونَ","bertakwa"],["أَن","bahawa"],["يُحْشَرُوٓا۟","mereka akan dikumpulkan"],["إِلَىٰ","kepada"],["رَبِّهِمْ ۙ","Tuhan mereka"],["لَيْسَ","tidak"],["لَهُم","bagi mereka"],["مِّن","daripada"],["دُونِهِۦ","selain Dia"],["وَلِىٌّۭ","mana-mana pelindung"],["وَلَا","dan bukan"],["شَفِيعٌۭ","mana-mana pemberi syafaat"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يَتَّقُونَ","(menjadi) soleh"]]],"841":["(Dan janganlah kamu mengusir orang-orang yang menyeru Tuhannya di pagi hari dan di petang hari sedangkan mereka menghendaki) dengan ibadahnya itu (keridaan-Nya) Yang Maha Tinggi bukannya untuk tujuan meraih sesuatu dari keduniaan. Mereka adalah kaum muslimin yang miskin sedangkan kaum musyrikin sangat tidak menyukai mereka lalu orang-orang musyrik meminta kepada Nabi saw. agar beliau mengusir mereka dari sisinya supaya orang-orang musyrik itu dapat duduk bersama-sama dengan beliau. Kemudian Nabi saw. bermaksud untuk memenuhi permintaan orang-orang musyrik itu agar mereka mau masuk Islam. (Kamu tidak memikul tanggung jawab terhadap perbuatan mereka) huruf min adalah tambahan (sedikit pun) jika hati mereka tidak rela (dan mereka pun tidak memikul tanggung jawab sedikit pun terhadap perbuatanmu yang menyebabkan kamu berhak mengusir mereka) sebagai jawab dari nafi (sehingga kamu termasuk orang-orang yang lalim) jika kamu melakukan hal itu.",[["وَلَا","Dan jangan"],["تَطْرُدِ","hantar pergi"],["ٱلَّذِينَ","orang yang"],["يَدْعُونَ","panggilan"],["رَبَّهُم","Tuhan mereka"],["بِٱلْغَدَوٰةِ","pada waktu pagi"],["وَٱلْعَشِىِّ","dan petang"],["يُرِيدُونَ","berkeinginan"],["وَجْهَهُۥ ۖ","Wajah-Nya"],["مَا","Tidak"],["عَلَيْكَ","(ada) pada kamu"],["مِنْ","daripada"],["حِسَابِهِم","akaun mereka"],["مِّن","[daripada]"],["شَىْءٍۢ","sesuatu"],["وَمَا","dan bukan"],["مِنْ","daripada"],["حِسَابِكَ","akaun kamu"],["عَلَيْهِم","ke atas mereka"],["مِّن","[daripada]"],["شَىْءٍۢ","sesuatu"],["فَتَطْرُدَهُمْ","Jadi adakah kamu menghantar mereka pergi"],["فَتَكُونَ","maka kamu akan menjadi"],["مِنَ","daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"842":["(Dan demikianlah telah Kami uji) Kami telah coba (sebagian mereka dengan sebagian lainnya) yakni orang yang mulia dengan orang yang rendah, orang kaya dengan orang miskin, untuk Kami lombakan siapakah yang berhak paling dahulu kepada keimanan (supaya mereka berkata) orang-orang yang mulia dan orang-orang yang kaya yaitu mereka yang ingkar (\"Orang-orang semacam inikah) yakni orang-orang miskin (di antara kita yang diberi anugerah oleh Allah kepada mereka?\") hidayah. Artinya jika apa yang sedang dilakukan oleh orang-orang miskin dan orang-orang rendahan itu dinamakan hidayah, niscaya orang-orang mulia dan orang-orang kaya itu tidak akan mampu mendahuluinya. Allah berfirman, (\"Tidakkah Allah lebih mengetahui tentang orang-orang yang bersyukur?\") kepada-Nya lalu Dia memberikan hidayah kepada mereka. Memang betul.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["فَتَنَّا","Kita cuba"],["بَعْضَهُم","sebahagian mereka"],["بِبَعْضٍۢ","dengan orang lain"],["لِّيَقُولُوٓا۟","yang mereka katakan"],["أَهَـٰٓؤُلَآءِ","Adakah ini"],["مَنَّ","(yang telah) diberi nikmat"],["ٱللَّهُ","(oleh) Allah"],["عَلَيْهِم","[kepada mereka]"],["مِّنۢ","daripada"],["بَيْنِنَآ ۗ","antara kita"],["أَلَيْسَ","bukan"],["ٱللَّهُ","Allah"],["بِأَعْلَمَ","paling mengetahui"],["بِٱلشَّـٰكِرِينَ","daripada mereka yang bersyukur"]]],"843":["(Apabila orang-orang yang beriman kepada ayat-ayat Kami itu datang kepadamu, maka katakanlah) kepada mereka (\"Mudah-mudahan Allah melimpahkan kesejahteraan atas kamu telah menetapkan) telah memastikan (Tuhanmu atas diri-Nya kasih sayang, yaitu bahwasanya) yakni perihalnya; di dalam suatu qiraat dibaca dengan fathah yaitu annahu sebagai badal atau kata ganti dari Lafal ar-rahmah (siapa yang berbuat kejahatan di antara kamu lantaran kejahilan) terhadap perbuatan itu sewaktu ia melakukannya (kemudian ia bertobat) kembali ke jalan yang benar (setelah itu) setelah mengerjakannya (dan mengadakan perbaikan) terhadap amal perbuatannya (maka sesungguhnya Ia) yakni Allah swt. (Maha Pengampun) kepadanya (lagi Maha Penyayang.\") kepada dirinya. Menurut qiraat lainnya dibaca dengan fatah; artinya maka Dialah yang memberi ampunan dan kasih sayang.",[["وَإِذَا","Dan apabila"],["جَآءَكَ","datang kepada kamu"],["ٱلَّذِينَ","orang yang"],["يُؤْمِنُونَ","beriman"],["بِـَٔايَـٰتِنَا","dalam Ayat-ayat Kami"],["فَقُلْ","kemudian berkata"],["سَلَـٰمٌ","Damai"],["عَلَيْكُمْ ۖ","(berada) atas kamu"],["كَتَبَ","(Telah) Ditetapkan"],["رَبُّكُمْ","Tuhanmu"],["عَلَىٰ","ke atas"],["نَفْسِهِ","dirinya sendiri"],["ٱلرَّحْمَةَ ۖ","kerahiman"],["أَنَّهُۥ","bahawa dia"],["مَنْ","yang"],["عَمِلَ","tidak"],["مِنكُمْ","antara kamu"],["سُوٓءًۢا","jahat"],["بِجَهَـٰلَةٍۢ","dalam kejahilan"],["ثُمَّ","kemudian"],["تَابَ","bertaubat"],["مِنۢ","daripada"],["بَعْدِهِۦ","selepas itu"],["وَأَصْلَحَ","dan pembaharuan"],["فَأَنَّهُۥ","maka sesungguhnya Dia"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"844":["(Dan demikianlah) sebagaimana yang telah Kami jelaskan sebelumnya (Kami terangkan) Kami jelaskan (ayat-ayat) Alquran untuk menampakkan yang hak kemudian diamalkan (supaya jelas) supaya menjadi terang (jalan) kelakuan (orang-orang yang berdosa) kemudian engkau menjauhinya. Dalam suatu qiraat dibaca litubayyina; menurut qiraat lainnya dibaca litastabiina. Bila lafal sabiil dibaca nashab maka pembicaraannya ditujukan kepada Nabi saw.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نُفَصِّلُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","ayat-ayat"],["وَلِتَسْتَبِينَ","sehingga menjadi nyata"],["سَبِيلُ","jalan"],["ٱلْمُجْرِمِينَ","(dari) penjenayah"]]],"845":["(Katakanlah, \"Sesungguhnya aku dilarang menyembah tuhan-tuhan yang kamu seru) kamu sembah (selain Allah.\" Katakanlah, \"Aku tidak akan mengikuti hawa nafsumu) dalam menyembah tuhan-tuhanmu itu (sungguh tersesatlah aku jika berbuat demikian) jika aku ikut menyembah tuhan-tuhan itu (dan tidak pula aku termasuk orang-orang yang mendapat petunjuk.\")",[["قُلْ","Katakanlah"],["إِنِّى","Sesungguhnya aku"],["نُهِيتُ","[Aku] dilarang"],["أَنْ","bahawa"],["أَعْبُدَ","aku menyembah"],["ٱلَّذِينَ","mereka yang"],["تَدْعُونَ","kamu panggil"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ ۚ","Allah"],["قُل","Katakanlah"],["لَّآ","Tidak"],["أَتَّبِعُ","aku ikut"],["أَهْوَآءَكُمْ ۙ","keinginan (sia-sia) kamu"],["قَدْ","sudah tentu"],["ضَلَلْتُ","Aku akan sesat"],["إِذًۭا","kemudian"],["وَمَآ","dan bukan"],["أَنَا۠","aku (akan)"],["مِنَ","daripada"],["ٱلْمُهْتَدِينَ","orang yang mendapat petunjuk"]]],"846":["(Katakanlah, \"Sesungguhnya aku berada di atas hujah) penjelasan yang nyata (dari Tuhanku dan) ternyata (kamu mendustakannya) mendustakan Tuhanku karena kamu telah menyekutukan-Nya. (Tidak ada padaku apa yang kamu minta supaya disegerakan kedatangannya) yaitu berupa azab. (Tidak lain) tiada lain (menetapkan hukum itu) dalam masalah tersebut dan masalah-masalah lainnya (hanyalah hak Allah. Dia memutuskan) menentukan (yang sebenarnya dan Dia pemberi keputusan yang paling baik.\") pemberi ketentuan hukum yang paling baik. Menurut suatu qiraat dibaca yaqushshu/menerangkan bukannya yaqdhii/memutuskan.",[["قُلْ","Katakanlah"],["إِنِّى","Sesungguhnya aku (adalah)"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّى","Tuhanku"],["وَكَذَّبْتُم","sedangkan kamu menafikan"],["بِهِۦ ۚ","[dengan] itu"],["مَا","Tidak"],["عِندِى","aku ada"],["مَا","apa"],["تَسْتَعْجِلُونَ","kamu berusaha untuk menyegerakan"],["بِهِۦٓ ۚ","daripadanya"],["إِنِ","Tidak"],["ٱلْحُكْمُ","(adalah) keputusannya"],["إِلَّا","kecuali"],["لِلَّهِ ۖ","kerana Allah"],["يَقُصُّ","Dia mengaitkan"],["ٱلْحَقَّ ۖ","kebenaran"],["وَهُوَ","dan Dia"],["خَيْرُ","(adalah) yang terbaik"],["ٱلْفَـٰصِلِينَ","(daripada) Pengambil keputusan"]]],"847":["(Katakanlah) kepada mereka (\"Kalau sekiranya ada padaku apa/azab yang kamu minta supaya disegerakan kedatangannya, tentu telah diselesaikan Allah urusan yang ada antara aku dan kamu) yaitu dengan cara aku menyegerakan azab itu kepadamu, kemudian aku istirahat. Akan tetapi azab itu hanya ada di tangan kekuasaan Allah (Dan Allah lebih mengetahui tentang orang-orang yang lalim.\") di kala Ia mau menghukum mereka.",[["قُل","Katakanlah"],["لَّوْ","Jika"],["أَنَّ","bahawa"],["عِندِى","(ada) dengan aku"],["مَا","apa"],["تَسْتَعْجِلُونَ","kamu berusaha untuk menyegerakan"],["بِهِۦ","daripadanya"],["لَقُضِىَ","pasti telah diputuskan"],["ٱلْأَمْرُ","perkara itu"],["بَيْنِى","antara aku"],["وَبَيْنَكُمْ ۗ","dan antara kamu"],["وَٱللَّهُ","Dan Allah"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلظَّـٰلِمِينَ","daripada orang-orang yang zalim"]]],"848":["(Dan pada sisi Allahlah) Yang Maha Luhur (kunci-kunci semua yang gaib) simpanan-simpanan ilmu gaib atau jalan-jalan yang mengantarkan kepada pengetahuan tentangnya (tak ada yang mengetahuinya kecuali Dia sendiri) ilmu tentang kegaiban itu ada lima macam; mengenai penjelasannya telah dikemukakan dalam surah Luqman ayat 34, yaitu firman-Nya, \"Sesungguhnya Allah hanya pada sisi-Nya sajalah pengetahuan tentang hari kiamat... sampai akhir ayat.\" Demikianlah menurut riwayat Imam Bukhari (dan Dia mengetahui apa) yang terjadi (di daratan) permukaan bumi (dan di lautan) perkampungan-perkampungan yang ada di atas sungai-sungai (dan tiada sehelai daun pun yang gugur) huruf min adalah zaidah/ tambahan (melainkan Dia mengetahuinya pula, dan tidak jatuh sebutir biji pun dalam kegelapan bumi dan tidak sesuatu yang basah atau yang kering) diathafkan kepada Lafal waraqatin (melainkan tertulis dalam kitab yang nyata) yakni Lohmahfuz. Al-Istitsna/pengecualian berkedudukan sebagai badal isytimal dari istitsna yang sebelumnya.",[["۞ وَعِندَهُۥ","Dan dengan Dia"],["مَفَاتِحُ","(adalah) kunci"],["ٱلْغَيْبِ","(dari) yang ghaib"],["لَا","tiada (satu)"],["يَعْلَمُهَآ","mengenali mereka"],["إِلَّا","kecuali"],["هُوَ ۚ","Dia"],["وَيَعْلَمُ","Dan Dia tahu"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلْبَرِّ","bumi"],["وَٱلْبَحْرِ ۚ","dan di dalam laut"],["وَمَا","Dan tidak"],["تَسْقُطُ","jatuh"],["مِن","daripada"],["وَرَقَةٍ","sebarang daun"],["إِلَّا","tetapi"],["يَعْلَمُهَا","Dia tahu"],["وَلَا","Dan tidak"],["حَبَّةٍۢ","sebiji bijirin"],["فِى","dalam"],["ظُلُمَـٰتِ","kegelapan[es]"],["ٱلْأَرْضِ","(dari) bumi"],["وَلَا","dan bukan"],["رَطْبٍۢ","lembab"],["وَلَا","dan bukan"],["يَابِسٍ","kering"],["إِلَّا","tetapi"],["فِى","(berada) dalam"],["كِتَـٰبٍۢ","sebuah Rekod"],["مُّبِينٍۢ","Jelas"]]],"849":["(Dan Dialah yang menidurkan kamu di malam hari) Ia mencabut arwah kamu di kala tidur (dan Dia mengetahui apa yang kamu kerjakan) yang kamu lakukan (pada siang hari kemudian Dia membangunkan kamu pada siang hari) maksudnya dibangunkan kembali pada siang harinya dengan cara mengembalikan arwahmu (untuk disempurnakan ajalmu yang telah ditentukan) yakni batas kehidupan (kemudian kepada Allahlah kamu kembali) melalui kebangkitan (lalu Dia memberitakan kepadamu apa yang dahulu kamu kerjakan) kemudian Ia membalas kamu berdasarkan hal itu.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["يَتَوَفَّىٰكُم","mengambil (jiwa) kamu"],["بِٱلَّيْلِ","menjelang malam"],["وَيَعْلَمُ","dan Dia mengetahui"],["مَا","apa"],["جَرَحْتُم","kamu komited"],["بِٱلنَّهَارِ","menjelang hari"],["ثُمَّ","Kemudian"],["يَبْعَثُكُمْ","Dia membesarkan kamu"],["فِيهِ","di dalamnya"],["لِيُقْضَىٰٓ","supaya itu dipenuhi"],["أَجَلٌۭ","(the) istilah"],["مُّسَمًّۭى ۖ","ditentukan"],["ثُمَّ","Kemudian"],["إِلَيْهِ","kepada-Nya"],["مَرْجِعُكُمْ","akan menjadi kepulangan kamu"],["ثُمَّ","kemudian"],["يُنَبِّئُكُم","Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"850":["(Dan Dialah yang mempunyai kekuasaan tertinggi) kekuasaan yang maha tinggi (di atas semua hamba-Nya dan diutus-Nya kepadamu malaikat-malaikat penjaga) yaitu para malaikat yang mencatat semua amal perbuatanmu (sehingga apabila datang kepada salah seorang di antara kamu kematian, ia diwafatkan) di dalam qiraat lainnya dibaca tawaffahu (oleh utusan-utusan Kami) yakni para malaikat yang ditugaskan untuk mencabut arwah-arwah (dan mereka itu tidak melalaikan kewajibannya) tidak pernah berlaku sembrono terhadap apa yang telah diperintahkan kepada mereka untuk dilakukannya.",[["وَهُوَ","Dan Dia"],["ٱلْقَاهِرُ","(ialah) Penunduk"],["فَوْقَ","atas"],["عِبَادِهِۦ ۖ","hambanya"],["وَيُرْسِلُ","dan Dia menghantar"],["عَلَيْكُمْ","atas kamu"],["حَفَظَةً","penjaga"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءَ","datang"],["أَحَدَكُمُ","(kepada) sesiapa sahaja di antara kamu"],["ٱلْمَوْتُ","kematian itu"],["تَوَفَّتْهُ","ambil dia"],["رُسُلُنَا","utusan kami"],["وَهُمْ","dan mereka"],["لَا","jangan"],["يُفَرِّطُونَ","gagal"]]],"851":["(Kemudian mereka dikembalikan) semua makhluk itu (kepada Allah Penguasa mereka) Yang Memiliki mereka (yang sebenarnya) yang bersifat Maha Adil untuk membalas amal perbuatan mereka. (Ketahuilah bahwa segala hukum pada hari itu kepunyaan-Nya) keputusan yang dilaksanakan atas diri mereka (dan Dialah Pembuat perhitungan yang paling cepat.\") Dia menghisab semua makhluk dalam jangka waktu setengah hari menurut ukuran hari dunia sebagaimana yang telah dijelaskan oleh sebuah hadis mengenai hal ini.",[["ثُمَّ","Kemudian"],["رُدُّوٓا۟","mereka dikembalikan"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["مَوْلَىٰهُمُ","Pelindung mereka"],["ٱلْحَقِّ ۚ","[yang] Benar"],["أَلَا","Tidak dinafikan"],["لَهُ","untuk Dia"],["ٱلْحُكْمُ","(ialah) penghakiman"],["وَهُوَ","Dan Dia"],["أَسْرَعُ","(adalah) paling pantas"],["ٱلْحَـٰسِبِينَ","(dari) orang-orang yang membuat perhitungan"]]],"852":["(Katakanlah,) hai Muhammad kepada penduduk Mekah (\"Siapakah yang dapat menyelamatkanmu dari kegelapan-kegelapan di darat dan di laut) dari bencana-bencananya dalam perjalananmu, yaitu tatkala (kamu berdoa kepada-Nya dengan berendah diri) dengan secara terang-terangan (dengan suara yang lembut) dengan secara sembunyi-sembunyi kamu mengatakan (Sesungguhnya jika) lam menunjukkan qasam/sumpah (Dia menyelamatkan kami) dalam qiraat lainnya dibaca anjaytanaa, yakni Allah (dari ini) maksudnya dari kegelapan dan bencana-bencana ini (tentulah kami menjadi orang-orang yang bersyukur.\") menjadi orang-orang yang beriman.",[["قُلْ","Katakanlah"],["مَن","Siapa"],["يُنَجِّيكُم","menyelamatkan kamu"],["مِّن","daripada"],["ظُلُمَـٰتِ","kegelapan[es]"],["ٱلْبَرِّ","(dari) tanah itu"],["وَٱلْبَحْرِ","dan laut"],["تَدْعُونَهُۥ","kamu panggil Dia"],["تَضَرُّعًۭا","dengan rendah hati"],["وَخُفْيَةًۭ","dan secara rahsia"],["لَّئِنْ","Jika"],["أَنجَىٰنَا","Dia menyelamatkan kita"],["مِنْ","daripada"],["هَـٰذِهِۦ","ini"],["لَنَكُونَنَّ","pasti kita akan jadi"],["مِنَ","daripada"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"853":["(Katakanlah,) kepada mereka (\"Allah menyelamatkan kamu) dibaca dengan takhfif yaitu yunjiikum dan dibaca dengan tasydid yaitu yunajjiikum (daripada bencana itu dan dari segala macam kesusahan) kesulitan yang selain bencana itu (kemudian kamu kembali menyekutukan\")-Nya.",[["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["يُنَجِّيكُم","menyelamatkan kamu"],["مِّنْهَا","daripadanya"],["وَمِن","dan daripada"],["كُلِّ","setiap"],["كَرْبٍۢ","kesusahan"],["ثُمَّ","belum lagi"],["أَنتُمْ","kamu"],["تُشْرِكُونَ","mempersekutukan (dengan Allah)"]]],"854":["(Katakanlah, \"Dialah yang berkuasa untuk mengirimkan azab kepadamu dari atas kamu) dari langit yakni berupa batu-batu dan suara keras yang mengguntur (atau dari bawah kakimu) dengan diamblaskan/ditelan bumi (atau Dia mencampurkan kamu) mencampur-adukkan kamu (menjadi golongan-golongan) kelompok-kelompok yang berbeda keinginannya (dan merasakan kepada sebagian kamu keganasan sebagian yang lain.\") dengan cara saling membunuh. Rasulullah saw. telah bersabda tatkala ayat ini turun, \"Ini lebih ringan dan lebih mudah.\" Akan tetapi tatkala ayat sebelumnya turun Nabi saw. bersabda, \"Aku berlindung kepada Zat-Mu,\" hadis ini diriwayatkan oleh Imam Bukhari. Dan Imam Muslim meriwayatkan tentang sabda Nabi saw., \"Aku memohon kepada Tuhanku agar Ia tidak menjadikan keganasan umatku disebabkan ulah sebagian di antara mereka tetapi Ia melarangku mendoakan hal ini.\" Dan sehubungan dengan hadis pertama, Imam Muslim mengatakan bahwa kejadiannya pasti akan ada hanya saja kenyataannya masih belum terungkapkan. (Perhatikanlah bagaimana Kami menjelaskan) menerangkan kepada mereka (tentang ayat-ayat) yang menunjukkan kepada kekuasaan Kami (barangkali saja mereka mau memahaminya) mereka mau mengetahuinya bahwa apa yang mereka lakukan itu adalah perkara batil.",[["قُلْ","Katakanlah"],["هُوَ","Dia"],["ٱلْقَادِرُ","(adalah) Mampu Semua"],["عَلَىٰٓ","[pada]"],["أَن","kepada"],["يَبْعَثَ","hantar"],["عَلَيْكُمْ","ke atas kamu"],["عَذَابًۭا","hukuman"],["مِّن","daripada"],["فَوْقِكُمْ","di atas kamu"],["أَوْ","atau"],["مِن","daripada"],["تَحْتِ","di bawah"],["أَرْجُلِكُمْ","kaki kamu"],["أَوْ","atau"],["يَلْبِسَكُمْ","(untuk) mengelirukan kamu"],["شِيَعًۭا","(menjadi) mazhab"],["وَيُذِيقَ","dan menjadikan (kamu) rasa"],["بَعْضَكُم","sebahagian daripada kamu"],["بَأْسَ","keganasan"],["بَعْضٍ ۗ","(dari) orang lain"],["ٱنظُرْ","Lihat"],["كَيْفَ","bagaimana"],["نُصَرِّفُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَفْقَهُونَ","faham"]]],"855":["(Dan telah berdusta kepadanya) terhadap Alquran (kaummu padahal Alquran itu adalah hak) yakni benar (Katakanlah,) kepada mereka (\"Aku ini bukanlah orang yang diserahi mengurus urusan kamu.\") kemudian aku membalas kamu; sesungguhnya aku ini hanyalah seorang pemberi peringatan sedangkan mengenai urusanmu hal itu terserah kepada Allah. Ayat ini diturunkan sebelum ada ayat perintah untuk berperang.",[["وَكَذَّبَ","Tetapi dinafikan"],["بِهِۦ","ia"],["قَوْمُكَ","orang kamu"],["وَهُوَ","semasa itu"],["ٱلْحَقُّ ۚ","(adalah) kebenaran"],["قُل","Katakanlah"],["لَّسْتُ","aku tidak"],["عَلَيْكُم","atas kamu"],["بِوَكِيلٍۢ","seorang pengurus"]]],"856":["(Untuk tiap-tiap berita) kabar (ada ketetapannya) yakni waktu kejadiannya dan waktu ketetapannya yang antara lain ialah pengazaban kamu (dan kelak kamu akan mengetahui) sebagai ancaman yang ditujukan kepada mereka.",[["لِّكُلِّ","Untuk setiap"],["نَبَإٍۢ","berita"],["مُّسْتَقَرٌّۭ ۚ","(adalah) masa yang tetap"],["وَسَوْفَ","dan tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"]]],"857":["(Dan apabila melihat orang-orang memperolok-olokkan ayat-ayat Kami) yakni Alquran dengan cemoohan (maka tinggalkanlah mereka) janganlah kamu bergaul dengan mereka (sehingga mereka membicarakan pembicaraan yang lain. Dan jika) Lafal immaa berasal dari in syarthiah yang diidghamkan ke dalam maa zaidah (menjadikan kamu lupa) dengan dibaca yunsiyannaka atau yunassiyannaka (godaan setan) kemudian engkau duduk bersama mereka (maka janganlah kamu duduk sesudah teringat) artinya sesudah engkau teringat akan larangan itu (bersama orang-orang yang lalim itu) ungkapan ini mengandung peletakan isim zahir pada posisi isim mudhmar. Dan orang-orang muslim mengatakan, \"Jika kami berdiri sewaktu mereka mulai memperolok-olokkan ayat-ayat Allah, maka kami tidak bisa lagi duduk di mesjid dan melakukan tawaf di dalamnya,\" lalu turunlah ayat berikut ini:",[["وَإِذَا","Dan apabila"],["رَأَيْتَ","kamu lihat"],["ٱلَّذِينَ","orang yang"],["يَخُوضُونَ","terlibat (dalam ceramah yang sia-sia)"],["فِىٓ","tentang"],["ءَايَـٰتِنَا","Ayat Kami"],["فَأَعْرِضْ","kemudian berpaling"],["عَنْهُمْ","daripada mereka"],["حَتَّىٰ","sehingga"],["يَخُوضُوا۟","mereka terlibat"],["فِى","dalam"],["حَدِيثٍ","ceramah"],["غَيْرِهِۦ ۚ","selainnya"],["وَإِمَّا","Dan jika"],["يُنسِيَنَّكَ","menyebabkan kamu lupa"],["ٱلشَّيْطَـٰنُ","syaitan"],["فَلَا","maka (buat) jangan"],["تَقْعُدْ","duduk"],["بَعْدَ","selepas"],["ٱلذِّكْرَىٰ","peringatan itu"],["مَعَ","dengan"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"858":["(Dan tidak ada atas orang-orang yang bertakwa) kepada Allah (pertanggungjawaban terhadap dosa mereka) orang-orang yang memperolok-olokkan ayat-ayat Allah (barang) sebagai huruf zaidah (sedikit pun) jika orang-orang yang bertakwa itu duduk-duduk dengan mereka (akan tetapi) kewajiban orang-orang yang bertakwa adalah (mengingatkan) memberikan peringatan kepada mereka dan juga nasihat (agar mereka bertakwa) tidak lagi memperolok-olokkan ayat-ayat Allah.",[["وَمَا","Dan tidak"],["عَلَى","(berada) di atas"],["ٱلَّذِينَ","orang yang"],["يَتَّقُونَ","takut (Allah)"],["مِنْ","daripada"],["حِسَابِهِم","akaun mereka"],["مِّن","[daripada]"],["شَىْءٍۢ","sesuatu"],["وَلَـٰكِن","tetapi"],["ذِكْرَىٰ","(untuk) peringatan"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَّقُونَ","takut (Allah)"]]],"859":["(Dan tinggalkanlah) biarkanlah (orang-orang yang menjadikan agama mereka) yang sudah menjadi kewajiban bagi mereka untuk mengamalkannya (sebagai main-main dan senda gurau) oleh sebab mereka mengejek agama (dan mereka telah ditipu oleh kehidupan dunia) maka janganlah engkau menghalang-halangi mereka; ayat ini diturunkan sebelum adanya perintah untuk berperang (Peringatkanlah) berilah nasihat umat manusia itu (dengannya) Alquran (agar) janganlah (setiap diri terjerumus ke dalam neraka) atau ke dalam kebinasaan (karena perbuatannya sendiri) karena amal perbuatannya sendiri (Baginya tidak akan ada selain dari Allah) (sebagai penolong) yang dapat menyelamatkannya (dan tidak pula pemberi syafaat) yang dapat mencegah dirinya dari siksaan neraka. (Dan jika ia menebus dengan segala tebusan) dengan segala macam tebusan (niscaya tidak akan diterima) maksudnya diri mereka tidak dapat ditebus. (Mereka itulah orang-orang yang terjerumus ke dalam neraka disebabkan perbuatan mereka sendiri. Bagi mereka disediakan minuman dari air yang sedang mendidih) yakni air yang sangat panas sekali (dan azab yang pedih) yang sangat menyakitkan (disebabkan kekafiran mereka dahulu) oleh sebab kekafiran mereka.",[["وَذَرِ","Dan pergi"],["ٱلَّذِينَ","orang yang"],["ٱتَّخَذُوا۟","ambil"],["دِينَهُمْ","agama mereka"],["لَعِبًۭا","(sebagai) sandiwara"],["وَلَهْوًۭا","dan keseronokan"],["وَغَرَّتْهُمُ","dan menipu mereka"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["وَذَكِّرْ","Tapi ingatkan"],["بِهِۦٓ","dengannya"],["أَن","jangan-jangan"],["تُبْسَلَ","diserahkan kepada kemusnahan"],["نَفْسٌۢ","sebuah jiwa"],["بِمَا","bagi apa"],["كَسَبَتْ","ia (telah) memperolehi"],["لَيْسَ","tidak"],["لَهَا","(adalah) untuknya"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["وَلِىٌّۭ","mana-mana pelindung"],["وَلَا","dan bukan"],["شَفِيعٌۭ","mana-mana pemberi syafaat"],["وَإِن","Dan jika"],["تَعْدِلْ","ia menawarkan wang tebusan"],["كُلَّ","setiap"],["عَدْلٍۢ","wang tebusan"],["لَّا","tidak"],["يُؤْخَذْ","adakah ia akan diambil"],["مِنْهَآ ۗ","daripadanya"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) mereka yang"],["أُبْسِلُوا۟","diberikan kepada kemusnahan"],["بِمَا","bagi apa"],["كَسَبُوا۟ ۖ","mereka perolehi"],["لَهُمْ","Untuk mereka"],["شَرَابٌۭ","(akan menjadi) minuman"],["مِّنْ","daripada"],["حَمِيمٍۢ","air mendidih"],["وَعَذَابٌ","dan hukuman"],["أَلِيمٌۢ","yang pedih"],["بِمَا","kerana"],["كَانُوا۟","mereka dahulu"],["يَكْفُرُونَ","kufur"]]],"860":["(Katakanlah, \"Apakah kita akan menyeru) apakah kita akan menyembah (selain daripada Allah sesuatu yang tidak dapat mendatangkan kemanfaatan kepada kita) karena menyembahnya (dan tidak pula mendatangkan kemudaratan kepada kita) oleh sebab tidak menyembahnya; yang dimaksud adalah berhala-berhala (dan apakah kita akan dikembalikan ke belakang) dikembalikan kepada kemusyrikan (sesudah Allah memberi petunjuk kepada kita) kepada agama Islam (seperti orang yang digoda) yang disesatkan (oleh setan dipesawangan yang menakutkan dalam keadaan bingung) bingung tidak tahu jalan yang akan ditempuhnya; Lafal ini menjadi hal bagi dhamir ha (dia mempunyai kawan-kawan) teman-teman (yang memanggilnya ke jalan yang lurus) artinya mereka bermaksud memberikan petunjuk jalan yang benar kepadanya kemudian berkata kepadanya: (Marilah ikuti kami.\") akan tetapi ia tidak mengikuti ajakan mereka sehingga binasalah ia dalam kesesatan. Istifham/kata tanya di sini bermakna ingkar dan kalimat yang ada tasybihnya adalah menjadi hal bagi dhamir yang terdapat di dalam Lafal nuraddu (Katakanlah, \"Sesungguhnya petunjuk Allah) yakni agama Islam (ialah sebenar-benar petunjuk) dan yang selain petunjuk-Nya adalah kesesatan belaka (dan kita disuruh agar menyerahkan diri) diperintahkan agar kita berserah diri (kepada Tuhan semesta alam).",[["قُلْ","Katakanlah"],["أَنَدْعُوا۟","Kita panggil"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["يَنفَعُنَا","memberi manfaat kepada kita"],["وَلَا","dan bukan"],["يَضُرُّنَا","memudaratkan kita"],["وَنُرَدُّ","dan kami berpatah balik"],["عَلَىٰٓ","pada"],["أَعْقَابِنَا","tumit kami"],["بَعْدَ","selepas"],["إِذْ","[apabila]"],["هَدَىٰنَا","(telah) membimbing kami"],["ٱللَّهُ","Allah"],["كَٱلَّذِى","Seperti yang satu"],["ٱسْتَهْوَتْهُ","yang (telah) tergoda"],["ٱلشَّيَـٰطِينُ","(oleh) syaitan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["حَيْرَانَ","keliru"],["لَهُۥٓ","dia ada"],["أَصْحَـٰبٌۭ","sahabat"],["يَدْعُونَهُۥٓ","yang memanggilnya"],["إِلَى","ke arah"],["ٱلْهُدَى","bimbingan"],["ٱئْتِنَا ۗ","'Datang kepada kami.'"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["هُدَى","(the) Bimbingan"],["ٱللَّهِ","(milik) Allah"],["هُوَ","ia"],["ٱلْهُدَىٰ ۖ","(adalah) Petunjuk"],["وَأُمِرْنَا","dan kami telah diperintahkan"],["لِنُسْلِمَ","yang kami serahkan"],["لِرَبِّ","kepada (Tuhan)."],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"861":["(dan agar) hendaknya (mendirikan salat dan bertakwa kepada-Nya) Yang Maha Tinggi (dan Dialah Tuhan yang kepada-Nyalah kamu akan dihimpunkan) dikumpulkan kelak di hari kiamat guna menjalani perhitungan amalnya.",[["وَأَنْ","Dan kepada"],["أَقِيمُوا۟","menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَٱتَّقُوهُ ۚ","dan takut kepada-Nya"],["وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang Esa"],["إِلَيْهِ","kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"862":["(Dan Dialah yang menciptakan langit dan bumi dengan benar.) dengan secara hak (Dan) ingatlah (di waktu Dia mengatakan) kepada sesuatu (\"Jadilah,\" lalu terjadilah) pada hari kiamat Allah mengatakan kepada makhluk semua, \"Bangkitlah kamu,\" lalu bangkitlah mereka (yakni perkataan-Nya yang benar) benar terjadi dan sudah pasti (dan di tangan-Nyalah segala kekuasaan di waktu sangkakala ditiup) pada masa malaikat Israfil meniup sangkakalanya yang kedua pada waktu itu tidak ada kekuasaan selain dari kekuasaan-Nya. Pada waktu itu kekuasaan hanya milik-Nya. (Dia mengetahui yang gaib dan yang tampak) apa-apa yang gaib dan apa-apa yang nyata. (Dan Dialah Yang Maha Bijaksana) dalam mengatur makhluk-Nya (lagi Maha Waspada) terhadap rahasia segala sesuatu sama halnya dengan lahiriahnya.",[["وَهُوَ","Dan (ialah) Dia"],["ٱلَّذِى","Siapa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["وَيَوْمَ","Dan (hari) itu"],["يَقُولُ","Dia berkata"],["كُن","Jadilah"],["فَيَكُونُ ۚ","dan ia adalah"],["قَوْلُهُ","firmanNya"],["ٱلْحَقُّ ۚ","(adalah) kebenaran"],["وَلَهُ","Dan untuk Dia"],["ٱلْمُلْكُ","(ialah) Kekuasaan"],["يَوْمَ","(pada) hari"],["يُنفَخُ","akan ditiup"],["فِى","dalam"],["ٱلصُّورِ ۚ","sangkakala"],["عَـٰلِمُ","(Dialah) Yang Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ ۚ","dan yang dilihat"],["وَهُوَ","Dan Dia"],["ٱلْحَكِيمُ","(ialah) Yang Maha Bijaksana"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"863":["(Dan) ingatlah (di waktu Ibrahim berkata kepada bapaknya Azar) julukan dan nama aslinya adalah Tarikh (\"Pantaskah kamu menjadikan patung-patung sebagai tuhan-tuhan?) yang kamu sembah. Kata tanya di sini bermakna celaan. (Sesungguhnya aku melihat kamu dan kaummu) karena menjadikan berhala-berhala sebagai tuhan-tuhan (dalam kesesatan) yakni tersesat dari jalan yang benar (yang nyata.\") yang jelas.",[["۞ وَإِذْ","Dan apabila"],["قَالَ","berkata"],["إِبْرَٰهِيمُ","Ibrahim"],["لِأَبِيهِ","kepada bapanya"],["ءَازَرَ","Azar"],["أَتَتَّخِذُ","Adakah kamu mengambil"],["أَصْنَامًا","berhala"],["ءَالِهَةً ۖ","(sebagai) tuhan"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰكَ","[Aku] jumpa kamu"],["وَقَوْمَكَ","dan rakyatmu"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍۢ","nyata"]]],"864":["(Dan demikianlah) sebagaimana apa yang telah Kami perhatikan kepada Ibrahim, yaitu ia menganggap sesat ayahnya dan kaum ayahnya (Kami perlihatkan kepada Ibrahim kerajaan) kekuasaan (langit dan bumi) agar ia dapat mengambil kesimpulan tentang keesaan-Ku (dan agar dia termasuk orang-orang yang yakin) terhadap tanda-tanda keagungan Kami itu. Jumlah wakadzaalika serta jumlah yang sesudahnya adalah jumlah I`tiradhiah yang diathafkan kepada Lafal qaala.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نُرِىٓ","Kami menunjukkan (ed)"],["إِبْرَٰهِيمَ","Ibrahim"],["مَلَكُوتَ","kerajaan itu"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَلِيَكُونَ","supaya dia menjadi"],["مِنَ","antara"],["ٱلْمُوقِنِينَ","mereka yang pasti"]]],"865":["(Ketika menjadi gelap) menjadi kelam pekat (malam hari atasnya, dia melihat sebuah bintang) menurut suatu pendapat bahwa yang dimaksud adalah bintang Zahrah/Venus (lalu dia berkata) kepada kaumnya yang pada waktu itu menjadi para penyembah bintang-bintang (\"Inilah Tuhanku\") menurut persangkaan kamu (Tetapi tatkala bintang itu tenggelam) surut (dia berkata, \"Saya tidak suka kepada yang tenggelam.\") maksudnya aku tidak suka menjadikannya sebagai tuhan-tuhan sebab tuhan tidak patut mempunyai sifat yang berubah-ubah dan pindah-pindah tempat karena kedua sifat ini hanyalah pantas disandang oleh makhluk-makhluk akan tetapi ternyata cara yang disampaikan oleh Nabi Ibrahim ini tidak mempan pada diri mereka.",[["فَلَمَّا","Maka apabila"],["جَنَّ","bertutup"],["عَلَيْهِ","atas dia"],["ٱلَّيْلُ","malam"],["رَءَا","dia nampak"],["كَوْكَبًۭا ۖ","sebuah bintang"],["قَالَ","Dia berkata"],["هَـٰذَا","Ini"],["رَبِّى ۖ","(ialah) Tuhanku"],["فَلَمَّآ","Tetapi apabila"],["أَفَلَ","ia ditetapkan"],["قَالَ","dia berkata"],["لَآ","Tidak"],["أُحِبُّ","(ada) aku suka"],["ٱلْـَٔافِلِينَ","yang ditetapkan"]]],"866":["(Kemudian tatkala dia melihat bulan terbit) bulan mulai menampakkan sinarnya (dia berkata) kepada mereka (\"Inilah tuhanku.\" Tetapi setelah bulan itu terbenam dia berkata, \"Sesungguhnya jika Tuhanku tidak memberi petunjuk kepadaku) memantapkan hidayah dalam diriku (pastilah aku termasuk orang-orang yang sesat.\") perkataan ini merupakan sindiran Nabi Ibrahim terhadap kaumnya bahwa mereka itu berada dalam kesesatan akan tetapi ternyata apa yang telah dilakukannya itu sedikit pun tidak bermanfaat bagi kaumnya.",[["فَلَمَّا","Apabila"],["رَءَا","dia nampak"],["ٱلْقَمَرَ","bulan"],["بَازِغًۭا","meningkat"],["قَالَ","dia berkata"],["هَـٰذَا","Ini"],["رَبِّى ۖ","(ialah) Tuhanku"],["فَلَمَّآ","Tetapi apabila"],["أَفَلَ","ia ditetapkan"],["قَالَ","dia berkata"],["لَئِن","Jika"],["لَّمْ","tidak"],["يَهْدِنِى","bimbing aku"],["رَبِّى","Tuhanku"],["لَأَكُونَنَّ","Aku pasti akan menjadi"],["مِنَ","antara"],["ٱلْقَوْمِ","manusia"],["ٱلضَّآلِّينَ","yang sesat"]]],"867":["(Kemudian tatkala dia melihat matahari terbit dia berkata, \"Inilah) dhamir dalam Lafal ra-aa dimudzakarkan mengingat khabarnya mudzakkar (Tuhanku ini yang lebih besar.\") daripada bintang dan bulan (maka tatkala matahari itu tenggelam) hujah yang ia sampaikan kepada kaumnya itu cukup kuat dan tidak dapat dibantah lagi oleh mereka (dia berkata, \"Hai kaumku! Sesungguhnya aku berlepas diri dari apa yang kamu persekutukan.\") dari mempersekutukan Allah dengan berhala-berhala dan benda-benda hawadits/baru yang masih membutuhkan kepada yang menciptakannya. Akhirnya kaumnya itu berkata kepadanya, \"Lalu apakah yang engkau sembah?\" Nabi Ibrahim menjawab:",[["فَلَمَّا","Apabila"],["رَءَا","dia nampak"],["ٱلشَّمْسَ","matahari"],["بَازِغَةًۭ","meningkat"],["قَالَ","dia berkata"],["هَـٰذَا","ini (ialah)"],["رَبِّى","Tuhanku"],["هَـٰذَآ","ini (ialah)"],["أَكْبَرُ ۖ","lebih besar"],["فَلَمَّآ","Tetapi apabila"],["أَفَلَتْ","ia ditetapkan"],["قَالَ","dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["إِنِّى","Memang aku"],["بَرِىٓءٌۭ","percuma"],["مِّمَّا","tentang apa"],["تُشْرِكُونَ","kamu mempersekutukan (dengan Allah)"]]],"868":["(\"Sesungguhnya aku menghadapkan diriku) aku menghadapkan diri dengan beribadah (kepada Tuhan yang telah menciptakan) yang telah mewujudkan (langit dan bumi) yaitu Allah swt. (dengan cenderung) meninggalkan semua agama untuk memeluk agama yang benar (dan aku bukanlah termasuk orang-orang yang mempersekutukan.\") Allah.",[["إِنِّى","Sesungguhnya aku"],["وَجَّهْتُ","[Aku] telah berpaling"],["وَجْهِىَ","muka aku"],["لِلَّذِى","kepada Yang Esa"],["فَطَرَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["حَنِيفًۭا ۖ","(sebagai) seorang ahli tauhid yang sebenar"],["وَمَآ","dan bukan"],["أَنَا۠","aku (ada)"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"869":["(Dan dia dibantah oleh kaumnya) ia mendapat sanggahan dari kaumnya mengenai agama yang dipeluknya itu, lalu mereka mengancam dan menakut-nakutinya dengan berhala-berhala mereka, bahwa jika ia tidak menyembah berhala-berhala mereka, ia pasti tertimpa musibah dan kejelekan. (Dia berkata, \"Apakah kamu hendak membantahku) dengan dibaca tasydid huruf nunnya dan dapat juga ditakhfifkan dengan cara membuang salah satu nunnya, yakni nun alamat rafa'nya, demikianlah menurut ulama nahwu. Akan tetapi menurut Imam Farra' yang dibuang adalah nun yang untuk wiqayah. Maknanya ialah: Apakah kamu menyanggah aku? (tentang) keesaan (Allah padahal sesungguhnya Allah telah memberi petunjuk kepadaku.\") Maha Tinggi Allah yang telah memberiku petunjuk kepada keesaan-Nya. (Dan aku tidak takut kepada apa yang kamu persekutukan) dia (dengan Allah) yakni berhala-berhala tersebut; mereka tidak akan dapat menimpakan malapetaka terhadap diriku, sebab mereka tidak mempunyai kekuatan apa-apa (kecuali) melainkan (di kala Tuhanku menghendaki sesuatu dari malapetaka itu) jika Dia hendak menimpakan malapetaka kepadaku, maka hal itu pasti terjadi (Pengetahuan Tuhanku meliputi segala sesuatu). (Maka apakah kamu tidak dapat mengambil pelajaran?) daripadanya kemudian kamu mau beriman.",[["وَحَآجَّهُۥ","Dan berdebat dengannya"],["قَوْمُهُۥ ۚ","umatnya"],["قَالَ","Dia berkata"],["أَتُحَـٰٓجُّوٓنِّى","Adakah kamu berdebat dengan aku"],["فِى","tentang"],["ٱللَّهِ","Allah"],["وَقَدْ","sedangkan pastinya"],["هَدَىٰنِ ۚ","Dia telah membimbing aku"],["وَلَآ","Dan tidak"],["أَخَافُ","(ada) aku takut"],["مَا","apa"],["تُشْرِكُونَ","kamu bergaul"],["بِهِۦٓ","dengan Dia"],["إِلَّآ","melainkan"],["أَن","[bahawa]"],["يَشَآءَ","wasiat"],["رَبِّى","Tuhanku"],["شَيْـًۭٔا ۗ","sesuatu"],["وَسِعَ","merangkumi"],["رَبِّى","Tuhanku"],["كُلَّ","setiap"],["شَىْءٍ","perkara"],["عِلْمًا ۗ","(dalam) pengetahuan"],["أَفَلَا","Kemudian tidak akan"],["تَتَذَكَّرُونَ","kamu ambil iktibar"]]],"870":["(Bagaimana aku takut dengan sesembahan-sesembahan yang kamu persekutukan) dengan Allah sedangkan mereka sama sekali tidak dapat mendatangkan malapetaka dan tidak pula kemanfaatan (padahal kamu tidak takut) kepada Allah (bahwasanya kamu sendiri mempersekutukan Allah) dalam ibadah kamu (dengan sesembahan-sesembahan yang Allah sendiri tidak menurunkan tentangnya) dalam hal menyembahnya (atas kamu suatu hujah pun) untuk mempersekutukan-Nya; yakni suatu alasan dan bukti padahal Allah itu Maha Kuasa atas segala sesuatu. (Maka manakah di antara dua golongan itu yang lebih berhak mendapat keamanan) apakah kami ataukah kamu? (jika kamu mengetahui?) siapakah yang paling berhak untuk mendapatkan keamanan dari malapetaka itu? Yang dimaksud dengan kami adalah Nabi Ibrahim, maka dari itu mengikutlah kamu kepada Ibrahim. Allah berfirman:",[["وَكَيْفَ","Dan bagaimana"],["أَخَافُ","bolehkah aku takut"],["مَآ","apa"],["أَشْرَكْتُمْ","kamu mempersekutukan (dengan Allah)"],["وَلَا","manakala tidak"],["تَخَافُونَ","kamu takut"],["أَنَّكُمْ","bahawa kamu"],["أَشْرَكْتُم","telah dikaitkan"],["بِٱللَّهِ","dengan Allah"],["مَا","apa"],["لَمْ","tidak"],["يُنَزِّلْ","adakah Dia menurunkan"],["بِهِۦ","baginya"],["عَلَيْكُمْ","kepada kamu"],["سُلْطَـٰنًۭا ۚ","mana-mana pihak berkuasa"],["فَأَىُّ","Jadi yang mana"],["ٱلْفَرِيقَيْنِ","(dari) dua pihak"],["أَحَقُّ","mempunyai lebih hak"],["بِٱلْأَمْنِ ۖ","kepada keselamatan"],["إِن","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"871":["(Orang-orang yang beriman dan tidak mencampur-adukkan) tidak mencampurkan (keimanan mereka dengan kelaliman) yakni kemusyrikan demikianlah menurut penafsiran yang tersebutkan di dalam hadis sahih Bukhari dan Muslim (mereka itulah orang-orang yang mendapat keamanan) dari siksaan (dan mereka itu adalah orang-orang yang mendapat petunjuk.)",[["ٱلَّذِينَ","Orang yang"],["ءَامَنُوا۟","beriman"],["وَلَمْ","dan (tidak) tidak"],["يَلْبِسُوٓا۟","campurkan"],["إِيمَـٰنَهُم","kepercayaan mereka"],["بِظُلْمٍ","dengan salah"],["أُو۟لَـٰٓئِكَ","mereka"],["لَهُمُ","bagi mereka"],["ٱلْأَمْنُ","(ialah) keselamatan"],["وَهُم","dan mereka"],["مُّهْتَدُونَ","(adalah) mendapat petunjuk"]]],"872":["(Dan itulah) menjadi mubtada lalu dijelaskan (hujah Kami) yang dijadikan sebagai hujah oleh Nabi Ibrahim untuk membuktikan keesaan Allah; yakni tenggelamnya bintang-bintang itu. Dan jumlah yang sesudahnya menjadi khabar dari tilka (yang Kami berikan kepada Ibrahim) yang Kami tunjukkan kepada Ibrahim sebagai hujah (untuk menghadapi kaumnya. Kami tinggikan siapa yang Kami kehendaki beberapa derajat) dengan dibaca idhafah dan juga dibaca tanwin, yakni dalam masalah ilmu dan hikmah. (Sesungguhnya Tuhanmu Maha Bijaksana) dalam mengatur ciptaan-Nya (lagi Maha Mengetahui) seluk-beluk makhluk-Nya.",[["وَتِلْكَ","Dan ini"],["حُجَّتُنَآ","(ialah) hujah kami"],["ءَاتَيْنَـٰهَآ","Kami memberikannya"],["إِبْرَٰهِيمَ","(kepada) Ibrahim"],["عَلَىٰ","terhadap"],["قَوْمِهِۦ ۚ","umatnya"],["نَرْفَعُ","Kami naikkan"],["دَرَجَـٰتٍۢ","(mengikut) darjah"],["مَّن","yang"],["نَّشَآءُ ۗ","Kami akan"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["حَكِيمٌ","(adalah) Maha Bijaksana"],["عَلِيمٌۭ","Maha Mengetahui"]]],"873":["(Dan Kami telah menganugerahkan Ishak dan Yakub kepadanya) sebagai anaknya (kepada keduanya) kepada masing-masingnya (telah Kami beri petunjuk dan kepada Nuh sebelum itu telah Kami beri petunjuk) sebelum Ibrahim (dan kepada sebagian dari keturunannya) yakni keturunan Nabi Nuh (yaitu Daud dan Sulaiman) Sulaiman anak Daud (Ayub dan Yusuf) anak lelaki Yakub (Musa dan Harun. Demikianlah) seperti mereka yang telah Kami beri pahala (Kami memberi balasan kepada orang-orang yang berbuat baik.)",[["وَوَهَبْنَا","Dan Kami kurniakan"],["لَهُۥٓ","kepadanya"],["إِسْحَـٰقَ","Ishak"],["وَيَعْقُوبَ ۚ","dan Yaqub"],["كُلًّا","semua"],["هَدَيْنَا ۚ","Kami membimbing"],["وَنُوحًا","Dan Nuh"],["هَدَيْنَا","Kami membimbing"],["مِن","daripada"],["قَبْلُ ۖ","sebelum"],["وَمِن","dan daripada"],["ذُرِّيَّتِهِۦ","keturunannya"],["دَاوُۥدَ","Dawood"],["وَسُلَيْمَـٰنَ","dan Sulaiman"],["وَأَيُّوبَ","dan Ayyub"],["وَيُوسُفَ","dan Yusuf"],["وَمُوسَىٰ","dan Musa"],["وَهَـٰرُونَ ۚ","dan Harun"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"874":["(Dan Zakaria, Yahya) yakni anak lelakinya (Isa) anak lelaki Maryam; hal ini menunjukkan bahwa pengertian keturunan itu mencakup juga anak-anak lelaki dari anak perempuan (dan Ilyas) anak lelaki Nabi Harun saudara lelaki Nabi Musa. (Semuanya) mereka itu (termasuk orang-orang yang saleh).",[["وَزَكَرِيَّا","Dan Zakariya"],["وَيَحْيَىٰ","dan Yahya"],["وَعِيسَىٰ","dan Isa"],["وَإِلْيَاسَ ۖ","dan Elia"],["كُلٌّۭ","semua (adalah)"],["مِّنَ","daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"875":["(Dan Ismail) anak lelaki Nabi Ibrahim (Alyasa) huruf lam adalah tambahan, yakni Yasa' (Yunus dan Luth) anak laki-laki Nabi Harun saudara lelaki Nabi Ibrahim (masing-masing) dari mereka itu (Kami lebihkan derajatnya di atas umat manusia) dengan pangkat kenabian.",[["وَإِسْمَـٰعِيلَ","Dan Ismail"],["وَٱلْيَسَعَ","dan Elisa"],["وَيُونُسَ","dan Yunus"],["وَلُوطًۭا ۚ","dan Lut"],["وَكُلًّۭا","dan semua"],["فَضَّلْنَا","Kami lebih suka"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"876":["(Dan Kami lebihkan pula derajat sebagian dari bapak-bapak mereka, keturunan mereka dan saudara-saudara mereka) diathafkan pada Lafal kullan atau nuuhan; dan makna min di sini menunjukkan littab'idh, sebab sebagian dari mereka ada yang tidak mempunyai anak, dan sebagian lainnya ada yang mempunyai anak hanya saja kafir. (Dan Kami memilih mereka) Kami menyeleksi mereka (dan Kami menunjuki mereka ke jalan yang lurus).",[["وَمِنْ","Dan daripada"],["ءَابَآئِهِمْ","bapa mereka"],["وَذُرِّيَّـٰتِهِمْ","dan keturunan mereka"],["وَإِخْوَٰنِهِمْ ۖ","dan saudara-saudara mereka"],["وَٱجْتَبَيْنَـٰهُمْ","dan Kami telah memilih mereka"],["وَهَدَيْنَـٰهُمْ","dan Kami beri petunjuk kepada mereka"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"]]],"877":["(Itulah) agama yang mereka diberi petunjuk kepadanya (petunjuk Allah yang dengannya Dia memberi petunjuk kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya. Seandainya mereka menyekutukan Allah) sebagai perumpamaan saja (niscaya lenyaplah dari mereka amalan yang telah mereka lakukan.)",[["ذَٰلِكَ","Itu"],["هُدَى","(adalah) Hidayah"],["ٱللَّهِ","(milik) Allah"],["يَهْدِى","Dia membimbing"],["بِهِۦ","dengannya"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ ۚ","hambanya"],["وَلَوْ","Tetapi jika"],["أَشْرَكُوا۟","mereka (mempunyai) syirik (dengan Allah)"],["لَحَبِطَ","pasti (akan) tidak berguna"],["عَنْهُم","bagi mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"878":["(Merekah itulah orang-orang yang telah Kami berikan kepada mereka kitab) yakni kitab-kitab (hukum) hikmah (dan kenabian. Jika berlaku ingkar terhadapnya) terhadap tiga hal itu (mereka itu) yaitu penduduk Mekah (maka sesungguhnya Kami akan menyerahkannya) Kami akan memasrahkannya (kepada kaum yang sekali-kali tidak akan mengingkarinya) mereka adalah kaum Muhajirin dan kaum Ansar.",[["أُو۟لَـٰٓئِكَ","Itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["ءَاتَيْنَـٰهُمُ","Kami memberi mereka"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحُكْمَ","dan penghakiman"],["وَٱلنُّبُوَّةَ ۚ","dan kenabian"],["فَإِن","Tetapi jika"],["يَكْفُرْ","kufur"],["بِهَا","di dalamnya"],["هَـٰٓؤُلَآءِ","ini"],["فَقَدْ","maka sesungguhnya"],["وَكَّلْنَا","Kami telah amanahkan"],["بِهَا","ia"],["قَوْمًۭا","(kepada) suatu kaum"],["لَّيْسُوا۟","yang tidak"],["بِهَا","di dalamnya"],["بِكَـٰفِرِينَ","orang kafir"]]],"879":["(Mereka itulah orang-orang yang mendapat petunjuk) yaitu mereka yang mendapat hidayah (Allah, maka petunjuk mereka) jalan mereka seperti mentauhidkan Allah dan bersabar (ikutilah) dengan ha saktah baik dibaca wakaf maupun washal akan tetapi menurut suatu qiraat dibaca tanpa ha saktah jika dibaca washal/dibaca langsung (katakanlah) kepada penduduk Mekah (\"Aku tidak meminta kepadamu dalam menyampaikannya) dimaksud menyampaikan Alquran (suatu upah pun.\") yang kamu berikan upah itu kepadaku (tidak lain ia itu) Alquran itu (hanyalah peringatan) nasihat (untuk segala umat) mencakup umat manusia dan umat jin.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["هَدَى","(telah) mendapat petunjuk"],["ٱللَّهُ ۖ","(oleh) Allah"],["فَبِهُدَىٰهُمُ","begitu juga bimbingan mereka"],["ٱقْتَدِهْ ۗ","kamu ikut"],["قُل","Katakanlah"],["لَّآ","Tidak"],["أَسْـَٔلُكُمْ","aku tanya kamu"],["عَلَيْهِ","baginya"],["أَجْرًا ۖ","sebarang ganjaran"],["إِنْ","Tidak"],["هُوَ","(adalah) ia"],["إِلَّا","tetapi"],["ذِكْرَىٰ","peringatan"],["لِلْعَـٰلَمِينَ","untuk dunia"]]],"880":["(Dan mereka tidak menghormati) orang-orang Yahudi itu (Allah dengan penghormatan yang semestinya) artinya mereka sama sekali tidak mengagungkan-Nya dengan pengagungan yang seharusnya, atau mereka tidak mengetahui-Nya dengan pengetahuan yang semestinya (di kala mereka mengatakan) kepada Nabi saw., yaitu sewaktu mereka mendebat Nabi saw. dalam masalah Alquran (\"Allah tidak menurunkan sesuatu pun kepada manusia.\" Katakanlah,) kepada mereka (\"Siapakah yang menurunkan kitab Taurat yang dibawa oleh Musa sebagai cahaya dan petunjuk bagi manusia, kamu jadikan kitab itu) dengan memakai ya dan ta pada tiga tempat (lembaran-lembaran kertas) kamu menuliskannya pada lembaran-lembaran kertas yang bercerai-berai (kamu perlihatkan sebagiannya) kamu tidak suka menampakkan kesemua isinya (dan kamu sembunyikan sebagian besarnya) sebagian besar dari apa yang terdapat di dalam kandungannya, seperti mengenai ciri-ciri Nabi Muhammad saw. (padahal telah diajarkan kepadamu) hai orang-orang Yahudi di dalam Alquran (apa yang kamu dan bapak-bapak kamu tidak mengetahuinya?\") karena tidak terdapat di dalam kitab Taurat, maka hal itu membuat kamu ragu dan berselisih paham tentang Taurat antara sesamamu. (Katakanlah, \"Allahlah\") yang menurunkannya; jika mereka tidak mengatakannya, maka tidak ada jawaban lain kecuali jawaban itu (kemudian biarkanlah mereka di dalam kesibukan mereka) dalam kebatilan mereka (bermain-main).",[["وَمَا","Dan tidak"],["قَدَرُوا۟","mereka menilai"],["ٱللَّهَ","Allah"],["حَقَّ","(dengan) benar"],["قَدْرِهِۦٓ","penilaiannya"],["إِذْ","apabila"],["قَالُوا۟","mereka berkata"],["مَآ","Tidak"],["أَنزَلَ","didedahkan"],["ٱللَّهُ","(oleh) Allah"],["عَلَىٰ","pada"],["بَشَرٍۢ","seorang manusia"],["مِّن","[daripada]"],["شَىْءٍۢ ۗ","sesuatu"],["قُلْ","Katakanlah"],["مَنْ","Siapa"],["أَنزَلَ","didedahkan"],["ٱلْكِتَـٰبَ","Kitab"],["ٱلَّذِى","yang"],["جَآءَ","dibawa"],["بِهِۦ","[ia]"],["مُوسَىٰ","Musa"],["نُورًۭا","(sebagai) cahaya"],["وَهُدًۭى","dan bimbingan"],["لِّلنَّاسِ ۖ","untuk rakyat"],["تَجْعَلُونَهُۥ","Kamu berjaya"],["قَرَاطِيسَ","(menjadi) perkamen"],["تُبْدُونَهَا","kamu mendedahkan (sebahagian)nya"],["وَتُخْفُونَ","dan kamu sembunyikan"],["كَثِيرًۭا ۖ","banyak (daripadanya)"],["وَعُلِّمْتُم","Dan kamu telah diajar"],["مَّا","apa"],["لَمْ","tidak"],["تَعْلَمُوٓا۟","tahu"],["أَنتُمْ","kamu"],["وَلَآ","dan bukan"],["ءَابَآؤُكُمْ ۖ","nenek moyang kamu"],["قُلِ","Katakanlah"],["ٱللَّهُ ۖ","Allah (menyatakannya)"],["ثُمَّ","Kemudian"],["ذَرْهُمْ","tinggalkan mereka"],["فِى","dalam"],["خَوْضِهِمْ","wacana mereka"],["يَلْعَبُونَ","bermain"]]],"881":["(Dan ini) Alquran ini (adalah kitab yang Kami turunkan yang diberkahi; membenarkan kitab-kitab yang sebelumnya) yaitu kitab-kitab yang diturunkan sebelumnya (dan agar kamu memberi peringatan) dengan memakai ta dan ya diathafkan kepada makna kalimat sebelumnya, yang artinya, Kami menurunkan Alquran untuk diambil keberkahannya, dipercayai dan agar kamu memberi peringatan dengannya (kepada penduduk Umul Qura/Mekah dan orang-orang yang ada disekitarnya) yaitu penduduk kota Mekah dan umat lainnya (dan orang-orang yang beriman kepada adanya kehidupan akhirat tentu beriman kepadanya, dan mereka selalu memelihara salatnya) karena takut akan siksaan akhirat.",[["وَهَـٰذَا","Dan ini"],["كِتَـٰبٌ","(ialah) sebuah Kitab"],["أَنزَلْنَـٰهُ","Kami telah mendedahkannya"],["مُبَارَكٌۭ","diberkati"],["مُّصَدِّقُ","mengesahkan"],["ٱلَّذِى","yang"],["بَيْنَ","(datang) sebelum ini"],["يَدَيْهِ","tangannya"],["وَلِتُنذِرَ","supaya kamu memberi peringatan"],["أُمَّ","(si) ibu"],["ٱلْقُرَىٰ","(dari) bandar-bandar"],["وَمَنْ","dan siapa"],["حَوْلَهَا ۚ","(ada) di sekelilingnya"],["وَٱلَّذِينَ","Dan orang yang"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["يُؤْمِنُونَ","mereka beriman"],["بِهِۦ ۖ","di dalamnya"],["وَهُمْ","dan mereka"],["عَلَىٰ","atas"],["صَلَاتِهِمْ","doa mereka"],["يُحَافِظُونَ","(sedang) menjaga"]]],"882":["(Dan siapakah) maksudnya tidak ada seorang pun (yang lebih lalim daripada orang yang membuat kedustaan terhadap Allah) dengan mengaku menjadi seorang nabi padahal tidak ada yang mengangkatnya menjadi nabi (atau yang berkata, \"Telah diwahyukan kepada saya,\" padahal tidak ada diwahyukan sesuatu pun kepadanya) ayat ini diturunkan berkenaan dengan sikap Musailamah si pendusta itu (dan) lebih aniaya daripada (orang yang berkata, \"Saya akan menurunkan seperti apa yang diturunkan Allah\") mereka adalah orang-orang yang memperolok-olokkan Alquran; mereka mengatakan, bahwa andaikata kami suka niscaya kami pun dapat membuat kata-kata seperti Alquran (dan sekiranya engkau melihat) wahai Muhammad (tatkala orang-orang lalim) yang telah disebutkan tadi (berada dalam sekarat) yaitu sedang menghadapi kematiannya (yakni maut sedangkan para malaikat memukul dengan tangannya) kepada mereka seraya menyiksa lalu para malaikat itu berkata dengan kasar kepada mereka (\"Keluarkanlah nyawamu,\") kepada kami untuk kami cabut. (Di hari ini kamu dibalas dengan siksaan yang sangat menghinakan) sangat merendahkan (karena kamu selalu mengatakan terhadap Allah perkataan yang tidak benar) dengan mengaku menjadi nabi dan berpura-pura diberi wahyu padahal dusta (dan karena kamu selalu menyombongkan diri terhadap ayat-ayat-Nya) kamu merasa tinggi diri tidak mau beriman kepada ayat-ayat-Nya. Jawab dari huruf lau ialah: niscaya engkau akan melihat peristiwa yang mengerikan.",[["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّنِ","daripada (seorang) yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["أَوْ","atau"],["قَالَ","berkata"],["أُوحِىَ","Ia telah diilhamkan"],["إِلَىَّ","kepada aku"],["وَلَمْ","manakala tidak"],["يُوحَ","ia telah diilhamkan"],["إِلَيْهِ","kepadanya"],["شَىْءٌۭ","sesuatu"],["وَمَن","dan (satu) siapa"],["قَالَ","berkata"],["سَأُنزِلُ","Aku akan dedahkan"],["مِثْلَ","suka"],["مَآ","apa"],["أَنزَلَ","(telah) didedahkan"],["ٱللَّهُ ۗ","(oleh) Allah"],["وَلَوْ","Dan jika"],["تَرَىٰٓ","kamu (boleh) lihat"],["إِذِ","apabila"],["ٱلظَّـٰلِمُونَ","orang yang zalim"],["فِى","(ada) dalam"],["غَمَرَٰتِ","penderitaan"],["ٱلْمَوْتِ","(dari) kematian"],["وَٱلْمَلَـٰٓئِكَةُ","manakala Malaikat"],["بَاسِطُوٓا۟","(sedang) meregang"],["أَيْدِيهِمْ","tangan mereka (berkata)"],["أَخْرِجُوٓا۟","Pelepasan"],["أَنفُسَكُمُ ۖ","jiwa kamu"],["ٱلْيَوْمَ","Hari ini"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["عَذَابَ","(dengan) hukuman"],["ٱلْهُونِ","memalukan"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَقُولُونَ","berkata"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["غَيْرَ","selain daripada"],["ٱلْحَقِّ","kebenaran"],["وَكُنتُمْ","dan kamu adalah"],["عَنْ","ke arah"],["ءَايَـٰتِهِۦ","Ayat-ayatNya"],["تَسْتَكْبِرُونَ","bersikap sombong"]]],"883":["(Dan) dikatakan kepada mereka ketika dibangkitkan (sesungguhnya kamu datang kepada Kami sendiri-sendiri) dalam keadaan sendiri-sendiri, terpisah dari keluarga, harta benda dan anak (sebagaimana kamu Kami ciptakan pada mulanya) dalam keadaan telanjang bulat dan masih belum disunatkan (dan kamu tinggalkan apa yang telah Kami berikan kepadamu) apa-apa yang telah Kami anugerahkan kepadamu berupa harta benda (berada di belakangmu) di dunia tanpa ada pilihan lain bagimu. (Dan) dikatakan kepada mereka sebagai cemoohan (Kami tidak melihat besertamu pemberi syafaat kamu) berhala-berhala kamu (yang kamu anggap bahwa mereka di antara kamu) artinya yang berhak kamu sembah (sebagai sekutu-sekutu) Allah. (Sungguh telah terputuslah di antara kamu) pertalian kamu, artinya telah tercerai-berailah persatuanmu. Dan di dalam suatu qiraat dibaca nashab sebagai zharaf; yang artinya telah terputuslah pertalian antara kamu (dan telah lenyap) maksudnya telah hilang (daripada kamu apa yang dahulu kamu anggap) sewaktu hidup di dunia bahwa kamu mendapatkan syafaatnya.",[["وَلَقَدْ","Dan sungguh"],["جِئْتُمُونَا","kamu telah datang kepada Kami"],["فُرَٰدَىٰ","bersendirian"],["كَمَا","seperti"],["خَلَقْنَـٰكُمْ","Kami mencipta kamu"],["أَوَّلَ","(yang) pertama"],["مَرَّةٍۢ","masa"],["وَتَرَكْتُم","dan kamu telah pergi"],["مَّا","apa sahaja"],["خَوَّلْنَـٰكُمْ","Kami menganugerahkan (kepada) kamu"],["وَرَآءَ","belakang"],["ظُهُورِكُمْ ۖ","belakang kamu"],["وَمَا","Dan tidak"],["نَرَىٰ","Kita nampak"],["مَعَكُمْ","bersama kamu"],["شُفَعَآءَكُمُ","pemberi syafaat kamu"],["ٱلَّذِينَ","mereka yang"],["زَعَمْتُمْ","kamu mendakwa"],["أَنَّهُمْ","bahawa mereka (adalah)"],["فِيكُمْ","dalam (urusan) kamu"],["شُرَكَـٰٓؤُا۟ ۚ","sekutu (dengan Allah)"],["لَقَد","Sesungguhnya"],["تَّقَطَّعَ","telah diputuskan (bon)"],["بَيْنَكُمْ","antara kamu"],["وَضَلَّ","dan hilang"],["عَنكُم","daripada kamu"],["مَّا","apa"],["كُنتُمْ","kamu pernah"],["تَزْعُمُونَ","tuntutan"]]],"884":["(Sesungguhnya Allah menumbuhkan) menjadikan (butir) tunas tetumbuhan (dan biji) dari pohon kurma. (Dia mengeluarkan yang hidup dan yang mati) seperti manusia dan unggas yaitu berasal dari air mani dan telur (dan mengeluarkan yang mati) yakni air mani dan telur (dari yang hidup, yang demikian itu) artinya yang menumbuhkan dan yang mengeluarkan (ialah Allah, maka mengapa kamu masih berpaling) mengapa kamu masih berpaling juga dari keimanan padahal bukti-buktinya telah ada.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["فَالِقُ","(ialah) Cleaver"],["ٱلْحَبِّ","(daripada) bijirin"],["وَٱلنَّوَىٰ ۖ","dan biji kurma"],["يُخْرِجُ","Dia melahirkan"],["ٱلْحَىَّ","yang hidup"],["مِنَ","daripada"],["ٱلْمَيِّتِ","yang mati"],["وَمُخْرِجُ","dan melahirkan"],["ٱلْمَيِّتِ","yang mati"],["مِنَ","daripada"],["ٱلْحَىِّ ۚ","yang hidup"],["ذَٰلِكُمُ","Itu"],["ٱللَّهُ ۖ","(ialah) Allah"],["فَأَنَّىٰ","jadi bagaimana"],["تُؤْفَكُونَ","adakah kamu tertipu"]]],"885":["(Dia menyingsingkan pagi) mashdar yang bermakna isim yakni subuh atau pagi hari; artinya Allahlah yang menyingsingkan sinar pagi, yaitu cahaya yang tampak di permulaan pagi hari mengusir kegelapan malam hari (dan menjadikan malam untuk beristirahat) waktu semua makhluk beristirahat dari kepenatannya (dan menjadikan matahari dan bulan) dibaca nashab diathafkan kepada Lafal lail secara makna (untuk perhitungan) untuk ukuran perhitungan waktu; atau dengan tanpa huruf ba atau hisaaban, maka menjadi hal bagi Lafal yang tersimpan. Artinya matahari dan bulan itu beredar menurut perhitungannya sebagaimana yang dijelaskan dalam ayat surah Ar-Rahman. (Itulah) yang telah tersebut itu (ketentuan Allah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) seluk-beluk makhluk-Nya.",[["فَالِقُ","(Dia adalah) Pemangkas"],["ٱلْإِصْبَاحِ","(dari) fajar"],["وَجَعَلَ","dan Dia telah menjadikan"],["ٱلَّيْلَ","malam"],["سَكَنًۭا","(untuk) berehat"],["وَٱلشَّمْسَ","dan matahari"],["وَٱلْقَمَرَ","dan bulan"],["حُسْبَانًۭا ۚ","(untuk) perhitungan"],["ذَٰلِكَ","Itu"],["تَقْدِيرُ","(ialah) menahbiskan"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلْعَلِيمِ","yang Maha Mengetahui"]]],"886":["(Dan Dialah yang menjadikan bintang-bintang bagimu agar kamu menjadikannya sebagai petunjuk dalam kegelapan di darat dan di laut) sewaktu dalam perjalanan (sesungguhnya Kami telah menjelaskan) Kami telah terangkan (tanda-tanda) yang menunjukkan akan kekuasaan Kami (kepada orang-orang yang mengetahui) yakni orang-orang yang mau menggunakan akalnya.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلنُّجُومَ","bintang"],["لِتَهْتَدُوا۟","supaya kamu mendapat petunjuk"],["بِهَا","bersama mereka"],["فِى","dalam"],["ظُلُمَـٰتِ","kegelapan[es]"],["ٱلْبَرِّ","(dari) tanah itu"],["وَٱلْبَحْرِ ۗ","dan laut"],["قَدْ","Sungguh"],["فَصَّلْنَا","Kami telah menjelaskan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","bagi kaum"],["يَعْلَمُونَ","(siapa) tahu"]]],"887":["(Dan Dialah yang menciptakan kamu) maksudnya yang mengadakan kamu (dari seorang diri) yaitu Nabi Adam (maka ada tempat tetap) bagimu di dalam rahim (dan tempat simpanan) bagimu di dalam tulang rusuk. Dalam suatu qiraat huruf qaf dibaca fatah; yang artinya tempat menetap kamu. (Sesungguhnya telah kami jelaskan tanda-tanda kebesaran Kami kepada orang-orang yang mengerti) tentang apa yang dikatakan kepada mereka.",[["وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنشَأَكُم","(telah) melahirkan kamu"],["مِّن","daripada"],["نَّفْسٍۢ","sebuah jiwa"],["وَٰحِدَةٍۢ","bujang"],["فَمُسْتَقَرٌّۭ","maka (ada) tempat kediaman"],["وَمُسْتَوْدَعٌۭ ۗ","dan tempat berehat"],["قَدْ","Sungguh"],["فَصَّلْنَا","Kami telah menjelaskan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","bagi kaum"],["يَفْقَهُونَ","(yang) faham"]]],"888":["(Dan Dialah yang menurunkan air hujan dari langit, lalu Kami tumbuhkan) dalam ayat ini terkandung iltifat dari orang yang ketiga menjadi pembicara (dengan air itu) yakni dengan air hujan itu (segala macam tumbuh-tumbuhan) yang dapat tumbuh (maka Kami keluarkan darinya) dari tumbuh-tumbuhan itu sesuatu (tanaman yang hijau) yang menghijau (Kami keluarkan darinya) dari tanaman yang menghijau itu (butir yang banyak) yang satu sama lainnya bersusun seperti bulir-bulir gandum dan sejenisnya (dan dari pohon kurma) menjadi khabar dan dijadikan sebagai mubdal minhu (yaitu dari mayangnya) yaitu dari pucuk pohonnya; dan mubtadanya ialah (keluar tangkai-tangkainya) tunas-tunas buahnya (yang mengurai) saling berdekatan antara yang satu dengan yang lainnya (dan) Kami tumbuhkan berkat air hujan itu (kebun-kebun) tanaman-tanaman (anggur, zaitun dan delima yang serupa) dedaunannya; menjadi hal (dan yang tidak serupa) buahnya (perhatikanlah) hai orang-orang yang diajak bicara dengan perhatian yang disertai pemikiran dan pertimbangan (buahnya) dengan dibaca fathah huruf tsa dan huruf mimnya, atau dibaca dhammah keduanya sebagai kata jamak dari tsamrah; perihalnya sama dengan kata syajaratun jamaknya syajarun, dan khasyabatun jamaknya khasyabun (di waktu pohonnya berbuah) pada awal munculnya buah; bagaimana keadaannya? (dan) kepada (kematangannya) artinya kemasakannya, yaitu apabila telah masak; bagaimana keadaannya. (Sesungguhnya yang demikian itu ada tanda-tanda) yang menunjukkan kepada kekuasaan Allah swt. dalam menghidupkan kembali yang telah mati dan lain sebagainya (bagi orang-orang yang beriman) mereka disebut secara khusus sebab hanya merekalah yang dapat memanfaatkan hal ini untuk keimanan mereka, berbeda dengan orang-orang kafir.",[["وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنزَلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَخْرَجْنَا","kemudian Kami lahirkan"],["بِهِۦ","dengannya"],["نَبَاتَ","tumbuh-tumbuhan"],["كُلِّ","(daripada) setiap"],["شَىْءٍۢ","perkara"],["فَأَخْرَجْنَا","Kemudian Kami lahirkan"],["مِنْهُ","daripadanya"],["خَضِرًۭا","tumbuhan hijau"],["نُّخْرِجُ","Kami melahirkan"],["مِنْهُ","daripadanya"],["حَبًّۭا","bijirin"],["مُّتَرَاكِبًۭا","tebal berkelompok"],["وَمِنَ","Dan daripada"],["ٱلنَّخْلِ","pokok kurma"],["مِن","daripada"],["طَلْعِهَا","spathenya"],["قِنْوَانٌۭ","gugusan kurma"],["دَانِيَةٌۭ","tergantung rendah"],["وَجَنَّـٰتٍۢ","Dan taman-taman"],["مِّنْ","daripada"],["أَعْنَابٍۢ","buah anggur"],["وَٱلزَّيْتُونَ","dan buah zaitun"],["وَٱلرُّمَّانَ","dan buah delima"],["مُشْتَبِهًۭا","menyerupai"],["وَغَيْرَ","dan bukan"],["مُتَشَـٰبِهٍ ۗ","menyerupai"],["ٱنظُرُوٓا۟","Tengok"],["إِلَىٰ","di"],["ثَمَرِهِۦٓ","buahnya"],["إِذَآ","apabila"],["أَثْمَرَ","ia membuahkan hasil"],["وَيَنْعِهِۦٓ ۚ","dan pematangannya"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكُمْ","bahawa"],["لَـَٔايَـٰتٍۢ","(adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","(yang) beriman"]]],"889":["(Dan mereka menjadikan di samping Allah) menjadi maf'ul tsani (sekutu-sekutu) menjadi maf'ul awal dan menjadi mubdal minhu (terdiri dari jin) yang mereka menaatinya dalam menyembah berhala-berhala (dan) padahal (Allahlah yang telah menciptakan mereka) lalu mengapa mereka menjadikannya sebagai sekutu-sekutu-Nya (dan mereka membohong) dengan dibaca takhfif dan tasydid; artinya mereka membuat-buat perkataan (bahwanya Allah mempunyai anak laki-laki dan perempuan, tanpa landasan ilmu pengetahuan) mereka telah mengatakan, bahwa Uzair adalah anak lelaki Allah, dan malaikat-malaikat itu adalah anak-anak perempuan Allah. (Maha Suci Allah) yakni sebagai ungkapan menyucikan-Nya (dan Maha Tinggi dari sifat-sifat yang mereka berikan) mengenai diri-Nya, yaitu mempunyai anak.",[["وَجَعَلُوا۟","Dan mereka buat"],["لِلَّهِ","dengan Allah"],["شُرَكَآءَ","rakan kongsi"],["ٱلْجِنَّ","jin"],["وَخَلَقَهُمْ ۖ","walaupun Dia telah menciptakan mereka"],["وَخَرَقُوا۟","dan mereka mendustakan"],["لَهُۥ","kepada-Nya"],["بَنِينَ","anak lelaki"],["وَبَنَـٰتٍۭ","dan anak perempuan"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ ۚ","pengetahuan"],["سُبْحَـٰنَهُۥ","Maha Suci Dia"],["وَتَعَـٰلَىٰ","dan Maha Tinggi"],["عَمَّا","atas apa"],["يَصِفُونَ","mereka sifatkan"]]],"890":["(Dia Pencipta langit dan bumi) yang menciptakan keduanya tanpa ada contoh yang mendahuluinya. (Bagaimana) mengapa (Dia dikatakan mempunyai anak padahal Dia tidak mempunyai istri?) yakni teman hidup. (Dia menciptakan segala sesuatu) maksudnya Dialah yang menciptakan kesemuanya (dan Dia mengetahui segala sesuatu).",[["بَدِيعُ","Pemula"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["أَنَّىٰ","Bagaimana"],["يَكُونُ","boleh jadi"],["لَهُۥ","untuk Dia"],["وَلَدٌۭ","seorang anak lelaki"],["وَلَمْ","manakala tidak"],["تَكُن","(ada) ada"],["لَّهُۥ","untuk Dia"],["صَـٰحِبَةٌۭ ۖ","seorang peneman"],["وَخَلَقَ","dan Dia menciptakan"],["كُلَّ","setiap"],["شَىْءٍۢ ۖ","perkara"],["وَهُوَ","Dan Dia"],["بِكُلِّ","(adalah) setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","Maha Mengetahui"]]],"891":["(Demikian itu ialah Allah Tuhan kamu; tidak ada Tuhan selain Dia; pencipta segala sesuatu, maka sembahlah Dia) esakanlah Dia (dan Dia adalah pemelihara segala sesuatu) yang memelihara semuanya.",[["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمْ ۖ","Tuhanmu"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["خَـٰلِقُ","(the) Pencipta"],["كُلِّ","(daripada) setiap"],["شَىْءٍۢ","perkara"],["فَٱعْبُدُوهُ ۚ","maka sembahlah Dia"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["وَكِيلٌۭ","seorang Penjaga"]]],"892":["(Dia tidak dapat dicapai oleh penglihatan mata) artinya engkau tidak akan dapat melihat-Nya sebab hal ini hanya khusus untuk kaum mukminin kelak di akhirat sebagaimana yang diungkapkan dalam firman-Nya surah Al-Qiyamah ayat 22-23 yaitu, \"Wajah-wajah orang-orang mukmin pada hari itu berseri-seri. Kepada Tuhannya mereka melihat.\" Dijelaskan pula dalam hadis yang diriwayatkan oleh Bukhari dan Muslim yaitu, \"Sesungguhnya kamu itu akan melihat Tuhanmu kelak di akhirat sebagaimana kamu melihat bulan pada malam purnama.\" Ada penafsiran lain yang mengatakan, bahwa yang dimaksud ialah bahwa pandangan mata itu tidak akan dapat meliputi-Nya (sedangkan Dia dapat melihat segala yang kelihatan) yakni Dia dapat melihatnya sedangkan apa-apa yang terlihat itu tidak dapat melihat-Nya; dan tiada selain-Nya mempunyai sifat ini (dan Dialah Yang Maha Lembut) terhadap kekasih-kekasih-Nya (lagi Maha Waspada) terhadap mereka.",[["لَّا","Tidak (boleh)"],["تُدْرِكُهُ","genggam Dia"],["ٱلْأَبْصَـٰرُ","penglihatan"],["وَهُوَ","tetapi Dia"],["يُدْرِكُ","(boleh) genggam"],["ٱلْأَبْصَـٰرَ ۖ","(semua) penglihatan"],["وَهُوَ","dan Dia (adalah)"],["ٱللَّطِيفُ","yang Maha Halus"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"893":["Katakanlah olehmu hai Muhammad kepada mereka (Sesungguhnya telah datang kepadamu bukti-bukti) hujah-hujah (dari Tuhanmu; maka siapa melihat) bukti-bukti kebenaran itu, lalu ia mau beriman kepadanya (maka manfaatnya bagi dirinya sendiri) sebab pahalanya dia sendirilah yang merasakannya sebagai imbalan dari maunya dia melihat bukti-bukti itu (dan siapa buta) tidak mau melihat kebenaran itu sehingga ia menjadi sesat (maka kemudaratannya kembali kepada dirinya) yakni malapetaka dari kesesatannya itu. (Dan aku, Muhammad, sekali-kali bukanlah pemeliharamu) yang selalu mengawasi amal perbuatanmu karena sesungguhnya aku ini hanyalah seorang pemberi peringatan.",[["قَدْ","Sesungguhnya"],["جَآءَكُم","telah datang kepada kamu"],["بَصَآئِرُ","pencerahan"],["مِن","daripada"],["رَّبِّكُمْ ۖ","Tuhanmu"],["فَمَنْ","Kemudian sesiapa sahaja"],["أَبْصَرَ","nampak"],["فَلِنَفْسِهِۦ ۖ","maka (itu) untuk jiwanya"],["وَمَنْ","dan sesiapa"],["عَمِىَ","(adalah) buta"],["فَعَلَيْهَا ۚ","maka (ia) terhadap dirinya sendiri"],["وَمَآ","Dan tidak"],["أَنَا۠","(aku) aku"],["عَلَيْكُم","atas kamu"],["بِحَفِيظٍۢ","seorang penjaga"]]],"894":["(Demikianlah) sebagaimana yang telah Kami jelaskan di atas (Kami menjelaskan) Kami terangkan (ayat-ayat itu) agar mereka mau berpikir tentangnya (dan supaya mereka mengatakan) yaitu orang-orang musyrik mengenai akibat dari perkara ini (\"Kamu telah mempelajari.\") engkau telah mempelajari tentang ahli kitab; dan menurut qiraat lainnya ditafsirkan bahwa engkau telah mempelajari kitab-kitab orang-orang terdahulu kemudian engkau mendatangkan ayat-ayat ini berdasarkan sumber darinya (dan supaya Kami menjelaskan Alquran itu kepada orang-orang yang mengetahui).",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نُصَرِّفُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["وَلِيَقُولُوا۟","yang mereka (boleh) katakan"],["دَرَسْتَ","Kamu telah belajar"],["وَلِنُبَيِّنَهُۥ","dan supaya Kami menerangkannya"],["لِقَوْمٍۢ","bagi kaum"],["يَعْلَمُونَ","siapa tahu"]]],"895":["(Ikutilah apa yang telah diwahyukan kepadamu dari Tuhanmu) yakni Alquran (tidak ada tuhan selain Dia dan berpalinglah dari orang-orang musyrik.)",[["ٱتَّبِعْ","Ikut"],["مَآ","apa"],["أُوحِىَ","telah diilhamkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ ۖ","Tuhanmu"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["وَأَعْرِضْ","dan berpaling"],["عَنِ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"896":["(Dan jika Allah menghendaki niscaya mereka tidak mempersekutukan-Nya. Dan Kami tidak menjadikan kamu pemelihara bagi mereka) sebagai pengawas yang oleh sebabnya engkau membalas mereka atas amal-amal yang mereka lakukan (dan kamu sekali-kali bukanlah pemelihara bagi mereka) yang oleh sebabnya engkau memaksa mereka untuk beriman. Ayat ini diturunkan sebelum adanya perintah untuk berperang.",[["وَلَوْ","Dan jika"],["شَآءَ","(telah) berkehendak"],["ٱللَّهُ","Allah"],["مَآ","tidak (mereka akan mempunyai)"],["أَشْرَكُوا۟ ۗ","sekutu-sekutu (dengan-Nya)"],["وَمَا","Dan tidak"],["جَعَلْنَـٰكَ","Kami telah membuat kamu"],["عَلَيْهِمْ","atas mereka"],["حَفِيظًۭا ۖ","seorang penjaga"],["وَمَآ","dan bukan"],["أَنتَ","kamu"],["عَلَيْهِم","(berada) atas mereka"],["بِوَكِيلٍۢ","seorang pengurus"]]],"897":["(Dan janganlah kamu memaki sesembahan-sesembahan yang mereka puja) yaitu berhala-berhala (selain Allah) yaitu berhala-berhala yang mereka sembah (karena mereka akan memaki Allah dengan melampaui batas) penuh dengan perasaan permusuhan dan kelaliman (tanpa pengetahuan) karena mereka tidak mengerti tentang Allah (Demikianlah) sebagaimana yang telah Kami jadikan sebagai perhiasan pada diri mereka yaitu amal perbuatan mereka (Kami jadikan setiap umat menganggap baik pekerjaan mereka) berupa pekerjaan yang baik dan pekerjaan yang buruk yang biasa mereka lakukan. (Kemudian kepada Tuhanlah mereka kembali) di akhirat kelak (lalu Dia memberikan kepada mereka apa yang dahulu mereka lakukan) kemudian Dia memberikan balasannya kepada mereka.",[["وَلَا","Dan jangan"],["تَسُبُّوا۟","menghina"],["ٱلَّذِينَ","mereka yang"],["يَدْعُونَ","mereka menyeru"],["مِن","daripada"],["دُونِ","selain daripada"],["ٱللَّهِ","Allah"],["فَيَسُبُّوا۟","supaya mereka tidak menghina"],["ٱللَّهَ","Allah"],["عَدْوًۢا","(dalam) permusuhan"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ ۗ","pengetahuan"],["كَذَٰلِكَ","Demikianlah"],["زَيَّنَّا","Kami telah membuat seolah-olah adil"],["لِكُلِّ","kepada setiap"],["أُمَّةٍ","masyarakat"],["عَمَلَهُمْ","perbuatan mereka"],["ثُمَّ","Kemudian"],["إِلَىٰ","kepada"],["رَبِّهِم","Tuhan mereka"],["مَّرْجِعُهُمْ","(adalah) kepulangan mereka"],["فَيُنَبِّئُهُم","kemudian Dia akan memberitahu mereka"],["بِمَا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"898":["(Mereka bersumpah) orang-orang kafir penduduk Mekah (dengan nama Allah dengan segala kesungguhan) dengan segala kesungguhan yang ada pada mereka dalam hal bersumpah (bahwa sungguh jika datang kepada mereka sesuatu mukjizat) sesuai dengan apa yang mereka minta (pastilah mereka beriman kepada mukjizat tersebut. Katakanlah) kepada mereka (\"Sesungguhnya mukjizat-mukjizat itu hanya berada di sisi Allah.\") Dialah yang akan menurunkan sesuai dengan apa yang dikehendaki-Nya karena sesungguhnya aku hanya seorang pemberi peringatan (dan apakah yang memberitahukan kepadamu) yang membuat kamu tentang keimanan mereka apabila mukjizat-mukjizat itu didatangkan; artinya kamu tidak akan mengetahui hal itu (bahwa apabila mukjizat itu datang mereka tidak akan beriman) berkat pengetahuan-Ku yang telah waspada sebelumnya. Dan menurut suatu qiraat memakai ta yakni tu`minuuna yang berarti khithab ayat ditujukan kepada orang-orang kafir. Menurut qiraat lainnya dibaca annahaa yang maknanya sinonim dengan Lafal la`alla atau menjadi ma'mul dari `amil sebelumnya.",[["وَأَقْسَمُوا۟","Dan mereka bersumpah"],["بِٱللَّهِ","oleh Allah"],["جَهْدَ","terkuat"],["أَيْمَـٰنِهِمْ","(dari) sumpah mereka"],["لَئِن","bahawa jika"],["جَآءَتْهُمْ","datang kepada mereka"],["ءَايَةٌۭ","satu tanda"],["لَّيُؤْمِنُنَّ","mereka pasti akan beriman"],["بِهَا ۚ","di dalamnya"],["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["ٱلْـَٔايَـٰتُ","tanda-tanda"],["عِندَ","(ada) dengan"],["ٱللَّهِ ۖ","Allah"],["وَمَا","Dan apa"],["يُشْعِرُكُمْ","akan membuat kamu memahami"],["أَنَّهَآ","bahawa [itu]"],["إِذَا","apabila"],["جَآءَتْ","ia datang"],["لَا","tidak"],["يُؤْمِنُونَ","mereka akan beriman"]]],"899":["(Dan Kami memalingkan hati mereka) Kami menyimpangkan hati mereka dari perkara yang hak sehingga mereka sama sekali tidak mengerti mengenai kebenaran (dan penglihatan mereka) dari perkara yang hak tersebut sehingga mereka tidak dapat melihatnya dan pula tidak mau beriman kepadanya (seperti mereka belum pernah beriman kepadanya) artinya kepada ayat-ayat yang telah diturunkan (pada permulaannya dan Kami biarkan mereka) Kami tinggalkan mereka (di dalam lewat batas mereka) yaitu kesesatan mereka (menggelimangkan dirinya) sehingga bolak-balik dalam keadaan bingung.",[["وَنُقَلِّبُ","Dan Kami akan berpaling"],["أَفْـِٔدَتَهُمْ","hati mereka"],["وَأَبْصَـٰرَهُمْ","dan pemandangan mereka"],["كَمَا","(hanya) sebagai"],["لَمْ","tidak"],["يُؤْمِنُوا۟","mereka beriman"],["بِهِۦٓ","di dalamnya"],["أَوَّلَ","(yang) pertama"],["مَرَّةٍۢ","masa"],["وَنَذَرُهُمْ","Dan Kami akan meninggalkan mereka"],["فِى","dalam"],["طُغْيَـٰنِهِمْ","pelanggaran mereka"],["يَعْمَهُونَ","merayau buta"]]]});